	TEACHER      = char("ครูฝ่ายปกครองไม้เรียว", 4, 5, 7, "Sati", "Epic", { "Necro" }, "เรียกชื่อเต็มเมื่อไหร่ ศพยังต้องลุก"),
	KARAOKE      = char("นักร้องคาราโอเกะเสียงหลง", 4, 6, 6, "Muen", "Epic", { "Unlucky" }, "ร้องผิดคีย์ทั้งเพลง แต่มั่นใจเต็มร้อย"),
