	FROZEN_FISH     = weapon("ปลาทูแช่แข็ง", 3, "Rare", 4, true, "ATK +4 / ดาเมจ 4 + แช่แข็ง", "แข็งกว่าใจแฟนเก่า"),
	BROKEN_UMBRELLA = weapon("ร่มเทพเจ้า (ร่มหัก)", 4, "Epic", 8, false, "สวม: ATK +8 / ปา: ดาเมจ 8", "หักตั้งแต่ซื้อ แต่ยังศักดิ์สิทธิ์"),

