SOURCES["ReplicatedStorage/Shared/Rules.lua"] = [[
-- ReplicatedStorage/Shared/Rules (ModuleScript)
local Config = require(script.Parent:WaitForChild("Config"))
local Rules = {}

Rules.Beats = { Sati = "Biao", Biao = "Muen", Muen = "Sati" }
Rules.Keywords = { Rush = true, Taunt = true, Necro = true, Unlucky = true, Steal = true }

function Rules.HasKeyword(card, kw)
	return card ~= nil and card.Keywords ~= nil and table.find(card.Keywords, kw) ~= nil
end

function Rules.HasTaunt(field)
	for _, c in field do
		if Rules.HasKeyword(c, "Taunt") then return true end
	end
	return false
end

-- Board = ตัวละคร, Weapon = สวม/ปา, None = ไม่ต้องเลือก, EnemyChar / AllyChar / Ally
function Rules.TargetType(card)
	if card.Type == "Character" then return "Board" end
	if card.Type == "Weapon" then return "Weapon" end
	return (card.Effect and card.Effect.Target) or "None"
end

function Rules.GateCost(card)
	return math.max(0, (card.Cost or 0) - Config.GATE_DISCOUNT)
end

return Rules]]
SOURCES["ReplicatedStorage/Shared/UI/CardInspector.lua"] = [[
-- ReplicatedStorage/Shared/UI/CardInspector (ModuleScript)
-- หน้าดูการ์ดแบบเต็ม: ใช้ได้ทุกเมนู ทุกสถานะ (ScreenGui แยก DisplayOrder 1000 = อยู่บนสุดเสมอ)
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")

local Theme = require(script.Parent.Theme)
local UIKit = require(script.Parent.UIKit)
local CardView = require(script.Parent.CardView)
local CardData = require(script.Parent.Parent.CardData)

local CardInspector = {}
local CENTER = Vector2.new(0.5, 0.5)
local INSPECT_KEY = Enum.KeyCode.F

local gui
local ui = {}
local isOpen = false
local shown = nil
local list, index = nil, 1
local bigView = nil
local T = 18
local hovered = nil
local tracked = setmetatable({}, { __mode = "k" })

local function esc(s)
	s = tostring(s or "")
	s = s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
	return s
end

local function statText(now, baseVal)
	if typeof(baseVal) ~= "number" or now == baseVal then return tostring(now) end
	return ("%s %s (เดิม %s)"):format(tostring(now), now > baseVal and "▲" or "▼", tostring(baseVal))
end

local function text(parent, order, str, size, color, font)
	return UIKit.new("TextLabel", {
		Name = "Text", LayoutOrder = order, BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
		Font = font or Theme.FontBody, RichText = true, Text = str,
		TextSize = size or T, TextColor3 = color or Theme.Color.Outline,
		TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = parent,
	})
end

local function row(parent, order)
	return UIKit.new("Frame", {
		Name = "Row", LayoutOrder = order, BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = parent,
	}, {
		UIKit.new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal, Wraps = true,
			Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})
end

local function chip(parent, str, color)
	return UIKit.new("TextLabel", {
		Name = "Chip", BackgroundColor3 = color, Size = UDim2.new(0, 0, 0, T + 16),
		AutomaticSize = Enum.AutomaticSize.X, Font = Theme.Font, Text = str,
		TextSize = T, TextColor3 = Color3.new(1, 1, 1), Parent = parent,
	}, {
		UIKit.corner(UDim.new(0.5, 0)),
		UIKit.new("UIStroke", { Thickness = 2, Color = Theme.Color.Outline }),
		UIKit.new("UIStroke", { Thickness = 2, Color = Theme.Color.Outline, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }),
		UIKit.new("UIPadding", { PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }),
	})
end

local function section(parent, order, title, color)
	local box = UIKit.new("Frame", {
		Name = "Section", LayoutOrder = order, BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.3,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = parent,
	}, {
		UIKit.corner(UDim.new(0, 12)),
		UIKit.new("UIStroke", { Thickness = 2, Color = color, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }),
		UIKit.new("UIPadding", {
			PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 10),
			PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
		}),
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
	})
	text(box, 0, "<b>" .. title .. "</b>", T, color)
	return box
end

local function build()
	gui = UIKit.new("ScreenGui", {
		Name = "CardInspector", DisplayOrder = 1000, ResetOnSpawn = false, IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Enabled = false,
		Parent = Players.LocalPlayer:WaitForChild("PlayerGui"),
	})
	ui.dim = UIKit.new("TextButton", {
		Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1,
		Text = "", AutoButtonColor = false, Parent = gui,
	})
	ui.dim.Activated:Connect(function() CardInspector.Close() end)

	-- TextButton = กันคลิกบนกล่องทะลุไปปิดหน้าต่าง
	ui.box = UIKit.new("TextButton", {
		Text = "", AutoButtonColor = false, Size = UDim2.fromScale(0.88, 0.82),
		Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		BackgroundColor3 = Theme.Color.Panel, Parent = ui.dim,
	}, {
		UIKit.corner(UDim.new(0.04, 0)),
		UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1.75 }),
	})
	ui.stroke = UIKit.stroke(nil, 5)
	ui.stroke.Parent = ui.box
	ui.scale = UIKit.new("UIScale", { Parent = ui.box })

	-- ซ้าย: แสงตามความหายาก + การ์ดใบใหญ่
	ui.left = UIKit.new("Frame", {
		Size = UDim2.fromScale(0.38, 0.9), Position = UDim2.fromScale(0.025, 0.05),
		BackgroundTransparency = 0.55, Parent = ui.box,
	}, {
		UIKit.corner(UDim.new(0.06, 0)),
		UIKit.new("UIGradient", {
			Rotation = 90,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 0.9),
			}),
		}),
	})

	-- ขวา: ข้อมูลทั้งหมด (เลื่อนได้ ยาวแค่ไหนก็ไม่โดนตัด)
	ui.info = UIKit.new("ScrollingFrame", {
		Size = UDim2.fromScale(0.54, 0.76), Position = UDim2.fromScale(0.43, 0.06),
		BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 6,
		ScrollBarImageColor3 = Theme.Color.Outline, CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
		Parent = ui.box,
	}, {
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingRight = UDim.new(0, 12), PaddingTop = UDim.new(0, 4) }),
	})

	ui.prev = UIKit.button({
		Text = "◀", Color = Theme.Color.Blue, Size = UDim2.fromScale(0.07, 0.1),
		Position = UDim2.fromScale(0.43, 0.95), AnchorPoint = Vector2.new(0, 1), Parent = ui.box,
		OnClick = function() CardInspector.Step(-1) end,
	})
	ui.next = UIKit.button({
		Text = "▶", Color = Theme.Color.Blue, Size = UDim2.fromScale(0.07, 0.1),
		Position = UDim2.fromScale(0.97, 0.95), AnchorPoint = Vector2.new(1, 1), Parent = ui.box,
		OnClick = function() CardInspector.Step(1) end,
	})
	ui.counter = UIKit.label({
		Text = "", Size = UDim2.fromScale(0.3, 0.07), Position = UDim2.fromScale(0.7, 0.935),
		AnchorPoint = Vector2.new(0.5, 1), Parent = ui.box,
	})
	local close = UIKit.button({
		Text = "✖", Color = Theme.Color.Red, Size = UDim2.fromScale(0.05, 0.09),
		Position = UDim2.fromScale(1, 0), AnchorPoint = Vector2.new(0.6, 0.4), Parent = ui.box,
		OnClick = function() CardInspector.Close() end,
	})
	UIKit.new("UIAspectRatioConstraint", { Parent = close })

	UIKit.label({
		Text = "คลิกพื้นหลัง / F / B = ปิด   •   ◀ ▶ / Q E / LB RB = เปลี่ยนใบ",
		Font = Theme.FontBody, Size = UDim2.fromScale(0.8, 0.035),
		Position = UDim2.fromScale(0.5, 0.985), AnchorPoint = Vector2.new(0.5, 1), Parent = ui.dim,
	})
end

local function show(card, quiet)
	shown = card
	local base = card.Id and CardData[card.Id] or nil
	local accent = card.Rarity == "Mystic" and Theme.Color.Pink or (Theme.Rarity[card.Rarity] or Theme.Rarity.Common)
	ui.stroke.Color = accent
	ui.left.BackgroundColor3 = accent

	if bigView then bigView:Remove() end
	bigView = CardView.new(card, { Size = UDim2.fromScale(0.92, 0.92), Static = true })
	bigView.Frame.AnchorPoint = CENTER
	bigView.Frame.Position = UDim2.fromScale(0.5, 0.5)
	bigView.Frame.Parent = ui.left
	if not quiet then bigView:PopIn() end

	for _, c in ipairs(ui.info:GetChildren()) do
		if c:IsA("GuiObject") then c:Destroy() end
	end

	text(ui.info, 1, "<b>" .. esc(card.Name or "???") .. "</b>", math.floor(T * 1.8), Theme.Color.Outline, Theme.Font)

	local tags = row(ui.info, 2)
	chip(tags, Theme.RarityText[card.Rarity] or card.Rarity or "ธรรมดา", accent)
	chip(tags, Theme.TypeText[card.Type] or card.Type or "?", Theme.Color.Gray)
	local el = Theme.Element[card.Element]
	if el then chip(tags, "ธาตุ" .. el.Text, el.Color) end

	local stats = row(ui.info, 3)
	chip(stats, "💰 ค่าร่าย " .. statText(card.Cost or 0, base and base.Cost), Theme.Color.Yellow)
	if card.Type == "Character" or card.Type == "Leader" then
		chip(stats, "⚔️ โจมตี " .. statText(card.ATK or 0, base and base.ATK), Theme.Color.Red)
		chip(stats, "❤️ พลังชีวิต " .. statText(math.max(card.HP or 0, 0), base and base.HP), Theme.Color.Green)
	elseif card.Type == "Weapon" then
		if typeof(card.Bonus) == "number" then chip(stats, "🗡️ โบนัส +" .. card.Bonus, Theme.Color.Red) end
		if typeof(card.Durability) == "number" then chip(stats, "🔧 ความทน " .. card.Durability, Theme.Color.Blue) end
		if card.Freeze then chip(stats, "❄️ แช่แข็งเป้า", Theme.Color.Blue) end
	end

	local desc = card.Desc or (base and base.Desc)
	if desc and desc ~= "" then
		local s = section(ui.info, 4, "📜 ความสามารถ", Color3.fromRGB(60, 100, 200))
		text(s, 1, esc(desc))
	end

	if card.Keywords and #card.Keywords > 0 then
		local s = section(ui.info, 5, "🏷️ คีย์เวิร์ด", Color3.fromRGB(140, 70, 210))
		for i, kw in ipairs(card.Keywords) do
			text(s, i, ("<b>%s</b> — %s"):format(esc(Theme.Keyword[kw] or kw), esc(Theme.KeywordDesc[kw] or "-")))
		end
	end

	local status = {}
	local gate = card.GateResult and Theme.Gate[card.GateResult]
	if gate then table.insert(status, "🎲 ผลเกต: " .. gate.Text) end
	if card.Frozen then table.insert(status, "❄️ ถูกแช่แข็ง") end
	if card.Slime then table.insert(status, "🟢 ติดเมือก") end
	if card.WeaponName then
		table.insert(status, ("🗡️ ถืออาวุธ %s (เหลือ %s ครั้ง)"):format(esc(card.WeaponName), tostring(card.WeaponDur or 0)))
	end
	if card.Type == "Character" and card.CanAttack == false then table.insert(status, "💤 เทิร์นนี้ยังโจมตีไม่ได้") end
	if #status > 0 then
		local s = section(ui.info, 6, "📍 สถานะตอนนี้", Color3.fromRGB(200, 90, 40))
		for i, line in ipairs(status) do text(s, i, line) end
	end

	local flavor = card.Flavor or (base and base.Flavor)
	if flavor and flavor ~= "" and flavor ~= desc then
		text(ui.info, 7, "<i>“" .. esc(flavor) .. "”</i>", T - 2, Color3.fromRGB(110, 100, 90))
	end

	local many = list ~= nil and #list > 1
	ui.prev.Visible, ui.next.Visible, ui.counter.Visible = many, many, many
	ui.counter.Text = many and ("%d / %d"):format(index, #list) or ""
	ui.info.Size = UDim2.fromScale(0.54, many and 0.76 or 0.88)
	if not quiet then ui.info.CanvasPosition = Vector2.zero end
end

-- card: ข้อมูลการ์ด | cards/i: (ไม่บังคับ) รายการให้กด ◀ ▶ ได้
function CardInspector.Open(card, cards, i)
	if not card then return end
	if not gui then build() end
	local cam = workspace.CurrentCamera
	T = math.clamp(math.floor((cam and cam.ViewportSize.Y or 720) / 40), 12, 24)
	list, index = cards, i or 1
	show(card)
	if not isOpen then
		isOpen = true
		gui.Enabled = true
		ui.dim.BackgroundTransparency = 1
		ui.scale.Scale = 0.7
		UIKit.tween(ui.dim, 0.2, { BackgroundTransparency = 0.35 })
		UIKit.tween(ui.scale, 0.3, { Scale = 1 }, Enum.EasingStyle.Back)
		UIKit.sfx("Click")
	end
end

function CardInspector.OpenByName(key)
	if key == nil then return end
	if type(key) == "table" then return CardInspector.Open(key) end
	local data, id = CardData[key], key
	if type(data) ~= "table" then
		data = nil
		for k, d in pairs(CardData) do
			if type(d) == "table" and d.Name == key then data, id = d, k break end
		end
	end
	if data then
		local c = table.clone(data)
		c.Id = id
		CardInspector.Open(c)
	end
end

function CardInspector.Step(d)
	if not (isOpen and list and #list > 1) then return end
	index = (index - 1 + d) % #list + 1
	show(list[index])
	UIKit.sfx("Click")
end

-- อัปเดตแบบสด: ถ้าการ์ดที่เปิดดูอยู่โดนตี/บัฟ ข้อมูลจะเปลี่ยนตามทันที
function CardInspector.Refresh(card)
	if not (isOpen and shown and card and card.Uid and shown.Uid == card.Uid) then return end
	if list then list[index] = card end
	show(card, true)
end

function CardInspector.Close()
	if not isOpen then return end
	isOpen = false
	UIKit.tween(ui.dim, 0.15, { BackgroundTransparency = 1 })
	UIKit.tween(ui.scale, 0.15, { Scale = 0.7 }).Completed:Once(function()
		if not isOpen then gui.Enabled = false end
	end)
end

function CardInspector.IsOpen() return isOpen end

-- CardView เรียกเพื่อให้กด F ตอนชี้ หรือกด Y บนจอย เปิดดูได้
function CardInspector.Track(hit, open)
	tracked[hit] = open
	hit.MouseEnter:Connect(function() hovered = hit end)
	hit.MouseLeave:Connect(function() if hovered == hit then hovered = nil end end)
end

if RunService:IsClient() then
	UserInputService.InputBegan:Connect(function(input)
		if UserInputService:GetFocusedTextBox() then return end
		local k = input.KeyCode
		if isOpen then
			if k == INSPECT_KEY or k == Enum.KeyCode.ButtonB or k == Enum.KeyCode.Backspace then
				CardInspector.Close()
			elseif k == Enum.KeyCode.Q or k == Enum.KeyCode.Left or k == Enum.KeyCode.ButtonL1 then
				CardInspector.Step(-1)
			elseif k == Enum.KeyCode.E or k == Enum.KeyCode.Right or k == Enum.KeyCode.ButtonR1 then
				CardInspector.Step(1)
			end
		elseif k == INSPECT_KEY and hovered and hovered.Parent and tracked[hovered] then
			tracked[hovered]()
		elseif k == Enum.KeyCode.ButtonY then
			local sel = GuiService.SelectedObject
			if sel and tracked[sel] then tracked[sel]() end
		end
	end)
end

return CardInspector]]
SOURCES["ReplicatedStorage/Shared/UI/CardView.lua"] = [[
-- ReplicatedStorage/Shared/UI/CardView
local Theme = require(script.Parent.Theme)
local UIKit = require(script.Parent.UIKit)
local Settings = require(script.Parent.Settings)
local TweenService = game:GetService("TweenService")
local function Inspector() return require(script.Parent.CardInspector) end -- require ตอนใช้ เลี่ยง require วนกัน

local SHINY = { Epic = 0.7, Legend = 0.5, Mystic = 0.35 } -- ค่ายิ่งน้อย แสงยิ่งแรง
local function addShine(art, strength)
	local shine = UIKit.new("Frame", {
		Name = "Shine", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1),
		ZIndex = 3, Parent = art,
	}, { UIKit.corner(UDim.new(0.08, 0)) })
	local g = UIKit.new("UIGradient", {
		Rotation = 25, Offset = Vector2.new(-1, 0), Parent = shine,
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.42, 1),
			NumberSequenceKeypoint.new(0.5, strength),
			NumberSequenceKeypoint.new(0.58, 1), NumberSequenceKeypoint.new(1, 1),
		}),
	})
	local tw = TweenService:Create(g, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, false, 2.5 + math.random()), { Offset = Vector2.new(1, 0) })
	tw:Play()
	shine.Visible = Settings.Get("Effects")
	local c = Settings.Changed:Connect(function(k, v) if k == "Effects" then shine.Visible = v end end)
	shine.Destroying:Once(function() tw:Cancel() c:Disconnect() end)
end

local CardView = {}
CardView.__index = CardView

local CENTER = Vector2.new(0.5, 0.5)
local TYPE_TEXT = { Character = "ตัวละคร", Spell = "เวท", Weapon = "อาวุธ", Leader = "ผู้นำ" }
local TYPE_ICON = { Character = "🙂", Spell = "✨", Weapon = "🗡️", Leader = "👑" }

local function hasArt(card)
	return typeof(card.Art) == "string" and card.Art ~= "" and card.Art ~= "rbxassetid://0"
end

local function describe(card)
	if card.Type == "Character" then
		local words = {}
		for _, kw in ipairs(card.Keywords or {}) do
			table.insert(words, Theme.Keyword[kw] or kw)
		end
		if #words > 0 then return table.concat(words, " • ") end
	end
	return card.Desc or card.Flavor or ""
end

local function bubble(parent, color, position, anchor)
	local b = UIKit.new("Frame", {
		Size = UDim2.fromScale(0.32, 0.32), Position = position, AnchorPoint = anchor,
		BackgroundColor3 = color, ZIndex = 2, Parent = parent,
	}, {
		UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1 }),
		UIKit.corner(UDim.new(0.5, 0)),
		UIKit.stroke(nil, 2),
	})
	return UIKit.label({ Size = UDim2.fromScale(0.8, 0.8), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER, Parent = b })
end

-- opts: Size, ShowSleep, OnClick(view), OnInspect(view)
function CardView.new(card, opts)
	opts = opts or {}
	local self = setmetatable({}, CardView)
	self.ShowSleep = opts.ShowSleep
	self.RarityColor = Theme.Rarity[card.Rarity] or Theme.Rarity.Common

	local root = UIKit.new("Frame", {
		Name = card.Uid or card.Id or "Card",
		Size = opts.Size or UDim2.fromScale(0.2, 1),
		BackgroundTransparency = 1,
	}, { UIKit.new("UIAspectRatioConstraint", { AspectRatio = 5 / 7 }) })

	local body = UIKit.new("Frame", {
		Name = "Body", Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = CENTER, BackgroundColor3 = Theme.Color.CardBg, Parent = root,
	}, { UIKit.corner(UDim.new(0.08, 0)) })
	body:SetAttribute("BaseSize", body.Size)
	self.Shadow = UIKit.new("Frame", {
		Name = "Shadow", Size = UDim2.fromScale(0.96, 0.96), Position = UDim2.fromScale(0.52, 0.535),
		AnchorPoint = CENTER, BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.55,
		ZIndex = 0, Parent = root,
	}, { UIKit.corner(UDim.new(0.08, 0)) })

	self.Stroke = UIKit.stroke(self.RarityColor, 4)
	self.Stroke.Parent = body
	if card.Rarity == "Mystic" then -- ขอบสีรุ้ง
		UIKit.new("UIGradient", {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 60, 60)),
				ColorSequenceKeypoint.new(0.5, Color3.fromRGB(60, 255, 120)),
				ColorSequenceKeypoint.new(1, Color3.fromRGB(80, 120, 255)),
			}),
			Parent = self.Stroke,
		})
	end
	self.Gradient = UIKit.new("UIGradient", { -- ร่างทองจากช่องเกต
		Color = ColorSequence.new(Color3.fromRGB(255, 240, 150), Color3.fromRGB(255, 170, 0)),
		Rotation = 45, Enabled = false, Parent = body,
	})

	UIKit.label({
		Text = TYPE_TEXT[card.Type] or "", Font = Theme.FontBody, Color = Theme.Color.Outline, StrokeThickness = 0,
		Size = UDim2.fromScale(0.36, 0.08), Position = UDim2.fromScale(0.5, 0.04), AnchorPoint = Vector2.new(0.5, 0), Parent = body,
	})

	local element = Theme.Element[card.Element]
	if element then
		local pill = UIKit.new("Frame", {
			Size = UDim2.fromScale(0.28, 0.09), Position = UDim2.fromScale(0.96, 0.03), AnchorPoint = Vector2.new(1, 0),
			BackgroundColor3 = element.Color, Parent = body,
		}, { UIKit.corner(UDim.new(0.5, 0)), UIKit.stroke(nil, 2) })
		UIKit.label({ Text = element.Text, Size = UDim2.fromScale(0.9, 0.85), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER, Parent = pill, StrokeThickness = 1 })
	end

	self.Art = UIKit.new("ImageLabel", {
		Name = "Art", Size = UDim2.fromScale(0.86, 0.46), Position = UDim2.fromScale(0.07, 0.15),
		BackgroundColor3 = Color3.fromRGB(235, 225, 205), ScaleType = Enum.ScaleType.Fit, Parent = body,
	}, { UIKit.corner(UDim.new(0.08, 0)), UIKit.stroke(nil, 2) })
	self.Icon = UIKit.label({ Size = UDim2.fromScale(0.7, 0.7), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER, Parent = self.Art, StrokeThickness = 0, MaxTextSize = 100 })
	self.Sleep = UIKit.label({ Text = "💤", Size = UDim2.fromScale(0.35, 0.35), Position = UDim2.fromScale(0.98, 0.02), AnchorPoint = Vector2.new(1, 0), Parent = self.Art, StrokeThickness = 0 })
	self.Status = UIKit.label({
		Text = "", Size = UDim2.fromScale(0.95, 0.24), Position = UDim2.fromScale(0.5, 0.98),
		AnchorPoint = Vector2.new(0.5, 1), Parent = self.Art, StrokeThickness = 1,
	})
	if SHINY[card.Rarity] then addShine(self.Art, SHINY[card.Rarity]) end

	UIKit.label({
		Text = card.Name or "???", Color = Theme.Color.Outline, StrokeThickness = 0,
		Size = UDim2.fromScale(0.9, 0.1), Position = UDim2.fromScale(0.5, 0.63), AnchorPoint = Vector2.new(0.5, 0), Parent = body,
	})
	local desc = UIKit.label({
		Text = describe(card), Font = Theme.FontBody, Color = Color3.fromRGB(90, 80, 70), StrokeThickness = 0,
		Size = UDim2.fromScale(0.56, 0.12), Position = UDim2.fromScale(0.5, 0.75), AnchorPoint = Vector2.new(0.5, 0), Parent = body,
	})
	desc.TextWrapped = true

	self.Cost = bubble(body, Theme.Color.Yellow, UDim2.fromScale(0, 0), Vector2.new(0.25, 0.25))
	if card.Type == "Character" or card.Type == "Leader" then
		self.Atk = bubble(body, Theme.Color.Red, UDim2.fromScale(0, 1), Vector2.new(0.25, 0.75))
		self.Hp = bubble(body, Theme.Color.Green, UDim2.fromScale(1, 1), Vector2.new(0.75, 0.75))
	end

	-- opts: Static (ไม่ให้เปิดดู), NoHover, InspectList, InspectIndex
	local hit = UIKit.new("TextButton", { Name = "Hitbox", Text = "", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = body })
	local function doInspect()
		if opts.Static then return end
		if opts.OnInspect then opts.OnInspect(self)
		else Inspector().Open(self.Card, opts.InspectList, opts.InspectIndex) end
	end
	local longPressed = false
	hit.Activated:Connect(function()
		if longPressed then longPressed = false return end -- กันกดค้างแล้วไปเลือกการ์ดซ้อน
		if opts.OnClick then opts.OnClick(self) end
	end)
	hit.MouseButton2Click:Connect(doInspect)
	hit.TouchLongPress:Connect(function(_, inputState)
		if inputState == Enum.UserInputState.Begin then longPressed = true doInspect() end
	end)
	if not opts.Static then
		Inspector().Track(hit, doInspect)
		if not opts.NoHover then
			local hover = UIKit.new("UIScale", { Parent = body })
			hit.MouseEnter:Connect(function() UIKit.tween(hover, 0.12, { Scale = 1.06 }) root.ZIndex = 10 end)
			hit.MouseLeave:Connect(function() UIKit.tween(hover, 0.12, { Scale = 1 }) root.ZIndex = 1 end)
		end
	end

	self.Frame, self.Body = root, body
	self:Update(card)
	return self
end

function CardView:Update(card)
	self.Card = card
	self.Cost.Text = tostring(card.Cost or 0)
	if self.Atk then
		self.Atk.Text = tostring(card.ATK or 0)
		self.Hp.Text = tostring(math.max(card.HP or 0, 0))
	end
	local art = hasArt(card)
	self.Art.Image = art and card.Art or ""
	self.Icon.Text = TYPE_ICON[card.Type] or "❓"
	self.Icon.Visible = not art
	self.Sleep.Visible = self.ShowSleep == true and card.Type == "Character" and not card.CanAttack
	local status = {}
	if card.Frozen then table.insert(status, "❄️") end
	if card.Slime then table.insert(status, "🟢") end
	if card.WeaponName then table.insert(status, "🗡️" .. tostring(card.WeaponDur or 0)) end
	self.Status.Text = table.concat(status, " ")

	self.Gradient.Enabled = card.GateResult == "Golden"
	if card.GateResult == "Poop" then
		self.BaseBg = Color3.fromRGB(150, 100, 60)
		self.Art.Image = ""
		self.Icon.Text = "💩"
		self.Icon.Visible = true
	else
		self.BaseBg = Theme.Color.CardBg
	end
	self.Body.BackgroundColor3 = self.BaseBg
end

-- โดนตี: หน้าบิด + ย้วย + ตัวเลขดาเมจ
function CardView:Hit(damage)
	UIKit.sfx("Hit")
	UIKit.popup(self.Frame, "-" .. damage)
	if not UIKit.Settings.VFX then return end
	if typeof(self.Card.HitArt) == "string" then -- ถ้ามีภาพหน้าโดนตี ให้สลับภาพชั่วคราว
		self.Art.Image = self.Card.HitArt
		task.delay(0.7, function()
			if self.Art.Parent then self:Update(self.Card) end
		end)
	end
	UIKit.jelly(self.Art, -0.4) -- ภาพยืดเบี้ยว
	UIKit.jelly(self.Body, 0.35)
	UIKit.shake(self.Body)
	self.Body.BackgroundColor3 = Theme.Color.Red
	UIKit.tween(self.Body, 0.4, { BackgroundColor3 = self.BaseBg })
end

local DEATH_STYLES = {
	function(self) -- หมุนติ้วหายไป
		UIKit.tween(self.Body, 0.5, { Rotation = 720, Size = UDim2.fromScale(0, 0) }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
	end,
	function(self) -- ระเบิดเป็นชามก๋วยเตี๋ยว
		UIKit.popup(self.Frame, "🍜💥", Theme.Color.Yellow)
		UIKit.jelly(self.Body, 0.6)
		task.delay(0.15, function() self.Body.Visible = false end)
	end,
	function(self) -- กระเด็นหลุดจอ
		UIKit.tween(self.Body, 0.5, { Position = UDim2.fromScale(2.5, 3), Rotation = 200 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
	end,
}

function CardView:Die()
	if self.Shadow then self.Shadow.Visible = false end
	UIKit.sfx("Death")
	if UIKit.Settings.VFX then
		DEATH_STYLES[math.random(#DEATH_STYLES)](self)
	end
	task.delay(0.6, function() self.Frame:Destroy() end)
end

function CardView:Remove()
	self.Frame:Destroy()
end

function CardView:PopIn()
	self.Body.Size = UDim2.fromScale(0.1, 0.1)
	UIKit.tween(self.Body, 0.35, { Size = UDim2.fromScale(1, 1) }, Enum.EasingStyle.Back)
end

function CardView:SetSelected(on)
	self.Stroke.Color = on and Theme.Color.Yellow or self.RarityColor
	self.Stroke.Thickness = on and 6 or 4
	UIKit.tween(self.Body, 0.15, { Position = UDim2.fromScale(0.5, on and 0.42 or 0.5) })
end

function CardView:SetTarget(on)
	self.Stroke.Color = on and Theme.Color.Red or self.RarityColor
	self.Stroke.Thickness = on and 6 or 4
end

function CardView:Lunge()
	UIKit.tween(self.Body, 0.12, { Position = UDim2.fromScale(0.5, 0.2) }).Completed:Once(function()
		UIKit.tween(self.Body, 0.25, { Position = UDim2.fromScale(0.5, 0.5) }, Enum.EasingStyle.Back)
	end)
end

-- หลังการ์ด (ไพ่ศัตรู / ช่องเกตศัตรู)
function CardView.back(size)
	local root = UIKit.new("Frame", { Size = size or UDim2.fromScale(0.18, 1), BackgroundTransparency = 1 }, {
		UIKit.new("UIAspectRatioConstraint", { AspectRatio = 5 / 7 }),
	})
	local body = UIKit.new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), Parent = root }, {
		UIKit.corner(UDim.new(0.08, 0)),
		UIKit.stroke(nil, 3),
		UIKit.new("UIGradient", { Color = ColorSequence.new(Theme.Color.Pink, Theme.Color.Yellow), Rotation = 45 }),
	})
	UIKit.label({ Text = "?", Size = UDim2.fromScale(0.6, 0.6), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER, Parent = body, MaxTextSize = 80 })
	return root
end

return CardView]]
SOURCES["ReplicatedStorage/Shared/UI/FX.lua"] = [[
-- ReplicatedStorage/Shared/UI/FX.lua  (ใช้ฝั่ง Client เท่านั้น)
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Debris = game:GetService("Debris")

local UIKit = require(script.Parent.UIKit)
local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local FX = {}

-- ตัวหมุนรวม: RenderStepped เส้นเดียวทั้งเกม
local spinners, spinConn = {}, nil
function FX.spin(inst, degPerSec)
	spinners[inst] = degPerSec or 90
	if not spinConn then
		spinConn = RunService.RenderStepped:Connect(function(dt)
			local any = false
			for i, sp in pairs(spinners) do
				if i.Parent then any = true; i.Rotation = (i.Rotation + sp * dt) % 360 else spinners[i] = nil end
			end
			if not any then spinConn:Disconnect(); spinConn = nil end
		end)
	end
	return function() spinners[inst] = nil end
end

local function diamond(parent, color, size, z)
	return UIKit.new("Frame", { Name = "Spark", BackgroundColor3 = color, BorderSizePixel = 0, AnchorPoint = CENTER, Size = size,
		Rotation = 45, ZIndex = z or 70, Parent = parent }, { UIKit.new("UIStroke", { Color = C.White, Thickness = 1.5 }) })
end

function FX.sparkles(parent, color, count, origin)
	if not parent or not UIKit.effectsOn() then return end
	origin = origin or Vector2.new(0.5, 0.5)
	for i = 1, count or 12 do
		local sz = math.random(6, 16)
		local d = diamond(parent, (i % 3 == 0) and C.White or (color or C.Yellow), UDim2.fromOffset(sz, sz))
		d.Position = UDim2.fromScale(origin.X, origin.Y)
		local a, dist, dur = math.random() * math.pi * 2, 0.25 + math.random() * 0.45, 0.5 + math.random() * 0.4
		UIKit.tween(d, dur, { Position = UDim2.fromScale(origin.X + math.cos(a) * dist, origin.Y + math.sin(a) * dist),
			Rotation = 45 + math.random(-180, 180), Size = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quart)
		Debris:AddItem(d, UIKit.dur(dur) + 0.1)
	end
end

function FX.ambientSparkles(parent, color, every)
	color = color or C.Yellow
	local alive = true
	task.spawn(function()
		while alive and parent.Parent do
			if UIKit.effectsOn() then
				local sz = math.random(5, 12)
				local d = diamond(parent, math.random() < 0.4 and C.White or color, UDim2.fromOffset(sz, sz), 30)
				d.Position = UDim2.fromScale(math.random(), math.random())
				local s = UIKit.getScale(d)
				s.Scale = 0
				UIKit.tween(s, 0.35, { Scale = 1 }, Enum.EasingStyle.Back)
				task.delay(UIKit.dur(0.4), function() if d.Parent then UIKit.tween(s, 0.35, { Scale = 0 }) end end)
				Debris:AddItem(d, UIKit.dur(0.8) + 0.2)
			end
			task.wait(every or 0.25)
		end
	end)
	return function() alive = false end
end

function FX.flash(parent, color)
	local f = UIKit.new("Frame", { BackgroundColor3 = color or C.White, BackgroundTransparency = 0.15, Size = UDim2.fromScale(1, 1), ZIndex = 400, Parent = parent })
	UIKit.tween(f, 0.35, { BackgroundTransparency = 1 })
	Debris:AddItem(f, UIKit.dur(0.4))
end

function FX.shockwave(parent, color)
	local r = UIKit.new("Frame", { BackgroundTransparency = 1, AnchorPoint = CENTER, Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(0.4, 0.4), ZIndex = 60, Parent = parent }, { UIKit.corner(UDim.new(1, 0)) })
	local st = UIKit.new("UIStroke", { Color = color or C.White, Thickness = 10, Parent = r })
	UIKit.tween(r, 0.5, { Size = UDim2.fromScale(1.7, 1.7) }, Enum.EasingStyle.Quart)
	UIKit.tween(st, 0.5, { Thickness = 0, Transparency = 1 }, Enum.EasingStyle.Quart)
	Debris:AddItem(r, UIKit.dur(0.55))
end

-- กรอบเส้นวาดมือ 2 ชั้น + line boil (เส้นสั่นแบบการ์ตูนวาดมือ)
local boilers = setmetatable({}, { __mode = "k" })
task.spawn(function()
	while true do
		task.wait(0.16)
		if UIKit.effectsOn() then
			for h in pairs(boilers) do
				if h.Parent then
					for i, ch in ipairs(h:GetChildren()) do ch.Rotation = (i == 1 and -0.8 or 0.7) + (math.random() - 0.5) * 0.9 end
				else boilers[h] = nil end
			end
		end
	end
end)

function FX.sketchFrame(gui, color, z)
	local old = gui:FindFirstChild("Sketch")
	if old then old:Destroy() end
	local h = UIKit.new("Frame", { Name = "Sketch", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = z or 45, Parent = gui })
	for i, cfg in ipairs({ { r = -0.8, x = -2, y = 1, t = 2.5 }, { r = 0.7, x = 2, y = -1, t = 1.5 } }) do
		UIKit.new("Frame", { BackgroundTransparency = 1, AnchorPoint = CENTER, Position = UDim2.new(0.5, cfg.x, 0.5, cfg.y),
			Size = UDim2.new(1, 2 * i, 1, -2 * i), Rotation = cfg.r, ZIndex = h.ZIndex, Parent = h }, {
			UIKit.corner(Theme.Radius - i * 2),
			UIKit.new("UIStroke", { Color = color or C.Outline, Thickness = cfg.t, Transparency = 0.15 * i }),
		})
	end
	boilers[h] = true
	return h
end

-- ออร่าตามเทียร์: T2 ขอบสี, T3+ ขอบรุ้งหมุน, T4+ ประกายวิบวับ
local ambient = setmetatable({}, { __mode = "k" })
function FX.rarityGlow(gui, rarity, opts)
	opts = opts or {}
	local old = gui:FindFirstChild("RarityGlow")
	if old then old:Destroy() end
	if ambient[gui] then ambient[gui](); ambient[gui] = nil end
	local tier = Theme.RarityTier[rarity] or 1
	if tier < 2 then return end
	local ring = UIKit.new("Frame", { Name = "RarityGlow", BackgroundTransparency = 1, AnchorPoint = CENTER, Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(1, 8, 1, 8), ZIndex = 50, Parent = gui }, { UIKit.corner(Theme.Radius + 4) })
	local st = UIKit.new("UIStroke", { Thickness = 2 + tier, Color = C.White, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = ring })
	local g = UIKit.new("UIGradient", { Color = Theme.RarityGlow[rarity] or Theme.RarityGlow.Rare, Parent = st })
	if tier >= 3 then
		FX.spin(g, 60 * tier)
		TweenService:Create(st, TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Transparency = 0.45 }):Play()
	end
	if tier >= 4 and opts.Sparkles ~= false then
		ambient[gui] = FX.ambientSparkles(gui, Theme.Rarity[rarity], tier == 5 and 0.12 or 0.22)
	end
	return ring
end

-- วงซัมมอนเจม (วงกลม/วงรีก็ได้) คืน { Root, SetActive, Burst, Destroy }
function FX.summonCircle(parent, p)
	p = p or {}
	local color = p.Color or C.Pink
	local root = UIKit.new("Frame", { Name = "SummonCircle", BackgroundTransparency = 1, AnchorPoint = CENTER,
		Position = p.Position or UDim2.fromScale(0.5, 0.5), Size = p.Size or UDim2.fromScale(0.5, 0.5), ZIndex = p.ZIndex or 1, Parent = parent })
	if p.Square then UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1, Parent = root }) end
	local z = root.ZIndex
	local function ellipse(name, sc, thick, seq, speed, fillT)
		local e = UIKit.new("Frame", { Name = name, BackgroundColor3 = color, BackgroundTransparency = fillT or 1, AnchorPoint = CENTER,
			Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(sc, sc), ZIndex = z, Parent = root }, { UIKit.corner(UDim.new(1, 0)) })
		local st
		if thick then
			st = UIKit.new("UIStroke", { Thickness = thick, Color = C.White, Parent = e })
			FX.spin(UIKit.new("UIGradient", { Color = seq, Parent = st }), speed)
		end
		return e, st
	end
	local glow = ellipse("Glow", 0.95, nil, nil, nil, 0.8)
	local _, outer = ellipse("Outer", 1, 6, Theme.seq(color, C.White, C.Blue, color), 140)
	ellipse("Inner", 0.72, 3, Theme.seq(C.Yellow, color, C.White, C.Yellow), -220)

	local star = UIKit.new("Frame", { Name = "Star", BackgroundTransparency = 1, AnchorPoint = CENTER, Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(0.5, 0.5), ZIndex = z, Parent = root }, { UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1 }) })
	for _, r in ipairs({ 0, 45 }) do
		UIKit.new("Frame", { BackgroundTransparency = 1, AnchorPoint = CENTER, Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.72, 0.72),
			Rotation = r, ZIndex = z, Parent = star }, { UIKit.new("UIStroke", { Color = color, Thickness = 2.5, Transparency = 0.2 }) })
	end
	FX.spin(star, -40)

	local gems, palette = {}, { C.Pink, C.Blue, C.Lime, C.Yellow }
	for i = 1, 8 do
		gems[i] = UIKit.new("Frame", { Name = "Gem", BackgroundColor3 = palette[(i - 1) % 4 + 1], BorderSizePixel = 0, AnchorPoint = CENTER,
			Size = UDim2.fromScale(0.12, 0.12), Rotation = 45, ZIndex = z, Parent = root },
			{ UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1 }), UIKit.stroke(C.Outline, 2) })
	end
	local t0 = os.clock()
	local orbit = RunService.RenderStepped:Connect(function()
		local t = UIKit.effectsOn() and (os.clock() - t0) * 1.2 or 0
		for i, g in ipairs(gems) do
			local a = t + (i - 1) / #gems * math.pi * 2
			g.Position = UDim2.fromScale(0.5 + math.cos(a) * 0.5, 0.5 + math.sin(a) * 0.5)
		end
	end)
	root.Destroying:Connect(function() orbit:Disconnect() end)

	local obj = { Root = root }
	function obj:SetActive(on)
		UIKit.tween(glow, 0.3, { BackgroundTransparency = on and 0.5 or 0.85 })
		UIKit.tween(outer, 0.3, { Transparency = on and 0 or 0.45 })
	end
	function obj:Burst(c)
		c = c or color
		UIKit.sfx("Summon", 0.1)
		local s = UIKit.getScale(root)
		s.Scale = 1.25
		UIKit.tween(s, 0.6, { Scale = 1 }, Enum.EasingStyle.Elastic)
		glow.BackgroundColor3, glow.BackgroundTransparency = c, 0.1
		UIKit.tween(glow, 0.6, { BackgroundTransparency = 0.75 })
		FX.shockwave(root, c)
		FX.sparkles(root, c, 18)
	end
	function obj:Destroy() root:Destroy() end
	obj:SetActive(false)
	return obj
end

-- ไฟลุก (ใช้ที่นาฬิกา) ตั้งความแรง 0..1
function FX.flames(parent, z)
	local root = UIKit.new("Frame", { Name = "Flames", BackgroundTransparency = 1, Size = UDim2.fromScale(1.3, 1.6),
		AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 1.05), ZIndex = z or 1, Parent = parent })
	local obj = { Root = root, Intensity = 0 }
	task.spawn(function()
		while root.Parent do
			local k = obj.Intensity
			if k > 0 and UIKit.effectsOn() then
				local sz = math.random(14, 26) * (0.7 + k * 0.6)
				local f = UIKit.new("Frame", { BackgroundColor3 = C.Yellow, BorderSizePixel = 0, AnchorPoint = CENTER, Size = UDim2.fromOffset(sz, sz),
					Position = UDim2.new(math.random() * 0.8 + 0.1, 0, 1, 0), Rotation = 45, ZIndex = root.ZIndex, Parent = root }, {
					UIKit.corner(UDim.new(0.3, 0)),
					UIKit.new("UIGradient", { Rotation = -45, Color = Theme.seq(C.White, C.Yellow, C.Orange, C.Red) }),
				})
				local d = 0.5 + math.random() * 0.35
				UIKit.tween(f, d, { Position = f.Position - UDim2.fromScale((math.random() - 0.5) * 0.15, 0.55 + k * 0.4),
					Size = UDim2.fromOffset(2, 2), BackgroundTransparency = 0.6, Rotation = 45 + math.random(-60, 60) })
				Debris:AddItem(f, UIKit.dur(d) + 0.05)
				task.wait(0.09 - k * 0.06)
			else
				task.wait(0.2)
			end
		end
	end)
	function obj:SetIntensity(x) self.Intensity = math.clamp(x, 0, 1) end
	function obj:Destroy() root:Destroy() end
	return obj
end

return FX]]
SOURCES["ReplicatedStorage/Shared/UI/Settings.lua"] = [[
-- ReplicatedStorage/Shared/UI/Settings (ModuleScript)
-- เก็บค่าตั้งค่าฝั่งผู้เล่น ใช้ร่วมกันทุกเมนู
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")

local Settings = {}
local values = {
	Sfx = 1,              -- 0–1
	AnimSpeed = 1,        -- 0.5 / 1 / 1.5 / 2
	Effects = true,       -- แสงวิ้งบนการ์ด + ประกายพื้นหลัง
	DamageNumbers = true,
	TargetArrow = true,
}
local changed = Instance.new("BindableEvent")
Settings.Changed = changed.Event

-- ปรับเสียงทุกไฟล์ใน SoundService.SFX (UIKit.sfx เล่นจากโฟลเดอร์นี้)
local function applySfx(v)
	local folder = SoundService:FindFirstChild("SFX")
	if not folder then return end
	for _, s in ipairs(folder:GetDescendants()) do
		if s:IsA("Sound") then
			if s:GetAttribute("BaseVolume") == nil then s:SetAttribute("BaseVolume", s.Volume) end
			s.Volume = s:GetAttribute("BaseVolume") * v
		end
	end
end

function Settings.Get(key) return values[key] end

function Settings.Set(key, value)
	if values[key] == value then return end
	values[key] = value
	if key == "Sfx" and RunService:IsClient() then applySfx(value) end
	changed:Fire(key, value)
end

return Settings]]
SOURCES["ReplicatedStorage/Shared/UI/Style.lua"] = [[
-- ธีมการ์ตูนนีออน (PASULOL): ใช้พาเล็ตจาก Theme เดียวกับ UIKit
local Theme = require(script.Parent.Theme)
local T = Theme.Color
local Style = {}

Style.Font = {
	Regular = Theme.FontBody, Medium = Theme.FontBody, Bold = Theme.Font, Heavy = Theme.Font,
}

Style.C = {
	Bg = T.TableDark, Panel = Color3.fromRGB(58, 24, 130), Panel2 = Color3.fromRGB(86, 34, 176), Line = T.Outline,
	Felt = T.Table, FeltDark = T.TableDark, Paper = T.CardBg, Ink = T.Ink, InkSoft = Color3.fromRGB(72, 60, 96),
	Text = T.White, TextDim = Color3.fromRGB(205, 195, 240), Accent = T.Yellow, Good = T.Green, Bad = T.Red,
	Info = T.Blue, Pink = T.Pink, Violet = T.Purple, Teal = Color3.fromRGB(0, 232, 200),
}
Style.Rarity = Theme.Rarity
Style.Element = {} -- Color3 ต่อธาตุ (Theme.Element เป็นตาราง {Text, Color})
for id, e in pairs(Theme.Element) do Style.Element[id] = e.Color end
Style.Name = {
	Type = { Character = "ตัวละคร", Spell = "เวท", Weapon = "อาวุธ", Leader = "ผู้นำ" },
	Element = { Sati = "สติ", Biao = "เบียว", Muen = "มึน", Gawa = "กาว" },
	Rarity = { Common = "ธรรมดา", Rare = "หายาก", Epic = "มหากาพย์", Legend = "ตำนาน", Mystic = "ลึกลับ" },
	Keyword = { Rush = "บุก", Taunt = "ยั่วยุ", Necro = "ปลุกศพ", Unlucky = "ดวงซวย", Steal = "ขโมย" },
}

function Style.new(class, props, children)
	local inst = Instance.new(class)
	if inst:IsA("GuiObject") then inst.BorderSizePixel = 0 end
	local parent
	for k, v in props or {} do
		if k == "Parent" then parent = v else inst[k] = v end
	end
	for _, c in children or {} do c.Parent = inst end
	if parent then inst.Parent = parent end
	return inst
end

function Style.corner(r)
	return Style.new("UICorner", { CornerRadius = typeof(r) == "UDim" and r or UDim.new(0, r or 4) })
end
function Style.pad(px)
	local u = UDim.new(0, px)
	return Style.new("UIPadding", { PaddingTop = u, PaddingBottom = u, PaddingLeft = u, PaddingRight = u })
end
function Style.stroke(color, thickness, parent)
	return Style.new("UIStroke", {
		Color = color or Style.C.Line, Thickness = thickness or 3, LineJoinMode = Enum.LineJoinMode.Round,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = parent,
	})
end

local function isThai(str) return type(str) == "string" and (str:find("\224\184") or str:find("\224\185")) ~= nil end

function Style.text(p)
	local lbl = Style.new("TextLabel", {
		Name = p.Name or "Text", BackgroundTransparency = 1, Text = p.Text or "",
		Font = p.Font or (isThai(p.Text) and Theme.FontThai or Style.Font.Regular), TextColor3 = p.Color or Style.C.Text,
		TextScaled = true, TextWrapped = p.Wrap ~= false,
		TextXAlignment = Enum.TextXAlignment[p.XAlign or "Left"],
		TextYAlignment = Enum.TextYAlignment[p.YAlign or "Center"],
		Position = p.Position or UDim2.new(), Size = p.Size or UDim2.fromScale(1, 1),
		AnchorPoint = p.AnchorPoint or Vector2.zero, Rotation = p.Tilt or 0, ZIndex = p.ZIndex or 1,
		LayoutOrder = p.LayoutOrder or 0, Parent = p.Parent,
	})
	Style.new("UITextSizeConstraint", { MaxTextSize = p.Max or 18, MinTextSize = p.Min or 6, Parent = lbl })
	if p.Stroke ~= false then
		Style.new("UIStroke", { Color = Style.C.Line, Thickness = p.StrokeThickness or 2, LineJoinMode = Enum.LineJoinMode.Round, Parent = lbl })
	end
	return lbl
end

function Style.button(p)
	local base = p.Color or Style.C.Panel2
	local btn = Style.new("TextButton", {
		Name = p.Name or "Button", AutoButtonColor = false, Text = p.Text or "",
		Font = p.Font or (isThai(p.Text) and Theme.FontThai or Style.Font.Bold), TextColor3 = p.TextColor or Style.C.Text,
		TextScaled = true, TextWrapped = true, BackgroundColor3 = base,
		Position = p.Position or UDim2.new(), Size = p.Size or UDim2.fromScale(1, 1),
		AnchorPoint = p.AnchorPoint or Vector2.zero, LayoutOrder = p.LayoutOrder or 0,
		ZIndex = p.ZIndex or 1, Parent = p.Parent,
	}, {
		Style.corner(p.Radius or 4),
		Style.new("UITextSizeConstraint", { MaxTextSize = p.Max or 18, MinTextSize = 6 }),
		Style.pad(p.Pad or 6),
	})
	local rim = Style.stroke(base:Lerp(Color3.new(1, 1, 1), 0.35), 1.5, btn)
	local hovered = false
	local function paint()
		local c = btn:GetAttribute("Base") or base
		rim.Color = c:Lerp(Color3.new(1, 1, 1), 0.35)
		if btn:GetAttribute("Disabled") then
			btn.BackgroundColor3 = c:Lerp(Style.C.Bg, 0.55)
			btn.TextTransparency = 0.45
		else
			btn.BackgroundColor3 = hovered and c:Lerp(Color3.new(1, 1, 1), 0.08) or c
			btn.TextTransparency = 0
		end
	end
	btn:SetAttribute("Base", base)
	btn.MouseEnter:Connect(function() hovered = true paint() end)
	btn.MouseLeave:Connect(function() hovered = false paint() end)
	btn:GetAttributeChangedSignal("Disabled"):Connect(paint)
	btn:GetAttributeChangedSignal("Base"):Connect(paint)
	if p.OnClick then
		local last = 0
		btn.Activated:Connect(function()
			if btn:GetAttribute("Disabled") then return end
			local now = os.clock()
			if now - last < (p.Debounce or 0.25) then return end -- กันกดรัวฝั่งไคลเอนต์
			last = now
			p.OnClick(btn)
		end)
	end
	paint()
	return btn
end

function Style.setEnabled(btn, on) btn:SetAttribute("Disabled", not on) end
function Style.setBase(btn, color) btn:SetAttribute("Base", color) end

-- ตัดอีโมจิออกจากข้อความที่มาจากเซิร์ฟเวอร์
function Style.clean(text)
	text = tostring(text or "")
	local ok, out = pcall(function()
		local parts = {}
		for _, cp in utf8.codes(text) do
			local emoji = cp >= 0x1F000 or (cp >= 0x2600 and cp <= 0x27BF)
				or (cp >= 0x2B00 and cp <= 0x2BFF) or cp == 0xFE0F or cp == 0x200D
			if not emoji then table.insert(parts, utf8.char(cp)) end
		end
		return table.concat(parts)
	end)
	if not ok then return text end
	return (out:gsub("^%s+", ""):gsub("%s+$", ""))
end

function Style.screen(name, order, parent)
	local g = Style.new("ScreenGui", {
		Name = name, DisplayOrder = order, ResetOnSpawn = false,
		IgnoreGuiInset = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})
	pcall(function() g.ScreenInsets = Enum.ScreenInsets.TopbarSafeInsets end)
	g.Parent = parent
	return g
end


-- ScrollingFrame ที่ขนาด canvas คำนวณเองจากเนื้อหา
-- (AutomaticCanvasSize + UIListLayout มีบัคที่รู้กัน: canvas เหลือ 0 แล้วเนื้อหาหายหมด)
function Style.scroll(p)
	local f = Style.new("ScrollingFrame", {
		Name = p.Name or "Scroll", BackgroundTransparency = 1, BorderSizePixel = 0,
		Position = p.Position or UDim2.new(), Size = p.Size or UDim2.fromScale(1, 1),
		ScrollBarThickness = 5, ScrollBarImageColor3 = Style.C.Line, CanvasSize = UDim2.new(),
		ScrollingDirection = Enum.ScrollingDirection.Y, LayoutOrder = p.LayoutOrder or 0, Parent = p.Parent,
	})
	local layout = p.Layout
	if not layout then
		layout = Style.new("UIListLayout", { Padding = UDim.new(0, p.Gap or 8), SortOrder = Enum.SortOrder.LayoutOrder })
	end
	layout.Parent = f
	local function fit()
		f.CanvasSize = UDim2.fromOffset(0, layout.AbsoluteContentSize.Y + (p.Extra or 8))
	end
	layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit)
	fit()
	return f, layout
end

-- ให้ลูกตัวนี้กินพื้นที่ที่เหลือใน UIListLayout (ถ้าเวอร์ชัน Studio ไม่รู้จัก UIFlexItem จะข้ามไปเฉยๆ)
function Style.fill(gui)
	pcall(function()
		local flex = Instance.new("UIFlexItem")
		flex.FlexMode = Enum.UIFlexMode.Fill
		flex.Parent = gui
	end)
end

-- แถบหัวเรื่องสีของแผง
function Style.header(parent, text, color, order)
	local bar = Style.new("Frame", { Name = "Header", BackgroundColor3 = color or Style.C.Violet,
		Size = UDim2.new(1, 0, 0, 34), LayoutOrder = order or 0, Parent = parent }, { Style.corner(5), Style.pad(4) })
	Style.text({ Font = Style.Font.Heavy, Text = text, Color = Style.C.Paper, Max = 20, Parent = bar,
		Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -16, 1, 0) })
	return bar
end

-- Toast: ซ้อนกันเป็นแถว ไม่ทับกัน สูงสุด 3 อัน
Style.toastParent = nil
local holder, seq, lastText, lastAt = nil, 0, nil, 0
local KIND = {
	info = Style.C.Panel2, good = Color3.fromRGB(24, 120, 70), bad = Color3.fromRGB(150, 30, 50),
	warn = Color3.fromRGB(170, 100, 0),
}
function Style.toast(text, kind)
	local parent = Style.toastParent
	if not parent then return end
	text = Style.clean(text)
	if text == "" then return end
	if text == lastText and os.clock() - lastAt < 0.6 then return end
	lastText, lastAt = text, os.clock()
	if not holder or not holder.Parent then
		holder = Style.new("Frame", {
			Name = "Toasts", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, 8), Size = UDim2.new(0.42, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 50, Parent = parent,
		}, {
			Style.new("UIListLayout", {
				Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
				HorizontalAlignment = Enum.HorizontalAlignment.Center,
			}),
			Style.new("UISizeConstraint", { MaxSize = Vector2.new(460, 9999) }),
		})
	end
	local items = {}
	for _, c in holder:GetChildren() do
		if c:IsA("Frame") then table.insert(items, c) end
	end
	table.sort(items, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
	while #items >= 3 do table.remove(items, 1):Destroy() end
	seq += 1
	local f = Style.new("Frame", {
		BackgroundColor3 = KIND[string.lower(tostring(kind or "info"))] or KIND.info, Size = UDim2.new(1, 0, 0, 34),
		LayoutOrder = seq, ZIndex = 50, Parent = holder,
	}, { Style.corner(4) })
	Style.stroke(Style.C.Line, 1, f)
	Style.text({ Text = text, Max = 16, XAlign = "Center", Position = UDim2.fromOffset(8, 0),
		Size = UDim2.new(1, -16, 1, 0), ZIndex = 51, Parent = f })
	task.delay(2.6, function() if f.Parent then f:Destroy() end end)
end

return Style]]
SOURCES["ReplicatedStorage/Shared/UI/Theme.lua"] = [[
-- ReplicatedStorage/Shared/UI/Theme.lua
-- PASULOL palette: นีออนจัดจ้าน + ขอบดำหนา + เงาการ์ตูน
local Theme = {}
local rgb = Color3.fromRGB

Theme.Font     = Enum.Font.LuckiestGuy -- หัวข้อ/ตัวเลข อ้วนกลมกวนๆ
Theme.FontAlt  = Enum.Font.Bangers     -- คอมมิคเอียง (POW! / WANTED)
Theme.FontBody = Enum.Font.FredokaOne  -- เนื้อหาอ่านง่าย
Theme.FontThai = Enum.Font.GothamBlack -- ข้อความไทย (ฟอนต์คอมมิคไม่มี glyph ไทย)

Theme.Color = {
	Outline = rgb(14, 10, 24), Ink = rgb(14, 10, 24), Shadow = rgb(0, 0, 0), White = rgb(255, 255, 255),
	Panel = rgb(255, 244, 205), CardBg = rgb(255, 251, 236),
	Table = rgb(44, 18, 96), TableDark = rgb(24, 8, 56),
	Yellow = rgb(255, 228, 0), Lime = rgb(198, 255, 0), Pink = rgb(255, 36, 168),
	Blue = rgb(0, 196, 255), Green = rgb(36, 255, 122), Orange = rgb(255, 128, 0),
	Red = rgb(255, 48, 72), Purple = rgb(148, 56, 255), Gray = rgb(150, 146, 170), Brown = rgb(130, 82, 40),
}
local C = Theme.Color

function Theme.seq(...)
	local cols, kps = { ... }, {}
	for i, c in ipairs(cols) do kps[i] = ColorSequenceKeypoint.new((i - 1) / (#cols - 1), c) end
	return ColorSequence.new(kps)
end

Theme.Rarity      = { Common = rgb(175, 185, 205), Rare = C.Blue, Epic = C.Purple, Legend = C.Yellow, Mystic = C.Pink }
Theme.RarityTier  = { Common = 1, Rare = 2, Epic = 3, Legend = 4, Mystic = 5 }
Theme.RarityLabel = { Common = "T1 ธรรมดา", Rare = "T2 แรร์", Epic = "T3 เอพิค", Legend = "T4 ตำนาน", Mystic = "T5 มิสติก" }
Theme.RarityGlow  = {
	Common = Theme.seq(Theme.Rarity.Common, Theme.Rarity.Common),
	Rare   = Theme.seq(C.Blue, C.White, C.Blue),
	Epic   = Theme.seq(C.Purple, C.Pink, C.White, C.Purple),
	Legend = Theme.seq(C.Yellow, C.Orange, C.White, C.Yellow),
	Mystic = Theme.seq(C.Pink, C.Yellow, C.Lime, C.Blue, C.Purple, C.Pink),
}

-- รูปแบบตารางเหมือนเดิม {Text, Color}: CardView / CardInspector อ่าน .Text และ .Color
Theme.Element = {
	Sati = { Text = "สติ",  Color = C.Blue },
	Biao = { Text = "เบียว", Color = C.Red },
	Muen = { Text = "มึน",  Color = C.Purple },
	Gawa = { Text = "กาว",  Color = C.Lime },
}

-- GateRoller / CardInspector อ่าน Theme.Gate[id].Text และ .Color จึงคงรูปแบบตาราง
-- (ถ้าอยากได้เฉพาะสี ใช้ Theme.GateColor[id])
Theme.GateColor = { Golden = rgb(255, 200, 0), Pumped = C.Green, Normal = C.Blue, Droopy = C.Orange, Poop = C.Brown }
Theme.GateInfo = {
	Golden = { Text = "ทองคำ!! x3",   Kind = "Win",  Emoji = "👑" },
	Pumped = { Text = "ปั๊มกล้าม x1.5", Kind = "Win",  Emoji = "💪" },
	Normal = { Text = "ปกติ... x1",    Kind = "Meh",  Emoji = "😐" },
	Droopy = { Text = "เหี่ยว x0.5",    Kind = "Fail", Emoji = "🥀" },
	Poop   = { Text = "เกลือ!! อึ!!",   Kind = "Fail", Emoji = "💩" },
}
Theme.Gate = {}
for id, info in pairs(Theme.GateInfo) do
	Theme.Gate[id] = { Text = info.Emoji .. " " .. info.Text, Color = Theme.GateColor[id], Kind = info.Kind, Emoji = info.Emoji }
end

Theme.FontTh = Theme.FontThai -- alias กันโค้ดเก่าที่เรียกชื่อสั้น

Theme.TypeColor = { Character = C.Pink, Weapon = C.Orange, Spell = C.Blue, Leader = C.Yellow }
Theme.TypeLabel = { Character = "ตัวละคร", Weapon = "อาวุธ", Spell = "สกิล", Leader = "ผู้นำ" }
-- คีย์เดิมที่ CardView / CardInspector ยังอ่านอยู่ (ห้ามลบ)
Theme.RarityText = { Common = "ธรรมดา", Rare = "หายาก", Epic = "มหากาพย์", Legend = "ตำนาน", Mystic = "ลึกลับ" }
Theme.TypeText = { Character = "ตัวละคร", Spell = "เวท", Weapon = "อาวุธ", Leader = "ผู้นำ" }
Theme.Keyword = { Rush = "ใจร้อน", Taunt = "ตัวบัง", Necro = "ขุดศพ", Unlucky = "ดวงซวย", Steal = "ขโมย" }
Theme.KeywordDesc = {
	Rush = "ลงสนามแล้วโจมตีได้ทันที ไม่ต้องรอเทิร์นถัดไป",
	Taunt = "ศัตรูต้องโจมตีตัวนี้ก่อน ถึงจะตีตัวอื่นหรือผู้นำได้",
	Necro = "ตอนลงสนาม: ขุดตัวละครจากสุสานของเราสุ่ม 1 ใบ กลับขึ้นมือ (ถ้ามือยังไม่เต็ม)",
	Unlucky = "ตอนตาย: โยนเหรียญ หัว = สุ่มทำดาเมจ 3 ใส่ศัตรู / ก้อย = ผู้นำเราโดนเอง 3",
	Steal = "ตอนลงสนาม: ขโมยพอยต์ที่ศัตรูดองไว้ สูงสุด 2",
}

Theme.Stroke, Theme.ShadowOffset, Theme.Radius, Theme.Tilt = 3, 6, 14, -3
return Theme]]
SOURCES["ReplicatedStorage/Shared/UI/UIKit.lua"] = [[
-- ReplicatedStorage/Shared/UI/UIKit.lua
local TweenService = game:GetService("TweenService")
local SoundService = game:GetService("SoundService")
local Players = game:GetService("Players")
local Debris = game:GetService("Debris")

local Theme = require(script.Parent.Theme)
local okS, Settings = pcall(require, script.Parent.Settings)
if not okS then Settings = nil end

local UIKit = {}
UIKit.Theme = Theme
-- คงไว้ให้โค้ดเดิมใช้ต่อ: CardView อ่าน UIKit.Settings.VFX, init.client ตั้ง UIKit.toastParent
UIKit.Settings = { Voice = true, VFX = true, Tomato = true }
UIKit.toastParent = nil
if Settings and Settings.Changed then
	UIKit.Settings.VFX = Settings.Get("Effects") ~= false
	Settings.Changed:Connect(function(k, v) if k == "Effects" then UIKit.Settings.VFX = v ~= false end end)
end
local C = Theme.Color
local CENTER = Vector2.new(0.5, 0.5)
UIKit.CENTER = CENTER

local function setting(key, default)
	if Settings and Settings.Get then
		local ok, v = pcall(Settings.Get, key)
		if ok and v ~= nil then return v end
	end
	return default
end
UIKit.setting = setting
function UIKit.effectsOn() return setting("Effects", true) ~= false end
function UIKit.dur(t) return t / math.max(tonumber(setting("AnimSpeed", 1)) or 1, 0.1) end

function UIKit.fontFor(text, preferred)
	if type(text) == "string" and (text:find("\224\184") or text:find("\224\185")) then return Theme.FontThai end
	return preferred or Theme.Font
end

function UIKit.new(className, props, children)
	local inst, parent = Instance.new(className), nil
	for k, v in pairs(props or {}) do if k == "Parent" then parent = v else inst[k] = v end end
	for _, c in ipairs(children or {}) do c.Parent = inst end
	if parent then inst.Parent = parent end
	return inst
end

function UIKit.corner(radius)
	return UIKit.new("UICorner", { CornerRadius = typeof(radius) == "UDim" and radius or UDim.new(0, radius or Theme.Radius) })
end

function UIKit.stroke(color, thickness)
	return UIKit.new("UIStroke", { Color = color or C.Outline, Thickness = thickness or Theme.Stroke, LineJoinMode = Enum.LineJoinMode.Round })
end

function UIKit.tween(inst, time, props, style, direction)
	local t = TweenService:Create(inst, TweenInfo.new(UIKit.dur(time or 0.25), style or Enum.EasingStyle.Quad, direction or Enum.EasingDirection.Out), props)
	t:Play()
	return t
end

function UIKit.getScale(gui)
	local s = gui:FindFirstChild("KitScale") or gui:FindFirstChildOfClass("UIScale")
	if not s then s = UIKit.new("UIScale", { Name = "KitScale", Parent = gui }) end
	return s
end

-- jitter = สุ่ม pitch ±% ให้เสียงไม่ซ้ำซาก
function UIKit.sfx(name, jitter)
	local folder = SoundService:FindFirstChild("SFX")
	local src = folder and folder:FindFirstChild(name)
	local vol = tonumber(setting("Sfx", 1)) or 1
	if not src or vol <= 0 then return end
	local s = src:Clone()
	s.Volume = src.Volume * vol
	if jitter then s.PlaybackSpeed = src.PlaybackSpeed * (1 + (math.random() * 2 - 1) * jitter) end
	s.Parent = SoundService
	s:Play()
	Debris:AddItem(s, math.max(s.TimeLength, 3) + 0.5)
end

function UIKit.label(p)
	local text = p.Text or ""
	local lbl = UIKit.new("TextLabel", {
		Name = p.Name or "Label", BackgroundTransparency = 1, Font = p.Font or UIKit.fontFor(text),
		Text = text, TextColor3 = p.Color or C.White, TextScaled = true, TextWrapped = p.Wrap == true,
		TextXAlignment = p.AlignX or Enum.TextXAlignment.Center, TextYAlignment = p.AlignY or Enum.TextYAlignment.Center,
		Size = p.Size or UDim2.fromScale(1, 1), Position = p.Position or UDim2.new(),
		AnchorPoint = p.AnchorPoint or Vector2.zero, Rotation = p.Tilt or 0,
		ZIndex = p.ZIndex or 1, LayoutOrder = p.LayoutOrder or 0, Parent = p.Parent,
	}, {
		UIKit.new("UIStroke", { Thickness = p.StrokeThickness or 3, Color = p.StrokeColor or C.Outline, LineJoinMode = Enum.LineJoinMode.Round }),
		UIKit.new("UITextSizeConstraint", { MaxTextSize = p.MaxTextSize or 40, MinTextSize = p.MinTextSize or 1 }),
	})
	if not p.Font then lbl:SetAttribute("AutoFont", Theme.Font.Name) end
	if p.Gradient then UIKit.new("UIGradient", { Color = p.Gradient, Rotation = 90, Parent = lbl }) end
	return lbl
end

function UIKit.setText(lbl, text)
	text = tostring(text)
	lbl.Text = text
	local auto = lbl:GetAttribute("AutoFont")
	if auto then lbl.Font = UIKit.fontFor(text, Enum.Font[auto]) end
	if lbl.Name == "Front" and lbl.Parent then
		local sh = lbl.Parent:FindFirstChild("Shadow")
		if sh and sh:IsA("TextLabel") then sh.Text, sh.Font = text, lbl.Font end
	end
end

-- หัวข้อตัวใหญ่มีเงาดำเยื้อง (คืนค่า front, holder, shadow)
function UIKit.title(p)
	local holder = UIKit.new("Frame", {
		Name = p.Name or "Title", BackgroundTransparency = 1, Size = p.Size or UDim2.fromScale(1, 0.15),
		Position = p.Position or UDim2.new(), AnchorPoint = p.AnchorPoint or Vector2.zero,
		Rotation = p.Tilt or Theme.Tilt, ZIndex = p.ZIndex or 1, LayoutOrder = p.LayoutOrder or 0, Parent = p.Parent,
	})
	local off, z = p.ShadowOffset or 5, holder.ZIndex
	local shadow = UIKit.label({ Name = "Shadow", Text = p.Text, Font = p.Font, Color = C.Outline, StrokeThickness = p.StrokeThickness or 4,
		MaxTextSize = p.MaxTextSize or 72, Position = UDim2.fromOffset(off, off), ZIndex = z, Parent = holder })
	local front = UIKit.label({ Name = "Front", Text = p.Text, Font = p.Font, Color = p.Color or C.Yellow, Gradient = p.Gradient,
		StrokeThickness = p.StrokeThickness or 4, MaxTextSize = p.MaxTextSize or 72, ZIndex = z + 1, Parent = holder })
	return front, holder, shadow
end

-- ตัวหนังสือเด้งดึ๋ง + บิดนิดๆ
function UIKit.bounceText(lbl, text, amount)
	if text ~= nil then UIKit.setText(lbl, text) end
	local target = (lbl.Name == "Front" and lbl.Parent) or lbl
	local s = UIKit.getScale(target)
	s.Scale = 1 + (amount or 0.35)
	UIKit.tween(s, 0.45, { Scale = 1 }, Enum.EasingStyle.Elastic)
	local base = target:GetAttribute("BaseRot")
	if base == nil then base = target.Rotation; target:SetAttribute("BaseRot", base) end
	target.Rotation = base + (math.random() < 0.5 and -8 or 8)
	UIKit.tween(target, 0.4, { Rotation = base }, Enum.EasingStyle.Elastic)
end

function UIKit.countTo(lbl, from, to, duration, fmt)
	fmt = fmt or "%d"
	local nv = Instance.new("NumberValue")
	nv.Value = from
	nv.Changed:Connect(function(v) if lbl.Parent then lbl.Text = string.format(fmt, math.floor(v + 0.5)) end end)
	local t = UIKit.tween(nv, duration or 0.5, { Value = to })
	t.Completed:Connect(function()
		nv:Destroy()
		if lbl.Parent then UIKit.bounceText(lbl, string.format(fmt, math.floor(to + 0.5)), 0.25) end
	end)
	return t
end

-- กล่องการ์ตูน: เงาดำทึบเยื้อง + ขอบหนา (คืน holder, face)
function UIKit.comicBox(p)
	local off = p.ShadowOffset or Theme.ShadowOffset
	local holder = UIKit.new("Frame", {
		Name = p.Name or "ComicBox", BackgroundTransparency = 1, Size = p.Size or UDim2.fromScale(1, 1),
		Position = p.Position or UDim2.new(), AnchorPoint = p.AnchorPoint or Vector2.zero, Rotation = p.Tilt or 0,
		ZIndex = p.ZIndex or 1, LayoutOrder = p.LayoutOrder or 0, Parent = p.Parent,
	})
	local z = holder.ZIndex
	UIKit.new("Frame", { Name = "Shadow", BackgroundColor3 = C.Shadow, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromOffset(off, off), ZIndex = z, Parent = holder }, { UIKit.corner(p.Radius) })
	local face = UIKit.new("Frame", { Name = "Face", BackgroundColor3 = p.Color or C.Panel, BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1), ZIndex = z + 1, ClipsDescendants = p.Clip or false, Parent = holder },
		{ UIKit.corner(p.Radius), UIKit.stroke(C.Outline, p.StrokeThickness or Theme.Stroke) })
	return holder, face
end

-- ปุ่มนูน 3D แบบเกมมือถือ: หน้าปุ่มยุบลงตอนกด
function UIKit.button(p)
	local color, lip = p.Color or C.Yellow, p.Lip or 6
	local btn = UIKit.new("TextButton", {
		Name = p.Name or "Button", Size = p.Size or UDim2.fromScale(0.2, 0.1), Position = p.Position or UDim2.new(),
		AnchorPoint = p.AnchorPoint or Vector2.zero, BackgroundColor3 = C.Outline, AutoButtonColor = false, Text = "",
		Rotation = p.Tilt or 0, ZIndex = p.ZIndex or 1, LayoutOrder = p.LayoutOrder or 0, Parent = p.Parent,
	}, { UIKit.corner(p.Radius) })
	local st = UIKit.stroke(C.Outline, p.StrokeThickness or 3)
	st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	st.Parent = btn
	btn:SetAttribute("BaseColor", color)

	local face = UIKit.new("Frame", { Name = "Face", BackgroundColor3 = color, BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 1, -lip), ZIndex = btn.ZIndex, Parent = btn }, {
		UIKit.corner(p.Radius),
		UIKit.new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(205, 205, 205)) }),
	})
	UIKit.new("Frame", { Name = "Gloss", BackgroundColor3 = C.White, BackgroundTransparency = 0.55, BorderSizePixel = 0,
		Size = UDim2.new(1, -16, 0.2, 0), Position = UDim2.new(0, 8, 0, 4), ZIndex = btn.ZIndex, Parent = face },
		{ UIKit.corner(UDim.new(1, 0)) })
	local label = UIKit.label({ Name = "Label", Text = p.Text, Font = p.Font, Color = p.TextColor or C.White,
		Size = UDim2.fromScale(0.88, 0.78), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		MaxTextSize = p.MaxTextSize, Tilt = p.TextTilt or -2, ZIndex = btn.ZIndex, Parent = face })

	local scale, pressed, busy = UIKit.getScale(btn), false, false
	local function press(on)
		pressed = on
		UIKit.tween(face, 0.06, { Position = UDim2.fromOffset(0, on and lip - 1 or 0) })
	end
	btn.MouseEnter:Connect(function()
		if btn:GetAttribute("Disabled") then return end
		UIKit.tween(scale, 0.15, { Scale = 1.06 }, Enum.EasingStyle.Back)
		UIKit.sfx("Hover", 0.15)
	end)
	btn.MouseLeave:Connect(function()
		UIKit.tween(scale, 0.15, { Scale = 1 })
		if pressed then press(false) end
	end)
	btn.MouseButton1Down:Connect(function() if not btn:GetAttribute("Disabled") then press(true) end end)
	btn.MouseButton1Up:Connect(function() if pressed then press(false) end end)
	btn.Activated:Connect(function()
		if btn:GetAttribute("Disabled") then UIKit.shake(btn); UIKit.sfx("Honk", 0.1) return end
		if busy then return end
		UIKit.sfx("Click", 0.12)
		UIKit.jelly(btn, 0.12)
		if p.OnClick then
			if p.Debounce then
				busy = true
				local ok, err = pcall(p.OnClick, btn)
				if not ok then warn("[UIKit.button] OnClick error: " .. tostring(err)) end
				task.wait(UIKit.dur(p.Debounce == true and 0.35 or p.Debounce))
				busy = false
			else
				p.OnClick(btn)
			end
		end
	end)
	return btn, label
end

function UIKit.setColor(btn, color)
	local face = btn:FindFirstChild("Face")
	if not face then btn.BackgroundColor3 = color return end
	btn:SetAttribute("BaseColor", color)
	if not btn:GetAttribute("Disabled") then UIKit.tween(face, 0.15, { BackgroundColor3 = color }) end
end

function UIKit.setDisabled(btn, disabled)
	btn:SetAttribute("Disabled", disabled and true or nil)
	local face = btn:FindFirstChild("Face")
	if not face then return end
	local base = btn:GetAttribute("BaseColor") or C.Yellow
	face.BackgroundColor3 = disabled and base:Lerp(C.Gray, 0.75) or base
	local lbl = face:FindFirstChild("Label")
	if lbl then lbl.TextTransparency = disabled and 0.35 or 0 end
end

function UIKit.shake(gui, power)
	if gui:GetAttribute("Shaking") then return end
	gui:SetAttribute("Shaking", true)
	local origin, rot, k = gui.Position, gui.Rotation, power or 7
	task.spawn(function()
		for i = 1, 7 do
			if not gui.Parent then return end
			local f = k * (1 - i / 8)
			gui.Position = origin + UDim2.fromOffset((math.random() * 2 - 1) * f, (math.random() * 2 - 1) * f * 0.5)
			gui.Rotation = rot + (math.random() * 2 - 1) * f * 0.6
			task.wait(0.03)
		end
		gui.Position, gui.Rotation = origin, rot
		gui:SetAttribute("Shaking", nil)
	end)
end

function UIKit.jelly(gui, amount)
	local s = UIKit.getScale(gui)
	s.Scale = 1 + (amount or 0.15)
	UIKit.tween(s, 0.5, { Scale = 1 }, Enum.EasingStyle.Elastic)
end

-- ตัวเลขดาเมจ/คำอุทานเด้งขึ้นแล้วจางหาย
function UIKit.popup(parent, text, color)
	if not parent then return end
	text = tostring(text)
	local lbl = UIKit.label({ Name = "Popup", Text = text, Font = UIKit.fontFor(text, Theme.FontAlt), Color = color or C.Yellow,
		StrokeThickness = 4, MaxTextSize = 64, Size = UDim2.fromScale(1.3, 0.4), AnchorPoint = CENTER,
		Position = UDim2.fromScale(0.5 + (math.random() - 0.5) * 0.3, 0.45), Tilt = (math.random() - 0.5) * 20, ZIndex = 60, Parent = parent })
	local s = UIKit.getScale(lbl)
	s.Scale = 0.2
	UIKit.tween(s, 0.35, { Scale = 1 }, Enum.EasingStyle.Back)
	UIKit.tween(lbl, 0.9, { Position = lbl.Position - UDim2.fromScale(0, 0.45) })
	task.delay(UIKit.dur(0.55), function()
		if not lbl.Parent then return end
		UIKit.tween(lbl, 0.35, { TextTransparency = 1 })
		local st = lbl:FindFirstChildOfClass("UIStroke")
		if st then UIKit.tween(st, 0.35, { Transparency = 1 }) end
	end)
	Debris:AddItem(lbl, UIKit.dur(1) + 0.2)
	return lbl
end

function UIKit.rain(parent, emoji, count)
	if not parent or not UIKit.effectsOn() then return end
	for _ = 1, count or 16 do
		task.delay(math.random() * 0.6, function()
			if not parent.Parent then return end
			local sz = math.random(28, 56)
			local l = UIKit.new("TextLabel", { BackgroundTransparency = 1, Text = emoji, TextScaled = true, Size = UDim2.fromOffset(sz, sz),
				AnchorPoint = CENTER, Position = UDim2.fromScale(math.random(), -0.1), Rotation = math.random(-40, 40), ZIndex = 80, Parent = parent })
			local d = 1.4 + math.random() * 0.8
			UIKit.tween(l, d, { Position = UDim2.fromScale(l.Position.X.Scale + (math.random() - 0.5) * 0.2, 1.15),
				Rotation = l.Rotation + math.random(-180, 180) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			Debris:AddItem(l, UIKit.dur(d) + 0.1)
		end)
	end
end

local toastGui, toastN = nil, 0
local function toastRoot()
	if UIKit.toastParent and UIKit.toastParent.Parent then
		local host = UIKit.toastParent:FindFirstChild("KitToastHost")
		if not host then
			host = UIKit.new("Frame", { Name = "KitToastHost", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 500,
				Parent = UIKit.toastParent }, {
				UIKit.new("UIListLayout", { Padding = UDim.new(0, 10), HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }),
				UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 72) }),
			})
		end
		return host
	end
	if toastGui and toastGui.Parent then return toastGui end
	local lp = Players.LocalPlayer
	local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
	if not pg then return nil end
	toastGui = UIKit.new("ScreenGui", { Name = "KitToasts", DisplayOrder = 500, ResetOnSpawn = false, IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Parent = pg }, {
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 10), HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 72) }),
	})
	return toastGui
end

function UIKit.toast(text, color)
	local root = toastRoot()
	if not root then return end
	toastN += 1
	local slot = UIKit.new("Frame", { Name = "Toast", BackgroundTransparency = 1, Size = UDim2.new(0.42, 0, 0, 56), LayoutOrder = toastN, Parent = root },
		{ UIKit.new("UISizeConstraint", { MaxSize = Vector2.new(520, 56) }) })
	local holder, face = UIKit.comicBox({ Parent = slot, Color = color or C.Yellow, Tilt = (toastN % 2 == 0) and 1.5 or -1.5, ShadowOffset = 5 })
	UIKit.label({ Text = text, Size = UDim2.new(1, -24, 1, -12), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER, MaxTextSize = 26, Parent = face })
	local s = UIKit.getScale(holder)
	s.Scale = 0.2
	UIKit.tween(s, 0.35, { Scale = 1 }, Enum.EasingStyle.Back)
	UIKit.sfx("Pop", 0.2)
	local list = {}
	for _, ch in ipairs(root:GetChildren()) do if ch.Name == "Toast" then table.insert(list, ch) end end
	table.sort(list, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
	for i = 1, #list - 4 do list[i]:Destroy() end
	task.delay(2.4, function()
		if not slot.Parent then return end
		UIKit.tween(s, 0.2, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		task.wait(UIKit.dur(0.22))
		slot:Destroy()
	end)
end

-- หน้าต่าง modal: ริบบิ้นหัวข้อเอียง + ปุ่ม X (คืน panel, close, backdrop)
function UIKit.panel(parent, title, color)
	local back = UIKit.new("TextButton", { Name = "PanelBackdrop", Text = "", AutoButtonColor = false, BackgroundColor3 = C.TableDark,
		BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 40, Parent = parent })
	UIKit.tween(back, 0.2, { BackgroundTransparency = 0.3 })
	local holder, panel = UIKit.comicBox({ Name = "PanelHolder", Parent = back, Size = UDim2.fromScale(0.74, 0.8),
		Position = UDim2.fromScale(0.5, 0.54), AnchorPoint = CENTER, Color = C.Panel, ShadowOffset = 10, StrokeThickness = 4, ZIndex = 41 })
	panel.Name = "Panel"
	panel:SetAttribute("IsKitPanel", true)
	local _, ribbon = UIKit.comicBox({ Name = "Ribbon", Parent = holder, Size = UDim2.new(0.5, 0, 0, 56), Position = UDim2.new(0.5, 0, 0, -18),
		AnchorPoint = CENTER, Color = color or C.Pink, Tilt = -3, ZIndex = 45 })
	UIKit.label({ Text = title or "", Size = UDim2.new(1, -20, 1, -10), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		MaxTextSize = 34, StrokeThickness = 4, Parent = ribbon })
	local function close()
		if not back.Parent then return end
		UIKit.sfx("Whoosh")
		UIKit.tween(UIKit.getScale(holder), 0.18, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		UIKit.tween(back, 0.18, { BackgroundTransparency = 1 })
		task.delay(UIKit.dur(0.2), function() if back.Parent then back:Destroy() end end)
	end
	UIKit.button({ Name = "Close", Parent = holder, Text = "X", Color = C.Red, Size = UDim2.fromOffset(52, 52),
		Position = UDim2.new(1, -8, 0, 8), AnchorPoint = CENTER, Radius = UDim.new(1, 0), Tilt = 8, ZIndex = 46, OnClick = close })
	panel.Destroying:Connect(function() if back.Parent then back:Destroy() end end)
	local s = UIKit.getScale(holder)
	s.Scale = 0.5
	UIKit.tween(s, 0.4, { Scale = 1 }, Enum.EasingStyle.Back)
	UIKit.sfx("Whoosh")
	return panel, close, back
end

function UIKit.badge(parent, text, color, p)
	p = p or {}
	local f = UIKit.new("Frame", { Name = p.Name or "Badge", BackgroundColor3 = color or C.Yellow, Size = p.Size or UDim2.fromOffset(90, 30),
		Position = p.Position or UDim2.new(), AnchorPoint = p.AnchorPoint or Vector2.zero, Rotation = p.Tilt or -4,
		ZIndex = p.ZIndex or 5, Parent = parent }, { UIKit.corner(UDim.new(1, 0)), UIKit.stroke(C.Outline, 3) })
	local l = UIKit.label({ Name = "Label", Text = text, Size = UDim2.new(1, -10, 1, -4), Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = CENTER, MaxTextSize = p.MaxTextSize or 20, ZIndex = f.ZIndex, Parent = f })
	return f, l
end

function UIKit.tierBadge(parent, rarity, size)
	local tier = Theme.RarityTier[rarity] or 1
	local f = UIKit.new("Frame", { Name = "TierBadge", BackgroundColor3 = Theme.Rarity[rarity] or C.Gray, Size = size or UDim2.fromOffset(30, 30),
		AnchorPoint = CENTER, Rotation = 45, ZIndex = 30, Parent = parent },
		{ UIKit.corner(6), UIKit.stroke(C.Outline, 3), UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1 }) })
	UIKit.label({ Text = "T" .. tier, Size = UDim2.fromScale(1.1, 0.8), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		Tilt = -45, MaxTextSize = 18, ZIndex = 31, Parent = f })
	f:SetAttribute("Tier", tier)
	return f
end

return UIKit]]
SOURCES["ServerScriptService/CardValidator.server.lua"] = [[
-- ServerScriptService/CardValidator (Script)
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared.Config)
local Rules = require(Shared.Rules)
local Cards = require(Shared.CardData)
local Decks = require(Shared.Decks)

local SPELL_KINDS = { Shield = true, Slime = true, Damage = true, Heal = true, Buff = true, Mystery = true, Bomb = true }
local TARGETS = { None = true, EnemyChar = true, AllyChar = true, Ally = true }
local ABILITIES = { Reroll = true, LuckyPoop = true, ExtraPoints = true }
local ELEMENTS = { Sati = true, Biao = true, Muen = true, Gawa = true }

local problems = 0
local function bad(msg)
	problems += 1
	warn("[CardValidator] ❌ " .. msg)
end

for id, c in Cards do
	local name = tostring(c.Name or id)
	local cost = c.Cost or 0
	if typeof(c.Cost) ~= "number" or c.Cost < 0 then bad(name .. ": ไม่มีค่าพอยต์ (Cost)") end

	if c.Type == "Character" then
		local keywords = c.Keywords or {}
		local budget = cost * 3 + 2
		local used = (c.ATK or 0) + (c.HP or 0) + #keywords * Config.KEYWORD_COST
		if used > budget then
			bad(("%s: โกง ใช้ %d/%d แต้ม"):format(name, used, budget))
		elseif used < budget then
			print(("[CardValidator] ℹ️ %s: อ่อนไป ใช้ %d/%d แต้ม"):format(name, used, budget))
		end
		if (c.HP or 0) <= 0 then bad(name .. ": HP ต้องมากกว่า 0") end
		if not ELEMENTS[c.Element] then bad(name .. ": ธาตุไม่ถูกต้อง") end
		for _, kw in keywords do
			if not Rules.Keywords[kw] then bad(name .. ": ไม่รู้จักคีย์เวิร์ด " .. tostring(kw)) end
		end
	elseif c.Type == "Spell" then
		local e = c.Effect
		if typeof(e) ~= "table" or not SPELL_KINDS[e.Kind] then
			bad(name .. ": Effect.Kind ไม่ถูกต้อง")
		else
			if not TARGETS[e.Target or "None"] then bad(name .. ": Effect.Target ไม่ถูกต้อง") end
			local value, budget = e.Value or 0, cost * 2
			if (e.Kind == "Damage" or e.Kind == "Heal") and value > budget then
				bad(("%s: แรงเกิน %d (ควร ≤ %d)"):format(name, value, budget))
			elseif e.Kind == "Buff" and value * 2 > budget then
				bad(("%s: บัฟแรงเกิน"):format(name))
			elseif e.Kind == "Shield" and (cost ~= 0 or value > 3) then
				bad(name .. ": โล่ต้องใช้ 0 พอยต์ และกันได้ไม่เกิน 3")
			end
		end
	elseif c.Type == "Weapon" then
		local budget = cost * 2 - (c.Freeze and 2 or 0)
		if (c.Bonus or 0) > budget then bad(("%s: อาวุธแรงเกิน %d (ควร ≤ %d)"):format(name, c.Bonus or 0, budget)) end
	elseif c.Type == "Leader" then
		if not ABILITIES[c.Ability] then bad(name .. ": สกิลผู้นำไม่ถูกต้อง") end
	else
		bad(name .. ": ประเภทการ์ดไม่ถูกต้อง " .. tostring(c.Type))
	end
end

local counts, shields = {}, 0
for _, id in Decks.Starter do
	local c = Cards[id]
	if not c then
		bad("เด็คเริ่มต้นมีการ์ดที่ไม่มีอยู่จริง: " .. tostring(id))
	else
		counts[c.Type] = (counts[c.Type] or 0) + 1
		if c.Effect and c.Effect.Kind == "Shield" then shields += 1 end
	end
end
for cardType, need in Config.DECK_COMPOSITION do
	if (counts[cardType] or 0) ~= need then
		bad(("เด็คเริ่มต้น: %s มี %d ใบ (ต้องมี %d)"):format(cardType, counts[cardType] or 0, need))
	end
end
if shields > Config.MAX_SHIELDS_IN_DECK then bad("เด็คเริ่มต้นมีโล่เกิน " .. Config.MAX_SHIELDS_IN_DECK .. " ใบ") end
for _, id in Decks.Leaders do
	if not (Cards[id] and Cards[id].Type == "Leader") then bad("ผู้นำไม่ถูกต้อง: " .. tostring(id)) end
end

if problems == 0 then
	print("[CardValidator] ✅ การ์ดและเด็คถูกต้องทั้งหมด")
else
	warn(("[CardValidator] เจอปัญหา %d จุด แก้ก่อนเปิดเกม"):format(problems))
end
]]
SOURCES["ServerScriptService/GameServer.server.lua"] = [[
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local StarterPlayer = game:GetService("StarterPlayer")
local ServerScriptService = game:GetService("ServerScriptService")

-- 0) ลบสคริปต์เก่าที่ค้าง
do
	local function purge(parent, name)
		local old = parent and parent:FindFirstChild(name)
		if old then
			warn(("[GameServer] พบ %s เก่าค้างอยู่ ลบทิ้งให้แล้ว"):format(name))
			old:Destroy()
		end
	end
	purge(ServerScriptService, "MatchHandler")
	purge(ServerScriptService, "MatchService")
	purge(ServerStorage:FindFirstChild("Modules"), "MatchRegistry")
end

-- 1) Remotes
local REMOTES = {
	RemoteFunction = { "PlayCard", "Attack", "Queue", "GetStats", "GetProfile", "SaveDeck", "Gacha", "ClaimQuest", "GetFarms", "ClaimFarm", "UpgradeFarm" },
	RemoteEvent = { "EndTurn", "Surrender", "StateUpdate", "GateRolled", "MatchEnded", "Notify", "ProfileChanged" },
}
local Remotes = ReplicatedStorage:FindFirstChild("Remotes")
if not Remotes then
	Remotes = Instance.new("Folder")
	Remotes.Name = "Remotes"
end
for className, names in REMOTES do
	for _, name in names do
		local existing = Remotes:FindFirstChild(name)
		if existing and not existing:IsA(className) then existing:Destroy() existing = nil end
		if not existing then
			local r = Instance.new(className)
			r.Name = name
			r.Parent = Remotes
		end
	end
end
for _, child in Remotes:GetChildren() do
	local keep = false
	for _, names in REMOTES do
		if table.find(names, child.Name) then keep = true break end
	end
	if not keep then child:Destroy() end
end
Remotes.Parent = ReplicatedStorage

-- 2) โมดูล
local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared.Config)
local CardData = require(Shared.CardData)
local Decks = require(Shared.Decks)
local DeckRules = require(Shared.DeckRules)
local Modules = ServerStorage:WaitForChild("Modules")
local Match = require(Modules.Match)
local DataService = require(Modules.DataService)
local Stats = require(Modules.StatsService)
local Guard = require(Modules.Guard)
local GachaService = require(Modules.GachaService)
local QuestService = require(Modules.QuestService)
local FarmService = require(Modules.FarmService)

-- 2.1) รวม Broadcast ให้เหลือครั้งเดียวต่อรอบ (ตัวการหลักที่ทำให้แลกตอนกดรัว)
do
	local rawBroadcast = Match.Broadcast
	Match.Broadcast = function(self)
		if self._broadcastQueued then return end
		self._broadcastQueued = true
		task.defer(function()
			self._broadcastQueued = false
			local ok, err = pcall(rawBroadcast, self)
			if not ok then warn("[GameServer] Broadcast error: " .. tostring(err)) end
		end)
	end
end

local ActiveMatches = {}
local waiting = nil

local function isId(v) return typeof(v) == "string" and #v > 0 and #v <= 64 end
local function isLeader(id)
	local c = isId(id) and CardData[id]
	return c and c.Type == "Leader"
end

local function lockMovement(player, locked)
	if typeof(player) ~= "Instance" then return end
	local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
	if not hum then return end
	hum.WalkSpeed = locked and 0 or StarterPlayer.CharacterWalkSpeed
	hum.JumpHeight = locked and 0 or StarterPlayer.CharacterJumpHeight
	hum.JumpPower = locked and 0 or StarterPlayer.CharacterJumpPower
end

-- 3) โปรไฟล์ / เควสต์
local function snapshot(player)
	local data = DataService.GetData(player)
	if not data then return nil end
	QuestService.Ensure(data, player.UserId)
	return {
		Gems = data.Gems, Collection = table.clone(data.Collection), Deck = table.clone(data.Deck),
		Pity = table.clone(data.Pity), Quests = QuestService.View(data),
	}
end

local pushPending = {}
local function pushProfile(player)
	if typeof(player) ~= "Instance" or pushPending[player] then return end
	pushPending[player] = true
	task.delay(0.2, function()
		pushPending[player] = nil
		if player.Parent then
			local snap = snapshot(player)
			if snap then Remotes.ProfileChanged:FireClient(player, snap) end
		end
	end)
end
DataService.OnChanged = pushProfile

local function trackQuest(player, event, amount)
	if typeof(player) ~= "Instance" then return end
	local data = DataService.GetData(player)
	if data and QuestService.Track(data, player.UserId, event, amount or 1) then pushProfile(player) end
end

local function deckFor(player)
	if typeof(player) ~= "Instance" then return Decks.Starter end
	local data = DataService.GetData(player)
	if data and DeckRules.Validate(data.Deck, data.Collection) then return table.clone(data.Deck) end
	return Decks.Starter
end

-- 4) สถิติ / จบแมตช์
local function recordMatchStats(m, player, won, reason, gems, bounty)
	local data = DataService.GetData(player)
	if not data then return end
	local mode = m.Mode == "PvP" and "PvP" or "Bot"
	local sec = math.max(0, math.floor(os.clock() - (m.startedAt or os.clock())))
	local side = m.sides[player]
	local outcome = won == true and "Win" or (won == false and "Loss" or "Draw")

	Stats.Add(data, "Matches")
	Stats.Add(data, "Matches" .. mode)
	Stats.Add(data, outcome .. "s")
	Stats.Add(data, outcome .. "s" .. mode)
	Stats.Add(data, "PlaySec", sec)
	Stats.Max(data, "LongestMatchSec", sec)
	if won == true then
		Stats.Add(data, "WinSec", sec)
		Stats.Min(data, "ShortestWinSec", math.max(sec, 1))
	elseif won == false then
		Stats.Add(data, "LossSec", sec)
	end
	if m.firstPlayer == player then
		Stats.Add(data, "MatchesGoingFirst")
		if won == true then Stats.Add(data, "WinsGoingFirst") end
	end
	if won == false then
		if reason == "SURRENDER" then Stats.Add(data, "Surrenders")
		elseif reason == "AFK_LIGHTNING" then Stats.Add(data, "AfkLosses")
		elseif reason == "LEFT" then Stats.Add(data, "Disconnects") end
	elseif won == true and reason == "LEFT" then
		Stats.Add(data, "OpponentLeft")
	end
	if side then
		Stats.Leader(data, side.leader.Id, "Matches")
		Stats.Leader(data, side.leader.Id, outcome .. "s")
	end
	if gems and gems > 0 then
		Stats.Add(data, "GemsEarned", gems)
		Stats.Max(data, "BestGemsOneMatch", gems)
	end
	if bounty and bounty > 0 then Stats.Add(data, "BountyEarned", bounty) end
end

local function onMatchEnded(m, winner, reason)
	for _, p in m.players do
		if ActiveMatches[p] == m then ActiveMatches[p] = nil end
		lockMovement(p, false)
	end
	local rewards = {}
	local loser = m:Opponent(winner)
	local bounty = 0
	if m.Mode == "PvP" then
		bounty = DataService.GetStreak(loser) * Config.BOUNTY_PER_STREAK
		DataService.RecordResult(winner, true)
		DataService.RecordResult(loser, false)
		rewards[winner] = DataService.AddGems(winner, Config.REWARD_WIN_PVP + bounty)
		rewards[loser] = DataService.AddGems(loser, Config.REWARD_LOSE_PVP)
		if bounty > 0 then m:Notify(("ล้มคนติดค่าหัวได้ โบนัส %d เพชร"):format(bounty), "Yellow") end
	elseif typeof(winner) == "Instance" then
		rewards[winner] = DataService.AddGems(winner, Config.REWARD_WIN_BOT)
	end
	for _, p in m.players do
		if typeof(p) == "Instance" then
			local isWinner = p == winner
			local ok, err = pcall(recordMatchStats, m, p, isWinner, reason, rewards[p], isWinner and bounty or 0)
			if not ok then warn("[GameServer] บันทึกสถิติไม่สำเร็จ: " .. tostring(err)) end
			trackQuest(p, "MatchPlayed")
			if isWinner then
				trackQuest(p, "MatchWon")
				if m.Mode == "PvP" then trackQuest(p, "PvPWon") end
			end
		end
	end
	return rewards
end

local function startMatch(p1, leader1, p2, leader2, mode)
	local ok, m = pcall(Match.new, p1, p2, deckFor(p1), deckFor(p2), leader1, leader2)
	if not ok then
		warn("[GameServer] สร้างแมตช์ไม่สำเร็จ: " .. tostring(m))
		return false
	end
	m.Mode = mode
	m.OnEnded = onMatchEnded
	m.GetData = DataService.GetData
	for _, p in m.players do
		if typeof(p) == "Instance" then
			ActiveMatches[p] = m
			lockMovement(p, true)
		end
	end
	local started, err = pcall(m.Start, m)
	if not started then
		warn("[GameServer] เริ่มแมตช์ไม่สำเร็จ: " .. tostring(err))
		m.ended = true
		for _, p in m.players do
			if ActiveMatches[p] == m then ActiveMatches[p] = nil end
			lockMovement(p, false)
		end
		return false
	end
	return true
end

-- คำสั่งในแมตช์: ล็อก "match" ต่อผู้เล่น (ไม่ warn ตอนถูกปฏิเสธ เพราะทำให้เซิร์ฟช้าเวลาโดนสแปม)
local function guarded(player, method, ...)
	local m = ActiveMatches[player]
	if not m or m.ended then return false, "NO_MATCH" end
	local a, b = Guard.Run(player, "match", m[method], m, player, ...)
	return a == true, b
end

-- 5) Remotes
local function queueImpl(player, mode, leaderId)
	if mode == "Cancel" then
		if waiting and waiting.player == player then
			waiting = nil
			Stats.Add(DataService.GetData(player), "QueueCancel")
		end
		return true, "CANCELLED"
	end
	if ActiveMatches[player] then return false, "IN_MATCH" end
	if mode ~= "Bot" and mode ~= "PvP" then return false, "BAD_MODE" end
	if not isLeader(leaderId) then return false, "BAD_LEADER" end
	if not DataService.IsLoaded(player) then return false, "DATA_LOADING" end

	if mode == "Bot" then
		if waiting and waiting.player == player then waiting = nil end
		Stats.Add(DataService.GetData(player), "QueueBot")
		local bot = { Name = "หุ่นฝึกซ้อม", IsBot = true }
		local botLeader = Decks.Leaders[math.random(#Decks.Leaders)]
		if not startMatch(player, leaderId, bot, botLeader, "Bot") then return false, "SERVER_ERROR" end
		return true, "STARTED"
	end

	Stats.Add(DataService.GetData(player), "QueuePvP")
	local other = waiting
	if other and other.player ~= player and other.player.Parent and not ActiveMatches[other.player] then
		waiting = nil
		if not startMatch(other.player, other.leader, player, leaderId, "PvP") then return false, "SERVER_ERROR" end
		local waited = math.max(0, math.floor(os.clock() - (other.since or os.clock())))
		local d1, d2 = DataService.GetData(other.player), DataService.GetData(player)
		Stats.Add(d1, "QueueMatched") Stats.Add(d1, "QueueWaitSec", waited) Stats.Add(d1, "QueueWaitCount")
		Stats.Add(d2, "QueueMatched") Stats.Add(d2, "QueueWaitCount")
		return true, "STARTED"
	end
	waiting = { player = player, leader = leaderId, since = os.clock() }
	return true, "WAITING"
end

Remotes.Queue.OnServerInvoke = function(player, mode, leaderId)
	if not Guard.Allow(player, "Queue", 0.5) then return false, "SLOW_DOWN" end
	return Guard.Run(player, "queue", queueImpl, player, mode, leaderId)
end

Remotes.GetStats.OnServerInvoke = function(player)
	if not Guard.Allow(player, "GetStats", 1) then return nil end
	return DataService.GetStats(player)
end

Remotes.GetProfile.OnServerInvoke = function(player)
	if not Guard.Allow(player, "GetProfile", 0.5) then return nil end
	return snapshot(player)
end

Remotes.PlayCard.OnServerInvoke = function(player, uid, target)
	if not Guard.Allow(player, "PlayCard", 0.12) then return false, "SLOW_DOWN" end
	if not isId(uid) then return false, "INVALID_CARD" end
	if target ~= nil and not isId(target) then return false, "INVALID_TARGET" end
	local m = ActiveMatches[player]
	local cardType
	local side = m and m.sides and m.sides[player]
	if side then
		for _, c in side.hand do
			if c.Uid == uid then cardType = c.Type break end
		end
	end
	local ok, code = guarded(player, "PlayCard", uid, target)
	if ok then
		trackQuest(player, "CardPlayed")
		if cardType == "Spell" then trackQuest(player, "SpellPlayed") end
		if target == "Gate" then trackQuest(player, "GatePlayed") end
	end
	return ok, code
end

Remotes.Attack.OnServerInvoke = function(player, attackerUid, targetUid)
	if not Guard.Allow(player, "Attack", 0.12) then return false, "SLOW_DOWN" end
	if not isId(attackerUid) or not isId(targetUid) then return false, "INVALID_TARGET" end
	local ok, code = guarded(player, "Attack", attackerUid, targetUid)
	if ok then trackQuest(player, "Attack") end
	return ok, code
end

Remotes.EndTurn.OnServerEvent:Connect(function(player)
	if Guard.Allow(player, "EndTurn", 0.4) then guarded(player, "EndTurn", false) end
end)

Remotes.Surrender.OnServerEvent:Connect(function(player)
	if Guard.Allow(player, "Surrender", 1) then guarded(player, "Surrender") end
end)

Remotes.Gacha.OnServerInvoke = function(player, count)
	if not Guard.Allow(player, "Gacha", 0.6) then return false, "SLOW_DOWN" end
	if count ~= 1 and count ~= 10 then return false, "BAD_COUNT" end
	local data = DataService.GetData(player)
	if not data then return false, "DATA_LOADING" end
	local ok, res = Guard.Run(player, "profile", GachaService.Pull, data, count)
	if ok then
		QuestService.Track(data, player.UserId, "GachaPull", count)
		DataService.Touch(player)
	end
	return ok, res
end

-- ===== ฟาร์ม =====
Remotes.GetFarms.OnServerInvoke = function(player)
	if not Guard.Allow(player, "GetFarms", 0.5) then return false, "SLOW_DOWN" end
	local data = DataService.GetData(player)
	if not data then return false, "DATA_LOADING" end
	return true, FarmService.List(data)
end

Remotes.ClaimFarm.OnServerInvoke = function(player, id)
	if not Guard.Allow(player, "ClaimFarm", 0.5) then return false, "SLOW_DOWN" end
	local data = DataService.GetData(player)
	if not data then return false, "DATA_LOADING" end
	local ok, res = FarmService.Claim(data, id)
	if ok then DataService.Touch(player) end
	return ok, res
end

Remotes.UpgradeFarm.OnServerInvoke = function(player, id)
	if not Guard.Allow(player, "UpgradeFarm", 0.5) then return false, "SLOW_DOWN" end
	local data = DataService.GetData(player)
	if not data then return false, "DATA_LOADING" end
	local ok, res = FarmService.Upgrade(data, id)
	if ok then DataService.Touch(player) end
	return ok, res
end

Remotes.SaveDeck.OnServerInvoke = function(player, ids)
	if not Guard.Allow(player, "SaveDeck", 1) then return false, "SLOW_DOWN" end
	local data = DataService.GetData(player)
	if not data then return false, "DATA_LOADING" end
	if typeof(ids) ~= "table" or #ids > 64 then return false, "ข้อมูลเด็คไม่ถูกต้อง" end
	local clean = {}
	for i = 1, #ids do clean[i] = ids[i] end
	local ok, err = DeckRules.Validate(clean, data.Collection)
	if not ok then return false, err end
	data.Deck = clean
	pushProfile(player)
	return true
end

Remotes.ClaimQuest.OnServerInvoke = function(player, questId)
	if not Guard.Allow(player, "ClaimQuest", 0.3) then return false, "SLOW_DOWN" end
	if not isId(questId) then return false, "BAD_QUEST" end
	local data = DataService.GetData(player)
	if not data then return false, "DATA_LOADING" end
	local ok, res = QuestService.Claim(data, player.UserId, questId)
	if ok then DataService.Touch(player) end
	return ok, res
end

-- 6) เข้า/ออกเกม
Players.PlayerAdded:Connect(DataService.Load)
for _, p in Players:GetPlayers() do task.spawn(DataService.Load, p) end

Players.PlayerRemoving:Connect(function(p)
	if waiting and waiting.player == p then waiting = nil end
	local m = ActiveMatches[p]
	if m and not m.ended then pcall(m.EndMatch, m, m:Opponent(p), "LEFT") end
	ActiveMatches[p] = nil
	pushPending[p] = nil
	DataService.Release(p)
end)

game:BindToClose(DataService.SaveAll)]]
SOURCES["ServerStorage/Modules/BotAI.lua"] = [[
-- ServerStorage/Modules/BotAI (ModuleScript)
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared.Config)
local Rules = require(Shared.Rules)

local BotAI = {}
local THINK_TIME = 0.9
local rng = Random.new()

local function stillMyTurn(match, bot, token)
	return not match.ended and match.current == bot and match.turnToken == token
end

local function strongest(field, filter)
	local best
	for _, c in field do
		if (not filter or filter(c)) and (not best or c.ATK > best.ATK) then best = c end
	end
	return best
end

local function chooseBoard(me)
	local fieldFree = #me.field < Config.FIELD_SLOTS
	if me.gate == nil and (not fieldFree or rng:NextNumber() < 0.25) then return "Gate", true end
	if fieldFree then return "Field", true end
	return nil, false
end

local function chooseSpell(me, opp, card)
	local tt = Rules.TargetType(card)
	if tt == "None" then
		if card.Effect and card.Effect.Kind == "Bomb" then return nil, #opp.field > #me.field end
		return nil, true
	elseif tt == "EnemyChar" then
		local t = strongest(opp.field)
		return t and t.Uid, t ~= nil
	elseif tt == "AllyChar" then
		local t = strongest(me.field)
		return t and t.Uid, t ~= nil
	elseif tt == "Ally" then
		return "MY_LEADER", me.leaderHP <= Config.LEADER_HP - 4
	elseif tt == "Weapon" then
		local t = strongest(me.field, function(c) return c.CanAttack and not c.WeaponName end)
		if t then return t.Uid, true end
		return "LEADER", true
	end
	return nil, false
end

local function playPhase(match, bot, token)
	for _ = 1, 12 do
		if not stillMyTurn(match, bot, token) then return end
		local me = match.sides[bot]
		local opp = match:OtherSide(me)
		local hand = table.clone(me.hand)
		table.sort(hand, function(a, b) return a.Cost > b.Cost end)
		local played = false
		for _, card in hand do
			if card.Cost <= me.points then
				local target, ok
				if card.Type == "Character" then
					target, ok = chooseBoard(me)
				else
					target, ok = chooseSpell(me, opp, card)
				end
				if ok and match:PlayCard(bot, card.Uid, target) then
					played = true
					break
				end
			end
		end
		if not played then return end
		task.wait(THINK_TIME)
	end
end

local function pickTarget(attacker, opp)
	if Rules.HasTaunt(opp.field) then
		for _, c in opp.field do
			if Rules.HasKeyword(c, "Taunt") then return c.Uid end
		end
	end
	for _, c in opp.field do
		if c.HP <= attacker.ATK and c.ATK < attacker.HP then return c.Uid end
	end
	return "LEADER"
end

local function attackPhase(match, bot, token)
	local tried = {}
	for _ = 1, 12 do
		if not stillMyTurn(match, bot, token) then return end
		local me = match.sides[bot]
		local attacker
		for _, c in me.field do
			if c.CanAttack and c.ATK > 0 and not tried[c.Uid] then attacker = c break end
		end
		if not attacker then return end
		tried[attacker.Uid] = true
		match:Attack(bot, attacker.Uid, pickTarget(attacker, match:OtherSide(me)))
		task.wait(THINK_TIME)
	end
end

function BotAI.TakeTurn(match, bot, token)
	task.wait(1.5)
	local ok, err = pcall(function()
		playPhase(match, bot, token)
		attackPhase(match, bot, token)
	end)
	if not ok then warn("[BotAI] " .. tostring(err)) end
	if stillMyTurn(match, bot, token) then match:EndTurn(bot, false) end
end

return BotAI]]
SOURCES["ServerStorage/Modules/CardEffects.lua"] = [[
-- ServerStorage/Modules/CardEffects (ModuleScript)
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared.Config)
local Rules = require(Shared.Rules)

local CardEffects = {}
local rng = Random.new()

local function find(list, uid)
	for i, c in list do
		if c.Uid == uid then return c, i end
	end
	return nil
end

-- สุ่มโดนศัตรู (ตัวละครที่ยังไม่ตาย + ผู้นำ)
local function hitRandomEnemy(match, opp, damage)
	local pool = { "LEADER" }
	for _, c in opp.field do
		if c.HP > 0 then table.insert(pool, c) end
	end
	local t = pool[rng:NextInteger(1, #pool)]
	if t == "LEADER" then
		match:DamageLeader(opp, damage)
		return "ผู้นำของ " .. opp.name
	end
	t.HP -= damage
	return t.Name
end

local Spells = {}

function Spells.Shield(match, me, _, card)
	me.shield += card.Effect.Value
	match:Track(me.player, function(d, S) S.Add(d, "ShieldGained", card.Effect.Value) end)
	match:Notify(("🛡️ %s ตั้งโล่ฝาหม้อ (กันได้ %d)"):format(me.name, me.shield), "Blue")
end

function Spells.Slime(match, _, _, _, t)
	t.Slime = true
	match:Notify(("🟢 %s เหยียบสไลม์! ตีครั้งหน้าพลาดได้ 50%%"):format(t.Name), "Green")
end

function Spells.Damage(match, me, _, card, t)
	local dealt = math.max(0, math.min(t.HP, card.Effect.Value))
	t.HP -= card.Effect.Value
	match.lastHit[t.Uid] = { by = me.player, card = card.Id }
	match:Track(me.player, function(d, S) S.Add(d, "DamageToCards", dealt) end)
	match:Notify(("👋 %s โดน %s %d!"):format(t.Name, card.Name, card.Effect.Value), "Red")
end

function Spells.Heal(match, me, _, card, t)
	local v = card.Effect.Value
	if t == "LEADER" then
		local gained = math.min(v, Config.LEADER_HP - me.leaderHP)
		match:Track(me.player, function(d, S) S.Add(d, "HealDone", math.max(0, gained)) end)
		me.leaderHP = math.min(me.leaderHP + v, Config.LEADER_HP)
		match:Notify(("💚 %s ฮีลผู้นำ +%d"):format(me.name, v), "Green")
	else
		local gained = math.min(v, (t.MaxHP or (t.HP + v)) - t.HP)
		match:Track(me.player, function(d, S) S.Add(d, "HealDone", math.max(0, gained)) end)
		t.HP = math.min(t.HP + v, t.MaxHP or (t.HP + v))
		match:Notify(("💚 %s ฮีล +%d"):format(t.Name, v), "Green")
	end
end

function Spells.Buff(match, _, _, card, t)
	local v = card.Effect.Value
	t.MaxHP = (t.MaxHP or t.HP) + v
	t.HP += v
	t.ATK += v
	match:Notify(("📣 %s ตื่นเต็มตา! ATK +%d HP +%d"):format(t.Name, v, v), "Yellow")
end

function Spells.Mystery(match, me, opp, card)
	local roll = rng:NextInteger(1, 3)
	if roll == 1 then
		local name = hitRandomEnemy(match, opp, card.Effect.Value)
		match:Notify(("🎁 กล่องระเบิดใส่ %s %d!"):format(name, card.Effect.Value), "Red")
	elseif roll == 2 then
		match:Draw(me, 2)
		match:Notify(("🎁 %s ได้จั่วการ์ด 2 ใบ"):format(me.name), "Blue")
	else
		match:Notify("🎁 ว่างเปล่า... มีแต่เสียงหัวเราะ 🤣", "Yellow")
	end
end

function Spells.Bomb(match, me, _, card)
	local delay = card.Effect.Delay or 2
	table.insert(match.bombs, { turns = delay, damage = card.Effect.Value })
	match:Notify(("💣 %s ตั้งหม้อหุงข้าว! อีก %d เทิร์นระเบิดทั้งสนาม"):format(me.name, delay), "Red")
end

function CardEffects.Equip(match, ally, weapon)
	if ally.WeaponName then
		ally.ATK = math.max(0, ally.ATK - (ally.WeaponBonus or 0))
	end
	ally.ATK += weapon.Bonus
	ally.WeaponName = weapon.Name
	ally.WeaponBonus = weapon.Bonus
	ally.WeaponDur = weapon.Durability or 2
	ally.WeaponFreeze = weapon.Freeze == true
	match:Notify(("🗡️ %s สวม %s (ATK +%d)"):format(ally.Name, weapon.Name, weapon.Bonus), "Yellow")
end

-- ตรวจเป้าหมายก่อน ถ้าผ่านจะคืนฟังก์ชันสำหรับทำผล ถ้าไม่ผ่านจะคืน nil, รหัส error
function CardEffects.Prepare(match, me, card, target)
	local opp = match:OtherSide(me)

	if card.Type == "Weapon" then
		if typeof(target) ~= "string" then return nil, "NEED_TARGET" end
		local ally = find(me.field, target)
		if ally then
			return function()
				match:Track(me.player, function(d, S) S.Add(d, "WeaponsEquipped") end)
				CardEffects.Equip(match, ally, card)
			end
		end
		if target == "LEADER" then
			return function()
				match:DamageLeader(opp, card.Bonus, me.player)
				match:Track(me.player, function(d, S) S.Add(d, "WeaponsThrown") end)
				match:Notify(("🗡️ ปา%sใส่ผู้นำของ %s %d!"):format(card.Name, opp.name, card.Bonus), "Red")
			end
		end
		local enemy = find(opp.field, target)
		if enemy then
			return function()
				local dealt = math.max(0, math.min(enemy.HP, card.Bonus))
				enemy.HP -= card.Bonus
				match.lastHit[enemy.Uid] = { by = me.player, card = card.Id }
				match:Track(me.player, function(d, S)
					S.Add(d, "WeaponsThrown")
					S.Add(d, "DamageToCards", dealt)
				end)
				if card.Freeze and enemy.HP > 0 then enemy.Frozen = true end
				match:Notify(("🗡️ ปา%sใส่ %s %d!%s"):format(card.Name, enemy.Name, card.Bonus,
					card.Freeze and " ❄️แช่แข็ง" or ""), "Red")
			end
		end
		return nil, "INVALID_TARGET"
	end

	if card.Type ~= "Spell" or typeof(card.Effect) ~= "table" then return nil, "INVALID_CARD" end
	local handler = Spells[card.Effect.Kind]
	if not handler then return nil, "INVALID_CARD" end

	local ttype = Rules.TargetType(card)
	local t = nil
	if ttype ~= "None" then
		if typeof(target) ~= "string" then return nil, "NEED_TARGET" end
		if ttype == "EnemyChar" then
			t = find(opp.field, target)
		elseif ttype == "AllyChar" then
			t = find(me.field, target)
		elseif ttype == "Ally" then
			t = (target == "MY_LEADER") and "LEADER" or find(me.field, target)
		end
		if not t then return nil, "INVALID_TARGET" end
	end
	return function() handler(match, me, opp, card, t) end
end

-- ตอนลงสนาม: ขุดศพ / ขโมย
function CardEffects.OnEnter(match, side, card)
	if Rules.HasKeyword(card, "Necro") then
		local pool = {}
		for i, c in side.graveyard do
			if c.Type == "Character" then table.insert(pool, i) end
		end
		if #pool > 0 and #side.hand < Config.MAX_HAND then
			local dead = table.remove(side.graveyard, pool[rng:NextInteger(1, #pool)])
			table.insert(side.hand, match.MakeCard(dead.Id))
			match:Notify(("⚰️ %s ขุด %s กลับขึ้นมือ!"):format(card.Name, dead.Name), "Pink")
		else
			match:Notify(("⚰️ %s ขุดแล้วไม่เจออะไร"):format(card.Name))
		end
	end

	if Rules.HasKeyword(card, "Steal") then
		local opp = match:OtherSide(side)
		local amount = opp.banking and math.min(2, opp.points) or 0
		if amount > 0 then
			opp.points -= amount
			side.points = math.min(side.points + amount, Config.MAX_BANKED_POINTS)
			match:Notify(("🦹 %s ขโมยพอยต์ที่ดองไว้ %d!"):format(card.Name, amount), "Pink")
		else
			match:Notify(("🦹 %s หาพอยต์ขโมยไม่เจอ"):format(card.Name))
		end
	end
end

-- ตอนตาย: ดวงซวย
function CardEffects.OnDeath(match, side, card)
	if Rules.HasKeyword(card, "Unlucky") then
		if rng:NextInteger(0, 1) == 1 then
			local name = hitRandomEnemy(match, match:OtherSide(side), 3)
			match:Notify(("🪙 ดวงซวยออกหัว! %s โดน 3"):format(name), "Yellow")
		else
			match:DamageLeader(side, 3)
			match:Notify(("🪙 ดวงซวยออกก้อย! ผู้นำของ %s โดนเอง 3 🤦"):format(side.name), "Red")
		end
	end
end

return CardEffects]]
SOURCES["ServerStorage/Modules/DataService.lua"] = [[
local DataStoreService = game:GetService("DataStoreService")
local RunService = game:GetService("RunService")
local ServerStorage = game:GetService("ServerStorage")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local StatsService = require(ServerStorage:WaitForChild("Modules"):WaitForChild("StatsService"))
local Shared = ReplicatedStorage:WaitForChild("Shared")
local Decks = require(Shared:WaitForChild("Decks"))
local DeckRules = require(Shared:WaitForChild("DeckRules"))

local DEFAULT = {
	Gems = 100, Wins = 0, Losses = 0, Streak = 0, BestStreak = 0,
	Collection = {}, Deck = {}, Pity = { Epic = 0, Legend = 0 },
	Quests = { Day = 0, List = {} }, Farms = {},
}
local AUTOSAVE_INTERVAL = 120

local store
pcall(function() store = DataStoreService:GetDataStore("GawaPlayer_v1") end)

local DataService = {}
DataService.OnChanged = nil -- GameServer ตั้งให้ (ส่งโปรไฟล์ใหม่ไปไคลเอนต์)
local profiles = {}

local function key(player) return "u_" .. player.UserId end

local function deepCopy(v)
	if typeof(v) ~= "table" then return v end
	local t = {}
	for k, x in v do t[k] = deepCopy(x) end
	return t
end

local function reconcile(data)
	for k, v in DEFAULT do
		if data[k] == nil then data[k] = deepCopy(v) end -- ก๊อปใหม่ทุกครั้ง ไม่ใช้ตารางร่วมกัน
	end
	if typeof(data.Collection) ~= "table" then data.Collection = {} end
	if typeof(data.Deck) ~= "table" then data.Deck = {} end
	if typeof(data.Pity) ~= "table" then data.Pity = {} end
	data.Pity.Epic = tonumber(data.Pity.Epic) or 0
	data.Pity.Legend = tonumber(data.Pity.Legend) or 0
	if typeof(data.Quests) ~= "table" then data.Quests = { Day = 0, List = {} } end
	if typeof(data.Farms) ~= "table" then data.Farms = {} end
	if next(data.Collection) == nil then
		for _, id in Decks.Starter do data.Collection[id] = (data.Collection[id] or 0) + 1 end
	end
	if not DeckRules.Validate(data.Deck, data.Collection) then
		data.Deck = table.clone(Decks.Starter)
	end
	StatsService.Reconcile(data)
	return data
end

local function publish(player, data)
	player:SetAttribute("Gems", data.Gems)
	player:SetAttribute("Streak", data.Streak)
end

local function changed(player)
	local profile = profiles[player]
	if not profile then return end
	publish(player, profile.Data)
	if DataService.OnChanged then task.spawn(DataService.OnChanged, player) end
end

function DataService.Load(player)
	if profiles[player] then return end
	local data, success = nil, false
	if store then
		local tries = RunService:IsStudio() and 1 or 3
		for attempt = 1, tries do
			success = pcall(function() data = store:GetAsync(key(player)) end)
			if success then break end
			task.wait(attempt)
		end
	end
	if not player.Parent then return end
	if not success then
		if RunService:IsStudio() then
			warn("[DataService] ใช้ DataStore ไม่ได้ ใช้ข้อมูลชั่วคราว (ไม่เซฟ) | เปิด Game Settings > Security > Enable Studio Access to API Services")
		else
			player:Kick("โหลดข้อมูลไม่สำเร็จ กรุณาเข้าเกมใหม่อีกครั้ง")
			return
		end
	end
	local profile = { Data = reconcile(typeof(data) == "table" and data or {}), CanSave = success }
	profiles[player] = profile
	changed(player)
end

local function save(player, profile)
	if not profile.CanSave or not store then return end
	local ok, err = pcall(function()
		store:UpdateAsync(key(player), function() return profile.Data end)
	end)
	if not ok then warn("[DataService] เซฟไม่สำเร็จ " .. player.Name .. ": " .. tostring(err)) end
end

function DataService.IsLoaded(player) return profiles[player] ~= nil end
function DataService.Touch(player) changed(player) end

function DataService.AddGems(player, amount)
	local profile = profiles[player]
	if not profile then return 0 end
	profile.Data.Gems += amount
	changed(player)
	return amount
end

function DataService.GetData(player)
	local profile = profiles[player]
	return profile and profile.Data or nil
end

function DataService.GetStats(player)
	local profile = profiles[player]
	return profile and StatsService.Snapshot(profile.Data) or nil
end

function DataService.GetStreak(player)
	local profile = profiles[player]
	return profile and profile.Data.Streak or 0
end

function DataService.RecordResult(player, won)
	local profile = profiles[player]
	if not profile then return end
	local d = profile.Data
	if won then
		d.Wins += 1
		d.Streak += 1
		d.BestStreak = math.max(d.BestStreak, d.Streak)
	else
		d.Losses += 1
		d.Streak = 0
	end
	publish(player, d)
end

function DataService.Release(player)
	local profile = profiles[player]
	profiles[player] = nil
	if profile then save(player, profile) end
end

function DataService.SaveAll()
	local pending = 0
	for player, profile in profiles do
		pending += 1
		task.spawn(function()
			save(player, profile)
			pending -= 1
		end)
	end
	local start = os.clock()
	while pending > 0 and os.clock() - start < 25 do task.wait(0.1) end
end

task.spawn(function()
	while true do
		task.wait(AUTOSAVE_INTERVAL)
		for player, profile in profiles do task.spawn(save, player, profile) end
	end
end)

return DataService]]
SOURCES["ServerStorage/Modules/FarmService.lua"] = [[
-- ฟาร์ม: เซิร์ฟเวอร์เป็นคนคำนวณทุกอย่างจากเวลาเซิร์ฟเวอร์ ไคลเอนต์ส่งมาแค่ id ของฟาร์ม
-- data.Farms[id] = { Level = n, LastClaim = unix วินาที }
local FarmService = {}

local MAX_LEVEL = 10

-- ผลิตเป็นเพชรทั้งหมด (สกุลเงินเดียวที่เกมมี) ค่าต่ำมากเพื่อไม่ให้ทำลายสมดุลกาชา
FarmService.Defs = {
	GlueGarden = { Name = "สวนกาว", Emoji = "🌻", Rate = 1, Cap = 20, UpgradeBase = 40 },
	GemMine = { Name = "เหมืองเจม", Emoji = "💎", Rate = 2, Cap = 30, UpgradeBase = 80 },
	MemePond = { Name = "บ่อเลี้ยงมีม", Emoji = "🐸", Rate = 1, Cap = 40, UpgradeBase = 60 },
}
FarmService.Order = { "GlueGarden", "GemMine", "MemePond" }

FarmService.Clock = os.time -- ทดสอบแทนที่ได้
local function now() return FarmService.Clock() end

local function stateOf(data, id)
	if typeof(data.Farms) ~= "table" then data.Farms = {} end
	local f = data.Farms[id]
	if typeof(f) ~= "table" then
		f = { Level = 1, LastClaim = now() }
		data.Farms[id] = f
	end
	f.Level = math.clamp(math.floor(tonumber(f.Level) or 1), 1, MAX_LEVEL)
	f.LastClaim = math.min(tonumber(f.LastClaim) or now(), now()) -- เวลาในอนาคต (ข้อมูลเสีย) ไม่ให้นับ
	return f
end

local function rateOf(def, level) return def.Rate * level end           -- ต่อนาที
local function capOf(def, level) return def.Cap * level end
local function upgradeCost(def, level) return def.UpgradeBase * level end

local function stored(def, f)
	local minutes = math.max(0, now() - f.LastClaim) / 60
	return math.min(capOf(def, f.Level), math.floor(minutes * rateOf(def, f.Level)))
end

local function view(id, def, f)
	return {
		Id = id, Name = def.Name, Emoji = def.Emoji, Level = f.Level,
		Rate = rateOf(def, f.Level), Cap = capOf(def, f.Level), LastClaim = f.LastClaim,
		UpgradeCost = f.Level < MAX_LEVEL and upgradeCost(def, f.Level) or nil,
	}
end

-- เวลาเป็น unix วินาที (ไคลเอนต์ใช้ serverNow เทียบ)
function FarmService.List(data)
	local out = {}
	for _, id in FarmService.Order do
		table.insert(out, view(id, FarmService.Defs[id], stateOf(data, id)))
	end
	return out, now()
end

-- คืน ok, จำนวนเพชรที่ได้ | ok=false, รหัสข้อผิดพลาด
function FarmService.Claim(data, id)
	local def = typeof(id) == "string" and FarmService.Defs[id]
	if not def then return false, "BAD_FARM" end
	local f = stateOf(data, id)
	local amount = stored(def, f)
	if amount < 1 then return false, "NOTHING_TO_CLAIM" end
	-- เก็บเฉพาะส่วนที่จ่ายจริง เศษนาทีที่เหลือไม่หาย
	local paidMinutes = amount / rateOf(def, f.Level)
	f.LastClaim = math.min(now(), f.LastClaim + math.ceil(paidMinutes * 60))
	if amount >= capOf(def, f.Level) then f.LastClaim = now() end -- เต็มแล้ว ส่วนเกินทิ้ง
	data.Gems += amount
	return true, amount
end

-- คืน ok, ข้อมูลฟาร์มใหม่ | ok=false, รหัสข้อผิดพลาด
function FarmService.Upgrade(data, id)
	local def = typeof(id) == "string" and FarmService.Defs[id]
	if not def then return false, "BAD_FARM" end
	local f = stateOf(data, id)
	if f.Level >= MAX_LEVEL then return false, "MAX_LEVEL" end
	local cost = upgradeCost(def, f.Level)
	if (data.Gems or 0) < cost then return false, "NOT_ENOUGH_GEMS" end
	-- จ่ายของที่สะสมไว้ก่อนอัปเกรด ไม่งั้นอัตราใหม่จะคิดย้อนหลังให้เวลาเดิม
	local pending = stored(def, f)
	data.Gems -= cost
	if pending > 0 then data.Gems += pending end
	f.Level += 1
	f.LastClaim = now()
	return true, view(id, def, f)
end

return FarmService
]]
SOURCES["ServerStorage/Modules/GachaService.lua"] = [=[
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared.Config)
local CardData = require(Shared.CardData)
local DeckRules = require(Shared.DeckRules)

local GachaService = {}
local rng = Random.new()
local ORDER = { "Legend", "Epic", "Rare", "Common" }
local TIER = { Common = 1, Rare = 2, Epic = 3, Legend = 4 }

local pool = { Common = {}, Rare = {}, Epic = {}, Legend = {} }
for id, c in CardData do
	if typeof(c) == "table" and c.Type and c.Type ~= "Leader" then
		local r = c.Rarity == "Mystic" and "Legend" or c.Rarity
		if pool[r] then table.insert(pool[r], id) end
	end
end
for _, list in pool do table.sort(list) end

local function rollRarity(pity)
	local rates = Config.GACHA_RATES
	if pity.Legend >= Config.GACHA_LEGEND_PITY then return "Legend" end
	if pity.Epic >= Config.GACHA_EPIC_PITY then
		local total = rates.Epic + rates.Legend
		return (rng:NextNumber() * total < rates.Legend) and "Legend" or "Epic"
	end
	local total = 0
	for _, r in ORDER do total += rates[r] or 0 end
	local x = rng:NextNumber() * total
	for _, r in ORDER do
		x -= rates[r] or 0
		if x < 0 then return r end
	end
	return "Common"
end

-- ถ้าระดับนั้นไม่มีการ์ด ให้ลดระดับลง (ถ้าไม่มีเลยค่อยขยับขึ้น)
local function pick(rarity)
	local start = table.find(ORDER, rarity) or #ORDER
	for i = start, #ORDER do
		local list = pool[ORDER[i]]
		if #list > 0 then return list[rng:NextInteger(1, #list)], ORDER[i] end
	end
	for i = start - 1, 1, -1 do
		local list = pool[ORDER[i]]
		if #list > 0 then return list[rng:NextInteger(1, #list)], ORDER[i] end
	end
	return nil
end

-- ทั้งหมดทำงานแบบไม่ yield จึงหักเพชรซ้ำซ้อนไม่ได้
function GachaService.Pull(data, count)
	if count ~= 1 and count ~= 10 then return false, "BAD_COUNT" end
	local cost = count == 10 and Config.GACHA_COST_10 or Config.GACHA_COST_1
	if (data.Gems or 0) < cost then return false, "NOT_ENOUGH_GEMS" end
	data.Gems -= cost

	local results, refund = {}, 0
	for _ = 1, count do
		data.Pity.Epic += 1
		data.Pity.Legend += 1
		local id, rarity = pick(rollRarity(data.Pity))
		if not id then break end
		if TIER[rarity] >= 3 then data.Pity.Epic = 0 end
		if rarity == "Legend" then data.Pity.Legend = 0 end

		local owned = data.Collection[id] or 0
		if owned >= DeckRules.MaxCopies(CardData[id]) then
			local back = Config.GACHA_DUPE_REFUND[rarity] or 0
			refund += back
			table.insert(results, { Id = id, Rarity = rarity, Refund = back })
		else
			data.Collection[id] = owned + 1
			table.insert(results, { Id = id, Rarity = rarity, New = owned == 0 })
		end
	end
	if #results == 0 then
		data.Gems += cost
		return false, "EMPTY_POOL"
	end
	data.Gems += refund
	return true, results
end

return GachaService]=]
SOURCES["ServerStorage/Modules/GateRNG.lua"] = [[
-- ServerStorage/Modules/GateRNG (ModuleScript)
local GateRNG = {}

GateRNG.Outcomes = {
	{ id = "Golden", weight = 5,  mult = 3   },
	{ id = "Pumped", weight = 20, mult = 1.5 },
	{ id = "Normal", weight = 45, mult = 1   },
	{ id = "Droopy", weight = 20, mult = 0.5 },
	{ id = "Poop",   weight = 10, mult = 0   },
}
local byId = {}
for _, o in GateRNG.Outcomes do byId[o.id] = o end
local rng = Random.new()

function GateRNG.Roll()
	local total = 0
	for _, o in GateRNG.Outcomes do total += o.weight end
	local r = rng:NextNumber(0, total)
	for _, o in GateRNG.Outcomes do
		r -= o.weight
		if r <= 0 then return o end
	end
	return GateRNG.Outcomes[#GateRNG.Outcomes]
end

function GateRNG.Get(id)
	return byId[id]
end

function GateRNG.Apply(card, outcome)
	if outcome.id == "Poop" then
		card.HP, card.ATK, card.Form = 1, 0, "Poop"
	else
		card.HP = math.max(1, math.floor(card.HP * outcome.mult))
		card.ATK = math.floor(card.ATK * outcome.mult)
	end
	card.MaxHP = card.HP
	card.GateResult = outcome.id
end

return GateRNG]]
SOURCES["ServerStorage/Modules/Guard.lua"] = [[
-- จำกัดความถี่ + กันคำสั่งซ้อน + เตะคนที่สแปม
local Players = game:GetService("Players")

local Guard = {}
local CAPACITY = 10      -- ส่งติดกันได้สูงสุด
local REFILL = 5         -- เติมโควตาต่อวินาที
local STRIKE_WINDOW = 10
local STRIKE_KICK = 120  -- ถูกปฏิเสธเกินนี้ภายใน 10 วิ = สแปม

local state = {}

local function get(player)
	local s = state[player]
	if not s then
		local now = os.clock()
		s = { tokens = CAPACITY, last = now, gaps = {}, busy = {}, strikes = 0, windowStart = now }
		state[player] = s
	end
	return s
end

local function strike(player, s, now)
	if now - s.windowStart > STRIKE_WINDOW then
		s.windowStart, s.strikes = now, 0
	end
	s.strikes += 1
	if s.strikes == STRIKE_KICK then
		warn(("[Guard] %s ส่งคำสั่งถี่ผิดปกติ ถูกเตะออก"):format(player.Name))
		player:Kick("ส่งคำสั่งถี่เกินไป กรุณาเข้าเกมใหม่")
	end
end

function Guard.Allow(player, action, minGap)
	local s = get(player)
	local now = os.clock()
	s.tokens = math.min(CAPACITY, s.tokens + (now - s.last) * REFILL)
	s.last = now
	local prev = s.gaps[action]
	if s.tokens < 1 or (prev and now - prev < (minGap or 0)) then
		strike(player, s, now)
		return false
	end
	s.tokens -= 1
	s.gaps[action] = now
	return true
end

-- คำสั่งกลุ่มเดียวกันที่ยังไม่เสร็จ จะถูกปฏิเสธทันที
function Guard.Run(player, lockKey, fn, ...)
	local s = get(player)
	if s.busy[lockKey] then return false, "BUSY" end
	s.busy[lockKey] = true
	local res = table.pack(pcall(fn, ...))
	s.busy[lockKey] = nil
	if not res[1] then
		warn(("[Guard] %s error: %s"):format(lockKey, tostring(res[2])))
		return false, "SERVER_ERROR"
	end
	return table.unpack(res, 2, res.n)
end

Players.PlayerRemoving:Connect(function(p) state[p] = nil end)

return Guard]]
SOURCES["ServerStorage/Modules/Match.lua"] = [[
-- ServerStorage/Modules/Match (ModuleScript)
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local HttpService = game:GetService("HttpService")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared.Config)
local Rules = require(Shared.Rules)
local CardData = require(Shared.CardData)
local Modules = ServerStorage:WaitForChild("Modules")
local GateRNG = require(Modules.GateRNG)
local CardEffects = require(Modules.CardEffects)
local BotAI = require(Modules.BotAI)
local Stats = require(Modules.StatsService)
local Remotes = ReplicatedStorage:WaitForChild("Remotes")

local Match = {}
Match.__index = Match
local rng = Random.new()

local function isPlayer(p)
	return typeof(p) == "Instance" and p.Parent ~= nil
end

local function send(remote, p, ...)
	if isPlayer(p) then remote:FireClient(p, ...) end
end

local function findByUid(list, uid)
	for i, c in list do
		if c.Uid == uid then return c, i end
	end
	return nil
end

local function shuffle(t)
	for i = #t, 2, -1 do
		local j = rng:NextInteger(1, i)
		t[i], t[j] = t[j], t[i]
	end
	return t
end

function Match.MakeCard(id)
	local data = CardData[id]
	assert(data, "ไม่พบการ์ด " .. tostring(id))
	local card = table.clone(data)
	if data.Keywords then card.Keywords = table.clone(data.Keywords) end
	if data.Effect then card.Effect = table.clone(data.Effect) end
	card.Id = id
	card.Uid = HttpService:GenerateGUID(false)
	card.MaxHP = card.HP
	return card
end

local function newSide(player, deckIds, leaderId)
	local leader = CardData[leaderId]
	assert(leader and leader.Type == "Leader", "ผู้นำไม่ถูกต้อง: " .. tostring(leaderId))
	local deck = {}
	for _, id in deckIds do table.insert(deck, Match.MakeCard(id)) end
	return {
		player = player,
		name = typeof(player) == "Instance" and player.DisplayName or player.Name,
		deck = shuffle(deck), hand = {}, field = {}, graveyard = {}, gate = nil,
		leader = { Id = leaderId, Name = leader.Name, Ability = leader.Ability },
		leaderHP = Config.LEADER_HP, shield = 0,
		points = 0, bonusPoints = leader.Ability == "ExtraPoints" and 2 or 0,
		banking = false, spentThisTurn = false, abilityUsed = false,
		afk = 0, fatigue = 0,
	}
end

function Match.new(p1, p2, deck1, deck2, leader1, leader2)
	local self = setmetatable({}, Match)
	self.id = HttpService:GenerateGUID(false)
	self.startedAt = os.clock()
	self.lastHit = {} -- [cardUid] = { by = player, card = cardId } ใช้ให้เครดิตการสังหาร (ไม่ส่งให้ client)
	self.players = { p1, p2 }
	self.sides = { [p1] = newSide(p1, deck1, leader1), [p2] = newSide(p2, deck2, leader2) }
	self.bombs = {}
	self.turnToken = 0
	self.ended = false
	return self
end

-- ───── ตัวช่วย ─────
function Match:Opponent(player)
	return self.players[1] == player and self.players[2] or self.players[1]
end

function Match:OtherSide(side)
	return self.sides[self:Opponent(side.player)]
end

-- บันทึกสถิติให้ผู้เล่น (บอท/คนที่ยังโหลดข้อมูลไม่เสร็จจะถูกข้ามเงียบ ๆ)
-- fn(data, Stats) | self.GetData ถูกใส่โดย GameServer
function Match:Track(player, fn)
	if typeof(player) ~= "Instance" or not self.GetData then return end
	local data = self.GetData(player)
	if not data then return end
	local ok, err = pcall(fn, data, Stats)
	if not ok then warn("[Match] Track error: " .. tostring(err)) end
end

function Match:Notify(text, color)
	for _, p in self.players do send(Remotes.Notify, p, text, color) end
end

function Match:Spend(side, cost)
	side.points -= cost
	if cost > 0 then side.spentThisTurn = true end
end

function Match:Draw(side, count)
	local fatigued = false
	local wanted = math.min(count, Config.MAX_HAND - #side.hand)
	for _ = 1, wanted do
		local card = table.remove(side.deck)
		if card then
			table.insert(side.hand, card)
			self:Track(side.player, function(d, S) S.Add(d, "CardsDrawn") end)
		else
			side.fatigue += 1
			side.leaderHP -= side.fatigue
			fatigued = true
			local dmg = side.fatigue
			self:Track(side.player, function(d, S)
				S.Add(d, "FatigueTurns")
				S.Add(d, "FatigueDamage", dmg)
				S.Add(d, "DamageTaken", dmg)
			end)
			self:Notify(("😵 %s การ์ดหมดกอง! เสีย HP %d"):format(side.name, side.fatigue), "Red")
		end
	end
	return fatigued
end

function Match:DamageLeader(side, amount, source)
	if amount <= 0 then return end
	local absorbed = math.min(side.shield, amount)
	side.shield -= absorbed
	local real = amount - absorbed
	side.leaderHP -= real
	if real > 0 then
		self:Track(side.player, function(d, S) S.Add(d, "DamageTaken", real) end)
		if source then
			self:Track(source, function(d, S) S.Add(d, "DamageToLeader", real) end)
		end
	end
	if absorbed > 0 then self:Notify(("🛡️ โล่ฝาหม้อกันไว้ %d"):format(absorbed), "Blue") end
end

function Match:EnterField(side, card, canAttack)
	card.CanAttack = canAttack
	table.insert(side.field, card)
	CardEffects.OnEnter(self, side, card)
end

function Match:RollGate(side)
	local outcome = GateRNG.Roll()
	local ability = side.leader.Ability
	if not side.abilityUsed then
		if ability == "Reroll" and (outcome.id == "Poop" or outcome.id == "Droopy") then
			side.abilityUsed = true
			self:Notify("🔄 ลุงกาวไม่ยอมรับผล! สุ่มใหม่!", "Yellow")
			outcome = GateRNG.Roll()
		elseif ability == "LuckyPoop" and outcome.id == "Poop" then
			side.abilityUsed = true
			self:Notify("🍀 ป้าดวงเฮงปัดอึทิ้ง! กลายเป็นธรรมดา", "Green")
			outcome = GateRNG.Get("Normal")
		end
	end
	return outcome
end

function Match:TickBombs()
	for i = #self.bombs, 1, -1 do
		local b = self.bombs[i]
		b.turns -= 1
		if b.turns <= 0 then
			table.remove(self.bombs, i)
			self:Notify(("💣💥 หม้อหุงข้าวระเบิด! ทุกตัวในสนามโดน %d"):format(b.damage), "Red")
			for _, p in self.players do
				for _, c in self.sides[p].field do c.HP -= b.damage end
			end
		end
	end
end

function Match:ElementBonus(attacker, target, player)
	if attacker.Element == "Gawa" then
		if rng:NextInteger(0, 1) == 1 then
			self:Notify("🪙 ธาตุกาวออกหัว! ATK +2", "Yellow")
			self:Track(player, function(d, S) S.Add(d, "ElementBonus") end)
			return 2
		end
		self:Notify("🪙 ธาตุกาวออกก้อย... ATK -2")
		self:Track(player, function(d, S) S.Add(d, "ElementPenalty") end)
		return -2
	end
	if Rules.Beats[attacker.Element] and Rules.Beats[attacker.Element] == target.Element then
		self:Notify("⚡ ธาตุชนะทาง! ATK +2", "Yellow")
		self:Track(player, function(d, S) S.Add(d, "ElementBonus") end)
		return 2
	end
	return 0
end

function Match:WearWeapon(card)
	if not card.WeaponName then return end
	card.WeaponDur -= 1
	if card.WeaponDur <= 0 then
		card.ATK = math.max(0, card.ATK - (card.WeaponBonus or 0))
		self:Notify(("💔 %s ของ %s พังแล้ว"):format(card.WeaponName, card.Name))
		card.WeaponName, card.WeaponBonus, card.WeaponDur, card.WeaponFreeze = nil, nil, nil, nil
	end
end

-- ย้ายการ์ดที่ตายลงช่องตาย (วนซ้ำเผื่อดวงซวยทำให้มีตัวตายต่อ)
function Match:Settle()
	for _ = 1, 20 do
		local died = false
		for _, p in self.players do
			local side = self.sides[p]
			for i = #side.field, 1, -1 do
				local c = side.field[i]
				if c.HP <= 0 then
					died = true
					table.remove(side.field, i)
					table.insert(side.graveyard, c)
					local hit = self.lastHit[c.Uid]
					local killer = hit and hit.by
					self:Track(side.player, function(d, S)
						S.Add(d, "CardsLost")
						S.Card(d, c.Id, "Deaths")
					end)
					if killer then
						self:Track(killer, function(d, S)
							S.Add(d, "KillsMade")
							S.Card(d, hit.card, "Kills")
						end)
					end
					CardEffects.OnDeath(self, side, c)
				end
			end
		end
		if not died then return end
	end
end

function Match:CheckWinner()
	local a, b = self.players[1], self.players[2]
	local aDead, bDead = self.sides[a].leaderHP <= 0, self.sides[b].leaderHP <= 0
	if aDead and bDead then return self.current end
	if aDead then return b end
	if bDead then return a end
	return nil
end

-- ปิดท้ายทุกการกระทำ: เก็บศพ → ส่งข้อมูล → ตัดสินผล
function Match:Commit(reason)
	if self.ended then return end
	self:Settle()
	self:Broadcast()
	local winner = self:CheckWinner()
	if winner then self:EndMatch(winner, reason or "LEADER_DOWN") end
end

-- ───── ลำดับเทิร์น ─────
function Match:Start()
	for _, p in self.players do
		self:Draw(self.sides[p], Config.STARTING_HAND)
	end
	self:StartTurn(self.players[rng:NextInteger(1, 2)])
end

function Match:StartTurn(player)
	if self.ended then return end
	if not self.firstPlayer then self.firstPlayer = player end
	self.current = player
	self.turnToken += 1
	local token = self.turnToken
	self.turnEndsAt = workspace:GetServerTimeNow() + Config.TURN_TIME
	local side = self.sides[player]

	self:Track(player, function(d, S) S.Add(d, "Turns") end)

	-- พอยต์ (ถ้าเทิร์นก่อนไม่ได้ดองไว้ พอยต์ที่เหลือจะหาย)
	if not side.banking then side.points = 0 end
	side.points = math.min(side.points + Config.POINTS_PER_TURN + side.bonusPoints, Config.MAX_BANKED_POINTS)
	side.bonusPoints = 0
	side.banking, side.spentThisTurn = false, false

	self:TickBombs()

	for _, c in side.field do
		c.CanAttack = not c.Frozen
	end

	if side.gate and #side.field < Config.FIELD_SLOTS then
		local card = side.gate
		side.gate = nil
		local outcome = self:RollGate(side)
		GateRNG.Apply(card, outcome)
		self:Track(side.player, function(d, S)
			S.Add(d, "GateRolls")
			S.Add(d, "Gate" .. tostring(outcome.id))
		end)
		for _, p in self.players do
			send(Remotes.GateRolled, p, p == player, card, outcome.id)
		end
		self:EnterField(side, card, true)
	elseif side.gate then
		self:Notify("🎲 สนามเต็ม! การ์ดในช่องเกตต้องรอก่อน")
	end

	local fatigued = self:Draw(side, Config.DRAW_PER_TURN)
	self:Commit(fatigued and "FATIGUE" or nil)
	if self.ended then return end

	task.delay(Config.TURN_TIME, function()
		if self.ended or self.turnToken ~= token then return end
		side.afk += 1
		self:Track(player, function(d, S) S.Add(d, "TurnsTimedOut") end)
		if side.afk > Config.AFK_LIMIT then
			self:Notify(("⚡ ฟ้าผ่า %s เพราะ AFK!"):format(side.name), "Red")
			self:EndMatch(self:Opponent(player), "AFK_LIGHTNING")
		else
			self:EndTurn(player, true)
		end
	end)

	if typeof(player) == "table" and player.IsBot then
		task.defer(BotAI.TakeTurn, self, player, token)
	end
end

function Match:PlayCard(player, uid, target)
	if self.ended then return false, "MATCH_OVER" end
	if self.current ~= player then return false, "NOT_YOUR_TURN" end
	local me = self.sides[player]
	local card, index = findByUid(me.hand, uid)
	if not card then return false, "INVALID_CARD" end

	if card.Type == "Character" then
		if target ~= "Field" and target ~= "Gate" then return false, "INVALID_TARGET" end
		local toGate = target == "Gate"
		local cost = toGate and Rules.GateCost(card) or card.Cost
		if cost > me.points then return false, "NOT_ENOUGH_POINTS" end
		if toGate and me.gate then return false, "GATE_OCCUPIED" end
		if not toGate and #me.field >= Config.FIELD_SLOTS then return false, "FIELD_FULL" end
		table.remove(me.hand, index)
		self:Spend(me, cost)
		self:Track(player, function(d, S)
			S.Add(d, "CardsPlayed")
			S.Add(d, "CharactersPlayed")
			S.Add(d, "PointsSpent", cost)
			S.Add(d, toGate and "PlayedToGate" or "PlayedToField")
			S.Card(d, card.Id, "Played")
			S.Card(d, card.Id, toGate and "Gate" or "Field")
		end)
		if toGate then
			card.CanAttack = false
			me.gate = card
			self:Notify(("🎲 %s ลงการ์ดในช่องเกต! เทิร์นหน้ามาลุ้นกัน"):format(me.name), "Pink")
		else
			self:Notify(("🃏 %s ลง %s"):format(me.name, card.Name))
			self:EnterField(me, card, Rules.HasKeyword(card, "Rush"))
		end
	elseif card.Type == "Spell" or card.Type == "Weapon" then
		if card.Cost > me.points then return false, "NOT_ENOUGH_POINTS" end
		local resolve, err = CardEffects.Prepare(self, me, card, target)
		if not resolve then return false, err end
		table.remove(me.hand, index)
		self:Spend(me, card.Cost)
		table.insert(me.graveyard, card)
		self:Notify(("✨ %s ใช้ %s"):format(me.name, card.Name))
		self:Track(player, function(d, S)
			S.Add(d, "CardsPlayed")
			S.Add(d, card.Type == "Spell" and "SpellsPlayed" or "WeaponsPlayed")
			S.Add(d, "PointsSpent", card.Cost)
			S.Card(d, card.Id, "Played")
		end)
		resolve()
	else
		return false, "INVALID_CARD"
	end

	me.afk = 0
	self:Commit()
	return true
end

function Match:Attack(player, attackerUid, targetUid)
	if self.ended then return false, "MATCH_OVER" end
	if self.current ~= player then return false, "NOT_YOUR_TURN" end
	local me = self.sides[player]
	local opp = self:OtherSide(me)
	local attacker = findByUid(me.field, attackerUid)
	if not attacker or not attacker.CanAttack or attacker.ATK <= 0 then return false, "CANNOT_ATTACK" end

	local tauntUp = Rules.HasTaunt(opp.field)
	local target = nil
	if targetUid == "LEADER" then
		if tauntUp then return false, "TAUNT" end
	else
		target = findByUid(opp.field, targetUid)
		if not target then return false, "INVALID_TARGET" end
		if tauntUp and not Rules.HasKeyword(target, "Taunt") then return false, "TAUNT" end
	end

	attacker.CanAttack = false
	me.afk = 0
	self:Track(player, function(d, S)
		S.Add(d, "Attacks")
		S.Add(d, target and "AttacksAtCard" or "AttacksAtLeader")
	end)

	if attacker.Slime then
		attacker.Slime = nil
		if rng:NextNumber() < 0.5 then
			self:Notify(("🟢 %s ลื่นสไลม์ ตีพลาด!"):format(attacker.Name), "Green")
			self:Track(player, function(d, S) S.Add(d, "AttacksMissed") end)
			self:Commit()
			return true
		end
	end

	if target then
		local dmg = math.max(0, attacker.ATK + self:ElementBonus(attacker, target, player))
		local before = target.HP
		target.HP -= dmg
		-- จำว่าใครตี เพื่อให้ Settle ให้เครดิตการสังหาร (ทั้งฝั่งโจมตีและฝั่งโต้กลับ)
		if dmg > 0 then self.lastHit[target.Uid] = { by = player, card = attacker.Id } end
		local counter = target.ATK
		attacker.HP -= counter
		if counter > 0 then self.lastHit[attacker.Uid] = { by = self:Opponent(player), card = target.Id } end
		local dealt = math.max(0, math.min(before, dmg))
		self:Track(player, function(d, S)
			S.Add(d, "DamageToCards", dealt)
			S.Card(d, attacker.Id, "Damage", dealt)
		end)
		if counter > 0 then
			self:Track(self:Opponent(player), function(d, S)
				S.Add(d, "DamageToCards", counter)
				S.Card(d, target.Id, "Damage", counter)
			end)
		end
		if attacker.WeaponFreeze and target.HP > 0 then
			target.Frozen = true
			self:Notify(("❄️ %s โดนแช่แข็ง!"):format(target.Name), "Blue")
		end
	else
		self:DamageLeader(opp, attacker.ATK, player)
		self:Track(player, function(d, S) S.Card(d, attacker.Id, "Damage", attacker.ATK) end)
	end

	self:WearWeapon(attacker)
	self:Commit()
	return true
end

function Match:EndTurn(player, timedOut)
	if self.ended or self.current ~= player then return false, "NOT_YOUR_TURN" end
	local side = self.sides[player]
	if not timedOut then side.afk = 0 end
	side.banking = not side.spentThisTurn
	if side.banking then
		self:Notify(("💰 %s ดองพอยต์ไว้!"):format(side.name), "Pink")
		local banked = side.points
		self:Track(player, function(d, S)
			S.Add(d, "TurnsSkipped")
			S.Add(d, "PointsBanked", banked)
		end)
	end
	for _, c in side.field do
		c.Slime = nil
		c.Frozen = nil
	end
	self:StartTurn(self:Opponent(player))
	return true
end

function Match:Surrender(player)
	if self.ended then return false end
	self:EndMatch(self:Opponent(player), "SURRENDER")
	return true
end

function Match:EndMatch(winner, reason)
	if self.ended then return end
	self.ended = true
	self.turnToken += 1
	local rewards = {}
	if self.OnEnded then
		local ok, result = pcall(self.OnEnded, self, winner, reason)
		if not ok then
			warn("[Match] OnEnded error: " .. tostring(result))
		elseif typeof(result) == "table" then
			rewards = result
		end
	end
	for _, p in self.players do
		send(Remotes.MatchEnded, p, p == winner, reason, self.id, rewards[p] or 0)
	end
end

-- ส่งข้อมูลแยกให้แต่ละคน (ไม่ส่งไพ่ในมือ, กองการ์ด หรือการ์ดในช่องเกตของอีกฝั่ง)
function Match:Broadcast()
	local bombs = {}
	for _, b in self.bombs do table.insert(bombs, b.turns) end
	for _, p in self.players do
		if isPlayer(p) then
			local me, opp = self.sides[p], self.sides[self:Opponent(p)]
			Remotes.StateUpdate:FireClient(p, {
				matchId = self.id,
				isMyTurn = self.current == p,
				turnEndsAt = self.turnEndsAt,
				bombs = bombs,
				myHand = me.hand, myField = me.field, myGate = me.gate,
				myPoints = me.points, mySpent = me.spentThisTurn,
				myHP = me.leaderHP, myShield = me.shield,
				myLeader = me.name .. " • " .. me.leader.Name, myLeaderId = me.leader.Id,
				myDeck = #me.deck, myGrave = #me.graveyard,
				oppField = opp.field, oppGateFilled = opp.gate ~= nil,
				oppHandCount = #opp.hand, oppHP = opp.leaderHP, oppShield = opp.shield,
				oppLeader = opp.name .. " • " .. opp.leader.Name, oppLeaderId = opp.leader.Id,
				oppDeck = #opp.deck, oppGrave = #opp.graveyard,
				oppBank = opp.banking and opp.points or 0,
			})
		end
	end
end

return Match]]
SOURCES["ServerStorage/Modules/QuestService.lua"] = [[
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local QuestData = require(ReplicatedStorage:WaitForChild("Shared"):WaitForChild("QuestData"))

local QuestService = {}
local byId = {}
for _, q in QuestData.Pool do byId[q.Id] = q end

local function today() return math.floor(os.time() / 86400) end -- รีเซ็ตเที่ยงคืน UTC (07:00 ไทย)

function QuestService.Ensure(data, userId)
	if typeof(data.Quests) ~= "table" then data.Quests = { Day = 0, List = {} } end
	local q, day = data.Quests, today()
	if q.Day == day and typeof(q.List) == "table" and #q.List > 0 then return false end
	local rng = Random.new(day * 7919 + (userId % 100000))
	local ids = {}
	for _, def in QuestData.Pool do table.insert(ids, def.Id) end
	local list = {}
	for i = 1, math.min(QuestData.DAILY_COUNT, #ids) do
		local j = rng:NextInteger(i, #ids)
		ids[i], ids[j] = ids[j], ids[i]
		table.insert(list, { Id = ids[i], Progress = 0, Claimed = false })
	end
	q.Day, q.List = day, list
	return true
end

function QuestService.Track(data, userId, event, amount)
	QuestService.Ensure(data, userId)
	local changed = false
	for _, e in data.Quests.List do
		local def = byId[e.Id]
		if def and def.Event == event and not e.Claimed and (e.Progress or 0) < def.Goal then
			e.Progress = math.min(def.Goal, (e.Progress or 0) + (amount or 1))
			changed = true
		end
	end
	return changed
end

function QuestService.Claim(data, userId, questId)
	QuestService.Ensure(data, userId)
	for _, e in data.Quests.List do
		if e.Id == questId then
			local def = byId[e.Id]
			if not def then return false, "BAD_QUEST" end
			if e.Claimed then return false, "ALREADY_CLAIMED" end
			if (e.Progress or 0) < def.Goal then return false, "NOT_DONE" end
			e.Claimed = true
			data.Gems += def.Reward
			return true, def.Reward
		end
	end
	return false, "BAD_QUEST"
end

function QuestService.View(data)
	local list = {}
	for _, e in data.Quests.List do
		local def = byId[e.Id]
		if def then
			table.insert(list, { Id = e.Id, Text = def.Text, Goal = def.Goal, Reward = def.Reward,
				Progress = e.Progress or 0, Claimed = e.Claimed == true })
		end
	end
	return { List = list, ResetIn = (today() + 1) * 86400 - os.time() }
end

return QuestService]]
SOURCES["ServerStorage/Modules/StatsService.lua"] = [=[
-- ServerStorage/Modules/StatsService (ModuleScript)
-- สถิติผู้เล่น: ตลอดชีพ + รายวัน (เวลาไทย) | เก็บใน DataService profile.Data.Stats / Data.Daily
-- ทุกค่านับที่เซิร์ฟเวอร์เท่านั้น ไม่เชื่อค่าจาก client
local StatsService = {}

local DAY_OFFSET = 7 * 3600 -- "วันนี้" ตามเวลาไทย (UTC+7)
local KEEP_DAYS = 14
local MAX_TOP = 150         -- เพดานชนิดการ์ดต่อ bucket (เกมมี 27 ใบ รองรับขยายถึง 150 ใบ ข้อมูลเต็มสุดราว 20KB ต่อ bucket)

-- ───── โครงสร้างค่าเริ่มต้น (ฟิลด์ใหม่ที่ขาดจะถูกเติมให้อัตโนมัติ) ─────
-- ตัวนับทั้งหมดเป็นจำนวนเต็ม ยกเว้นที่ระบุหน่วยเป็นวินาที
local COUNTERS = {
	-- คิว
	"QueuePvP", "QueueBot", "QueueCancel", "QueueMatched", "QueueWaitSec", "QueueWaitCount",
	-- แมตช์
	"Matches", "MatchesPvP", "MatchesBot",
	"Wins", "Losses", "Draws",
	"WinsPvP", "LossesPvP", "DrawsPvP",
	"WinsBot", "LossesBot", "DrawsBot",
	"WinsGoingFirst", "MatchesGoingFirst",
	"Surrenders", "Disconnects", "AfkLosses", "OpponentLeft",
	-- เวลา (วินาที)
	"PlaySec", "WinSec", "LossSec", "LongestMatchSec", "ShortestWinSec",
	-- เทิร์น
	"Turns", "TurnsSkipped", "TurnsTimedOut", "PointsBanked",
	-- การ์ด
	"CardsPlayed", "CharactersPlayed", "SpellsPlayed", "WeaponsPlayed",
	"PlayedToField", "PlayedToGate", "PointsSpent",
	"CardsDrawn", "FatigueTurns", "FatigueDamage",
	-- ช่องเกต
	"GateRolls", "GateGolden", "GatePumped", "GateNormal", "GateDroopy", "GatePoop",
	-- การต่อสู้
	"Attacks", "AttacksAtLeader", "AttacksAtCard", "AttacksMissed",
	"DamageToLeader", "DamageToCards", "DamageTaken", "HealDone", "ShieldGained",
	"KillsMade", "CardsLost", "WeaponsEquipped", "WeaponsThrown",
	"ElementBonus", "ElementPenalty",
	-- ผลตอบแทน
	"GemsEarned", "BountyEarned", "BestGemsOneMatch",
}

local function newBucket()
	local b = { Cards = {}, Leaders = {} }
	for _, k in ipairs(COUNTERS) do b[k] = 0 end
	return b
end

local function fill(b)
	for _, k in ipairs(COUNTERS) do
		if typeof(b[k]) ~= "number" then b[k] = 0 end
	end
	if typeof(b.Cards) ~= "table" then b.Cards = {} end
	if typeof(b.Leaders) ~= "table" then b.Leaders = {} end
	return b
end

-- ───── วันที่ ─────
function StatsService.DayKey(t)
	return os.date("!%Y-%m-%d", (t or os.time()) + DAY_OFFSET)
end

-- ───── เตรียมข้อมูลในโปรไฟล์ (เรียกจาก DataService.reconcile) ─────
function StatsService.Reconcile(data)
	if typeof(data.Stats) ~= "table" then data.Stats = {} end
	fill(data.Stats)
	if typeof(data.Daily) ~= "table" then data.Daily = {} end
	for _, b in pairs(data.Daily) do fill(b) end

	-- ย้ายค่าเก่า (Wins/Losses/BestStreak ที่นับก่อนมีระบบนี้) เข้าสถิติตลอดชีพครั้งเดียว
	if not data.StatsMigrated then
		data.StatsMigrated = true
		local s = data.Stats
		s.WinsPvP = math.max(s.WinsPvP, data.Wins or 0)
		s.LossesPvP = math.max(s.LossesPvP, data.Losses or 0)
		s.Wins = math.max(s.Wins, data.Wins or 0)
		s.Losses = math.max(s.Losses, data.Losses or 0)
		s.MatchesPvP = math.max(s.MatchesPvP, s.WinsPvP + s.LossesPvP + s.DrawsPvP)
		s.Matches = math.max(s.Matches, s.MatchesPvP)
	end

	-- ตัดวันเก่า เหลือ KEEP_DAYS วันล่าสุด
	local keys = {}
	for k in pairs(data.Daily) do table.insert(keys, k) end
	table.sort(keys, function(a, b) return a > b end)
	for i = KEEP_DAYS + 1, #keys do data.Daily[keys[i]] = nil end
	return data
end

local function today(data)
	local k = StatsService.DayKey()
	local b = data.Daily[k]
	if not b then
		b = newBucket()
		data.Daily[k] = b
	end
	return b, k
end

local function bumpCard(bucket, id, field, n)
	if typeof(id) ~= "string" then return end
	local c = bucket.Cards[id]
	if not c then
		-- กันบวม: ถ้าเต็มแล้วและเป็นการ์ดใหม่ ให้ข้าม
		local count = 0
		for _ in pairs(bucket.Cards) do count = count + 1 end
		if count >= MAX_TOP then return end
		c = { Played = 0, Field = 0, Gate = 0, Kills = 0, Deaths = 0, Damage = 0 }
		bucket.Cards[id] = c
	end
	c[field] = (c[field] or 0) + (n or 1)
end

-- ───── API หลัก ─────
-- ctx: { data = profile.Data } หรือ nil ถ้าโหลดไม่เสร็จ
-- Add(data, "Wins", 1) บวกทั้งตลอดชีพและวันนี้
function StatsService.Add(data, key, n)
	if not data or not data.Stats then return end
	n = n or 1
	data.Stats[key] = (data.Stats[key] or 0) + n
	local d = today(data)
	d[key] = (d[key] or 0) + n
end

-- ตั้งค่าเป็นค่าสูงสุด (เช่น แมตช์ที่ยาวที่สุด)
function StatsService.Max(data, key, value)
	if not data or not data.Stats then return end
	if value > (data.Stats[key] or 0) then data.Stats[key] = value end
	local d = today(data)
	if value > (d[key] or 0) then d[key] = value end
end

-- ตั้งค่าเป็นค่าต่ำสุดที่ > 0 (เช่น ชนะเร็วสุด) 0 = ยังไม่มี
function StatsService.Min(data, key, value)
	if not data or not data.Stats then return end
	local cur = data.Stats[key] or 0
	if cur == 0 or value < cur then data.Stats[key] = value end
	local d = today(data)
	local dc = d[key] or 0
	if dc == 0 or value < dc then d[key] = value end
end

function StatsService.Card(data, id, field, n)
	if not data or not data.Stats then return end
	bumpCard(data.Stats, id, field, n)
	bumpCard((today(data)), id, field, n)
end

function StatsService.Leader(data, leaderId, field)
	if not data or not data.Stats or typeof(leaderId) ~= "string" then return end
	for _, b in ipairs({ data.Stats, (today(data)) }) do
		local l = b.Leaders[leaderId]
		if not l then
			l = { Matches = 0, Wins = 0, Losses = 0, Draws = 0 }
			b.Leaders[leaderId] = l
		end
		l[field] = (l[field] or 0) + 1
	end
end

-- ───── ตัวช่วยสรุปผล ─────
local function topCard(cards, field)
	local bestId, best = nil, 0
	for id, c in pairs(cards) do
		if (c[field] or 0) > best then bestId, best = id, c[field] end
	end
	return bestId, best
end

local function topLeader(leaders)
	local bestId, best = nil, 0
	for id, l in pairs(leaders) do
		if (l.Matches or 0) > best then bestId, best = id, l.Matches end
	end
	return bestId, best
end

local function rate(a, b)
	if b <= 0 then return 0 end
	return math.floor(a / b * 1000 + 0.5) / 10 -- ทศนิยม 1 ตำแหน่ง (เปอร์เซ็นต์)
end

local function derive(b)
	local decided = b.Wins + b.Losses
	local out = {
		WinRate = rate(b.Wins, decided),
		WinRatePvP = rate(b.WinsPvP, b.WinsPvP + b.LossesPvP),
		WinRateBot = rate(b.WinsBot, b.WinsBot + b.LossesBot),
		AvgMatchSec = b.Matches > 0 and math.floor(b.PlaySec / b.Matches) or 0,
		AvgQueueWaitSec = b.QueueWaitCount > 0 and math.floor(b.QueueWaitSec / b.QueueWaitCount) or 0,
		CardsPerMatch = b.Matches > 0 and math.floor(b.CardsPlayed / b.Matches * 10 + 0.5) / 10 or 0,
		GoingFirstWinRate = rate(b.WinsGoingFirst, b.MatchesGoingFirst),
		GoldenRate = rate(b.GateGolden, b.GateRolls),
		PoopRate = rate(b.GatePoop, b.GateRolls),
	}
	out.TopPlayedCard, out.TopPlayedCount = topCard(b.Cards, "Played")
	out.TopKillCard, out.TopKillCount = topCard(b.Cards, "Kills")
	out.TopLeader, out.TopLeaderMatches = topLeader(b.Leaders)
	return out
end

-- สำเนาที่ปลอดภัยส่งให้ client (ตารางล้วน ไม่มี reference กลับ)
local function export(b)
	local copy = { Cards = {}, Leaders = {} }
	for _, k in ipairs(COUNTERS) do copy[k] = b[k] or 0 end
	for id, c in pairs(b.Cards) do copy.Cards[id] = table.clone(c) end
	for id, l in pairs(b.Leaders) do copy.Leaders[id] = table.clone(l) end
	copy.Derived = derive(b)
	return copy
end

-- รวมหลายวันเป็น bucket เดียว (สำหรับ "7 วันล่าสุด")
local function merge(buckets)
	local sum = newBucket()
	for _, b in ipairs(buckets) do
		for _, k in ipairs(COUNTERS) do
			if k == "LongestMatchSec" or k == "BestGemsOneMatch" then
				sum[k] = math.max(sum[k], b[k] or 0)
			elseif k == "ShortestWinSec" then
				local v = b[k] or 0
				if v > 0 and (sum[k] == 0 or v < sum[k]) then sum[k] = v end
			else
				sum[k] = sum[k] + (b[k] or 0)
			end
		end
		for id, c in pairs(b.Cards) do
			local t = sum.Cards[id]
			if not t then
				t = { Played = 0, Field = 0, Gate = 0, Kills = 0, Deaths = 0, Damage = 0 }
				sum.Cards[id] = t
			end
			for f, v in pairs(c) do t[f] = (t[f] or 0) + v end
		end
		for id, l in pairs(b.Leaders) do
			local t = sum.Leaders[id]
			if not t then
				t = { Matches = 0, Wins = 0, Losses = 0, Draws = 0 }
				sum.Leaders[id] = t
			end
			for f, v in pairs(l) do t[f] = (t[f] or 0) + v end
		end
	end
	return sum
end

-- { Today = {...}, Week = {...}, Total = {...}, Days = {...}, DayKey = "..." }
function StatsService.Snapshot(data)
	if not data or not data.Stats then return nil end
	local dayKey = StatsService.DayKey()
	local todayBucket = data.Daily[dayKey] or newBucket()

	local week = {}
	for i = 0, 6 do
		local b = data.Daily[StatsService.DayKey(os.time() - i * 86400)]
		if b then table.insert(week, b) end
	end

	local days = {}
	for i = 6, 0, -1 do
		local k = StatsService.DayKey(os.time() - i * 86400)
		local b = data.Daily[k]
		table.insert(days, {
			Day = k,
			Matches = b and b.Matches or 0,
			Wins = b and b.Wins or 0,
			Losses = b and b.Losses or 0,
			PlaySec = b and b.PlaySec or 0,
		})
	end

	return {
		DayKey = dayKey,
		Today = export(todayBucket),
		Week = export(merge(week)),
		Total = export(data.Stats),
		Days = days,
		Streak = data.Streak or 0,
		BestStreak = data.BestStreak or 0,
	}
end

return StatsService
]=]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/BountyBoard.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/BountyBoard.lua
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local PAPER, WOOD = Color3.fromRGB(244, 226, 178), Color3.fromRGB(150, 96, 52)
local BountyBoard = {}

local function fmt(n)
	local s = tostring(math.floor(n or 0)):reverse():gsub("(%d%d%d)", "%1,"):reverse()
	return (s:gsub("^,", ""))
end

local SAMPLE = {
	{ Name = "เจ้าเป็ดสายฟาด", Emoji = "🦆", Bounty = 1500000, Crime = "ลงโล่ฝาหม้อ 40 เทิร์นติด" },
	{ Name = "ลุงกบเกลือ", Emoji = "🐸", Bounty = 820000, Crime = "เปิดเกตได้อึ 9 รอบรวด" },
	{ Name = "หินโมอายเงียบ", Emoji = "🗿", Bounty = 640000, Crime = "AFK แต่ดันชนะ" },
	{ Name = "ตัวตลกลืมตา", Emoji = "🤡", Bounty = 300000, Crime = "กด SKIP ตอนเหลือ 5 พอยต์" },
	{ Name = "แมวส้มสายปั่น", Emoji = "🐱", Bounty = 125000, Crime = "นอนทับปุ่มยอมแพ้" },
	{ Name = "ไก่ทอดซีอิ๊ว", Emoji = "🍗", Bounty = 50000, Crime = "อร่อยเกินไป" },
}

-- opts = { Entries = {{Name, Emoji, Bounty, Crime, IsMe}}, Me = {Bounty, Rank}, OnHunt = function(entry) end }
function BountyBoard.Open(parent, opts)
	opts = opts or {}
	local list = table.clone(opts.Entries or SAMPLE)
	table.sort(list, function(a, b) return (a.Bounty or 0) > (b.Bounty or 0) end)

	local panel = UIKit.panel(parent, "ประกาศจับ!!", C.Orange)
	panel.BackgroundColor3 = WOOD
	local grid = UIKit.new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, -28, 1, opts.Me and -130 or -76),
		Position = UDim2.new(0, 14, 0, 56), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 10, Parent = panel }, {
		UIKit.new("UIGridLayout", { CellSize = UDim2.fromOffset(196, 268), CellPadding = UDim2.fromOffset(22, 26), SortOrder = Enum.SortOrder.LayoutOrder,
			HorizontalAlignment = Enum.HorizontalAlignment.Center }),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 18), PaddingBottom = UDim.new(0, 18) }) })

	for rank, e in ipairs(list) do
		local holder, face = UIKit.comicBox({ Parent = grid, Color = PAPER, Tilt = math.random(-40, 40) / 10, ShadowOffset = 5, LayoutOrder = rank })
		local z = face.ZIndex
		UIKit.new("Frame", { BackgroundColor3 = C.Red, Size = UDim2.fromOffset(18, 18), Position = UDim2.new(0.5, 0, 0, 2),
			AnchorPoint = CENTER, ZIndex = z + 5, Parent = holder }, { UIKit.corner(UDim.new(1, 0)), UIKit.stroke(C.Outline, 2) })
		UIKit.label({ Text = "WANTED", Font = Theme.FontAlt, Color = C.Brown, StrokeThickness = 2, Size = UDim2.fromScale(0.9, 0.15),
			Position = UDim2.fromScale(0.5, 0.04), AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 40, ZIndex = z + 1, Parent = face })
		local pic = UIKit.new("Frame", { BackgroundColor3 = Color3.fromRGB(255, 248, 225), Size = UDim2.fromScale(0.7, 0.36),
			Position = UDim2.fromScale(0.5, 0.2), AnchorPoint = Vector2.new(0.5, 0), ZIndex = z + 1, Parent = face },
			{ UIKit.stroke(C.Brown, 3) })
		UIKit.label({ Text = e.Emoji or "😈", StrokeThickness = 0, Size = UDim2.fromScale(0.9, 0.9), Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = CENTER, MaxTextSize = 80, ZIndex = z + 2, Parent = pic })
		UIKit.label({ Text = e.Name or "???", Size = UDim2.fromScale(0.92, 0.1), Position = UDim2.fromScale(0.5, 0.58),
			AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 20, ZIndex = z + 1, Parent = face })
		UIKit.label({ Text = "ค่าหัว " .. fmt(e.Bounty) .. " 🍌", Color = C.Yellow, Size = UDim2.fromScale(0.92, 0.1),
			Position = UDim2.fromScale(0.5, 0.68), AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 20, ZIndex = z + 1, Parent = face })
		UIKit.label({ Text = "ข้อหา: " .. (e.Crime or "กาวเกินพิกัด"), Color = C.Ink, StrokeThickness = 0, Wrap = true,
			Size = UDim2.fromScale(0.9, 0.1), Position = UDim2.fromScale(0.5, 0.78), AnchorPoint = Vector2.new(0.5, 0),
			MaxTextSize = 14, ZIndex = z + 1, Parent = face })
		if not e.IsMe then
			UIKit.button({ Parent = holder, Text = "ล่า!", Color = C.Red, Size = UDim2.fromOffset(88, 40), Position = UDim2.new(0.5, 0, 1, 4),
				AnchorPoint = CENTER, Tilt = -4, Lip = 5, MaxTextSize = 24, ZIndex = z + 6, Debounce = 1,
				OnClick = function() if opts.OnHunt then opts.OnHunt(e) end end })
		else
			UIKit.badge(holder, "นี่คุณเอง!", C.Pink, { Size = UDim2.fromOffset(110, 32), Position = UDim2.new(0.5, 0, 1, 4), AnchorPoint = CENTER, ZIndex = z + 6 })
		end
		if rank == 1 then
			FX.rarityGlow(holder, "Legend")
			UIKit.badge(holder, "เบอร์ 1", C.Yellow, { Size = UDim2.fromOffset(84, 30), Position = UDim2.new(1, 6, 0, 8), AnchorPoint = Vector2.new(1, 0.5), Tilt = 12, ZIndex = z + 6 })
		elseif rank <= 3 then
			FX.rarityGlow(holder, "Epic", { Sparkles = false })
		end
	end

	if opts.Me then
		local _, bar = UIKit.comicBox({ Parent = panel, Size = UDim2.new(1, -40, 0, 50), Position = UDim2.new(0.5, 0, 1, -16),
			AnchorPoint = Vector2.new(0.5, 1), Color = C.Pink, Tilt = -1 })
		UIKit.label({ Text = string.format("ค่าหัวคุณ: %s 🍌  (อันดับ #%s)", fmt(opts.Me.Bounty), tostring(opts.Me.Rank or "-")),
			Size = UDim2.new(1, -20, 1, -10), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER, MaxTextSize = 26, Parent = bar })
	end
	return panel
end

return BountyBoard]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/CardFace.lua"] = [[
-- การ์ด 1 ใบ: แบ่งแถบแนวตั้งชัดเจน ข้อความไม่ทับกัน
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local S = require(ReplicatedStorage:WaitForChild("Shared"):WaitForChild("UI"):WaitForChild("Style"))

local CardFace = {}
CardFace.__index = CardFace
CardFace.ASPECT = 0.72

local GLOW = {
	none = { S.C.Ink, 1 }, playable = { S.C.Accent, 2 }, ready = { S.C.Good, 2.5 },
	target = { S.C.Info, 2.5 }, hover = { S.C.Accent, 3.5 }, selected = { S.C.Accent, 3 },
}

function CardFace.KeywordText(card)
	local out = {}
	if card and typeof(card.Keywords) == "table" then
		for k, v in card.Keywords do
			local kw = typeof(k) == "number" and v or (v and k)
			if typeof(kw) == "string" then table.insert(out, S.Name.Keyword[kw] or kw) end
		end
	end
	return table.concat(out, " · ")
end

local function box(parent, color, pos, size)
	return S.new("Frame", { BackgroundColor3 = color, Position = pos, Size = size, Parent = parent }, { S.corner(3) })
end

function CardFace.new(card, opts)
	opts = opts or {}
	local self = setmetatable({}, CardFace)
	local root = S.new("TextButton", {
		Name = "Card", AutoButtonColor = false, Text = "", Selectable = false,
		BackgroundColor3 = S.C.Paper, AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5), Size = opts.Size or UDim2.fromScale(1, 1),
		ClipsDescendants = true, ZIndex = 2,
	}, { S.corner(5) })
	if not opts.NoAspect then
		S.new("UIAspectRatioConstraint", {
			AspectRatio = CardFace.ASPECT, AspectType = Enum.AspectType.FitWithinMaxSize,
			DominantAxis = Enum.DominantAxis.Height, Parent = root,
		})
	end
	self.Root = root
	self.Stroke = S.stroke(S.C.Ink, 1, root)
	self.Scale = S.new("UIScale", { Parent = root })

	-- แถบบน: ค่าใช้แต้ม | ชื่อ
	self.CostBox = box(root, S.C.Ink, UDim2.fromScale(0.05, 0.035), UDim2.fromScale(0.24, 0.15))
	self.CostStroke = S.stroke(S.C.Ink, 1.5, self.CostBox)
	self.Cost = S.text({ Font = S.Font.Heavy, Color = S.C.Paper, XAlign = "Center", Max = 22, Parent = self.CostBox })
	self.NameLabel = S.text({ Font = S.Font.Bold, Color = S.C.Ink, Max = 15,
		Position = UDim2.fromScale(0.33, 0.035), Size = UDim2.fromScale(0.62, 0.15), Parent = root })
	-- ภาพ (ใช้สีธาตุ)
	self.Art = box(root, S.C.InkSoft, UDim2.fromScale(0.05, 0.21), UDim2.fromScale(0.9, 0.34))
	self.ArtText = S.text({ Font = S.Font.Heavy, Color = S.C.Paper, XAlign = "Center", Max = 28,
		Position = UDim2.fromScale(0.05, 0.2), Size = UDim2.fromScale(0.9, 0.6), Parent = self.Art })
	-- ประเภท / คำอธิบาย
	self.TypeLine = S.text({ Font = S.Font.Medium, Color = S.C.InkSoft, Max = 11,
		Position = UDim2.fromScale(0.05, 0.57), Size = UDim2.fromScale(0.9, 0.08), Parent = root })
	self.Desc = S.text({ Color = S.C.Ink, Max = 11, YAlign = "Top",
		Position = UDim2.fromScale(0.05, 0.66), Size = UDim2.fromScale(0.9, 0.17), Parent = root })
	-- แถบล่าง: ATK | สถานะ | HP
	self.AtkBox = box(root, Color3.fromRGB(160, 70, 55), UDim2.fromScale(0.05, 0.85), UDim2.fromScale(0.28, 0.12))
	self.Atk = S.text({ Font = S.Font.Heavy, Color = S.C.Paper, XAlign = "Center", Max = 18, Parent = self.AtkBox })
	self.HpBox = box(root, Color3.fromRGB(70, 120, 80), UDim2.fromScale(0.67, 0.85), UDim2.fromScale(0.28, 0.12))
	self.Hp = S.text({ Font = S.Font.Heavy, Color = S.C.Paper, XAlign = "Center", Max = 18, Parent = self.HpBox })
	self.Status = S.text({ Font = S.Font.Bold, Color = S.C.InkSoft, XAlign = "Center", Max = 11,
		Position = UDim2.fromScale(0.34, 0.85), Size = UDim2.fromScale(0.32, 0.12), Parent = root })
	self.Shade = S.new("Frame", { BackgroundColor3 = S.C.Bg, BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = root })

	self.Glow = "none"
	if card then self:Update(card) end
	return self
end

function CardFace:Update(card)
	self.Card = card
	local t = card.Type
	self.Cost.Text = tostring(card.Cost or 0)
	self.NameLabel.Text = card.Name or card.Id or "?"
	self.CostStroke.Color = S.Rarity[card.Rarity] or S.C.Ink
	local typeName = S.Name.Type[t] or t or ""
	local rarity = S.Name.Rarity[card.Rarity] or ""
	self.TypeLine.Text = rarity ~= "" and (typeName .. " · " .. rarity) or typeName

	local desc
	if t == "Character" then
		self.Art.BackgroundColor3 = S.Element[card.Element] or S.C.InkSoft
		self.ArtText.Text = S.Name.Element[card.Element] or card.Element or ""
		self.AtkBox.Visible, self.HpBox.Visible = true, true
		self.Atk.Text = tostring(card.ATK or 0)
		local hp = card.HP or 0
		self.Hp.Text = tostring(hp)
		self.HpBox.BackgroundColor3 = (card.MaxHP and hp < card.MaxHP)
			and Color3.fromRGB(165, 105, 50) or Color3.fromRGB(70, 120, 80)
		local lines = {}
		local kw = CardFace.KeywordText(card)
		if kw ~= "" then table.insert(lines, kw) end
		if card.WeaponName then
			table.insert(lines, ("ถือ %s (%s)"):format(card.WeaponName, tostring(card.WeaponDur or "-")))
		end
		desc = table.concat(lines, "\n")
		if self.LastHP and hp < self.LastHP then self:Flash() end
		self.LastHP = hp
	elseif t == "Weapon" then
		self.Art.BackgroundColor3 = Color3.fromRGB(88, 94, 102)
		self.ArtText.Text = "อาวุธ"
		local hasBonus = typeof(card.Bonus) == "number"
		self.AtkBox.Visible = hasBonus
		self.Atk.Text = hasBonus and ("+" .. card.Bonus) or ""
		self.HpBox.Visible = card.Durability ~= nil
		self.Hp.Text = tostring(card.Durability or "")
		desc = card.Desc or ""
	else
		self.Art.BackgroundColor3 = Color3.fromRGB(62, 82, 112)
		self.ArtText.Text = S.Name.Type[t] or ""
		self.AtkBox.Visible, self.HpBox.Visible = false, false
		desc = card.Desc or ""
	end
	self.Desc.Text = S.clean(desc)
end

function CardFace:SetGlow(kind)
	self.Glow = kind or "none"
	local g = GLOW[self.Glow] or GLOW.none
	self.Stroke.Color, self.Stroke.Thickness = g[1], g[2]
end

function CardFace:SetStatus(text, dim)
	self.Status.Text = text or ""
	self.Shade.BackgroundTransparency = dim and 0.55 or 1
end

function CardFace:SetCostWarning(on)
	self.CostBox.BackgroundColor3 = on and S.C.Bad or S.C.Ink
end

function CardFace:SetLift(on)
	if self.Lifted == on then return end
	self.Lifted = on
	self.Root.ZIndex = on and 3 or 2
	TweenService:Create(self.Scale, TweenInfo.new(0.1), { Scale = on and 1.06 or 1 }):Play()
end

function CardFace:PopIn()
	self.Scale.Scale = 0.85
	TweenService:Create(self.Scale, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 1 }):Play()
end

function CardFace:Flash()
	self.Stroke.Color, self.Stroke.Thickness = S.C.Bad, 3
	local token = (self.FlashToken or 0) + 1
	self.FlashToken = token
	task.delay(0.3, function()
		if self.FlashToken == token and self.Root.Parent then self:SetGlow(self.Glow) end
	end)
end

function CardFace:Destroy() self.Root:Destroy() end

return CardFace]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/CombatFX.lua"] = [[
-- StarterPlayerScripts/UIClient/CombatFX (ModuleScript)
-- ตัวเลขลอย / สั่น / กะพริบ
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local UI = game:GetService("ReplicatedStorage"):WaitForChild("Shared"):WaitForChild("UI")
local Theme = require(UI:WaitForChild("Theme"))
local Settings = require(UI:WaitForChild("Settings"))

local FX = {}
local STYLE = {
	Damage = { Color = Theme.Color.Red, Suffix = "", Y = 0 },
	Heal   = { Color = Theme.Color.Green, Suffix = " ❤️", Y = 0 },
	Atk    = { Color = Color3.fromRGB(255, 140, 40), Suffix = " ⚔️", Y = 0.3 },
	Shield = { Color = Theme.Color.Blue, Suffix = " 🛡️", Y = 0.3 },
	Points = { Color = Theme.Color.Yellow, Suffix = " 💰", Y = 0 },
}
local shaking = {}

-- วางตัวเลขใน ScreenGui เดียวกับเป้า เพื่อให้ตำแหน่งตรงเสมอ
local function centerIn(obj)
	local sg = obj:FindFirstAncestorWhichIsA("ScreenGui")
	if not sg then return nil end
	return sg, obj.AbsolutePosition + obj.AbsoluteSize / 2 - sg.AbsolutePosition
end

function FX.Number(target, amount, kind)
	if not (target and amount and amount ~= 0 and Settings.Get("DamageNumbers")) then return end
	local sg, p = centerIn(target)
	if not sg then return end
	local st = STYLE[kind] or (amount < 0 and STYLE.Damage or STYLE.Heal)
	local sp = Settings.Get("AnimSpeed") or 1
	local size = math.floor(math.clamp(sg.AbsoluteSize.Y / 14, 26, 64) * (1 + math.min(math.abs(amount), 10) * 0.04))
	p += Vector2.new(math.random(-12, 12), target.AbsoluteSize.Y * st.Y)

	local label = Instance.new("TextLabel")
	label.BackgroundTransparency = 1
	label.AnchorPoint = Vector2.new(0.5, 0.5)
	label.Position = UDim2.fromOffset(p.X, p.Y)
	label.Size = UDim2.fromOffset(size * 5, size)
	label.Font = Theme.Font
	label.TextSize = size
	label.TextColor3 = st.Color
	label.Text = (amount > 0 and "+" or "") .. amount .. st.Suffix
	label.ZIndex = 200
	local stroke = Instance.new("UIStroke")
	stroke.Thickness = 3
	stroke.Color = Theme.Color.Outline
	stroke.Parent = label
	local scale = Instance.new("UIScale")
	scale.Scale = 0.2
	scale.Parent = label
	label.Parent = sg

	TweenService:Create(scale, TweenInfo.new(0.18 / sp, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
	local rise = TweenInfo.new(0.8 / sp, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0, false, 0.35 / sp)
	TweenService:Create(label, rise, { Position = UDim2.fromOffset(p.X, p.Y - size * 1.8), TextTransparency = 1 }):Play()
	local t = TweenService:Create(stroke, rise, { Transparency = 1 })
	t:Play()
	t.Completed:Once(function() label:Destroy() end)
end

function FX.Flash(target, color)
	local f = Instance.new("Frame")
	f.Size = UDim2.fromScale(1, 1)
	f.BackgroundColor3 = color or Color3.new(1, 1, 1)
	f.BackgroundTransparency = 0.25
	f.BorderSizePixel = 0
	f.ZIndex = 20
	local c = Instance.new("UICorner")
	c.CornerRadius = UDim.new(0.1, 0)
	c.Parent = f
	f.Parent = target
	local t = TweenService:Create(f, TweenInfo.new(0.35), { BackgroundTransparency = 1 })
	t:Play()
	t.Completed:Once(function() f:Destroy() end)
end

function FX.Shake(target, power)
	if shaking[target] then return end
	shaking[target] = true
	local origin, t0, conn = target.Position, os.clock(), nil
	power = power or 6
	conn = RunService.RenderStepped:Connect(function()
		local e = os.clock() - t0
		if e > 0.3 or not target.Parent then
			conn:Disconnect()
			target.Position = origin
			shaking[target] = nil
			return
		end
		local k = power * (1 - e / 0.3)
		target.Position = origin + UDim2.fromOffset((math.random() * 2 - 1) * k, (math.random() * 2 - 1) * k)
	end)
end

-- ใช้กับตัวเลขที่เปลี่ยน: kind = "HP" | "Shield" | "Points"
function FX.Track(target, old, new, kind)
	if typeof(old) ~= "number" or typeof(new) ~= "number" or old == new or not target then return end
	local d = new - old
	if kind == "Points" then
		if d > 0 then FX.Number(target, d, "Points") end -- ตอนจ่ายพอยต์ไม่ต้องโชว์
		return
	end
	FX.Number(target, d, kind == "Shield" and "Shield" or nil)
	if d < 0 then
		FX.Shake(target, math.clamp(-d * 2, 4, 14))
		FX.Flash(target, kind == "Shield" and Theme.Color.Blue or Theme.Color.Red)
	end
end

return FX]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/DeckBuilder.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/DeckBuilder.lua
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)

local Config = require(Shared.Config)
local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local DeckBuilder = {}

-- กฎเดียวกับ DeckRules.MaxCopies / IsShield ฝั่งเซิร์ฟเวอร์ (ไม่งั้นเด็คที่ดูถูกจะโดนเซิร์ฟเวอร์ปฏิเสธตอนเซฟ)
local function maxCopies(def) return (def and Config.MAX_COPIES and Config.MAX_COPIES[def.Rarity]) or 1 end
local function isShield(def) return def.Type == "Spell" and type(def.Effect) == "table" and def.Effect.Kind == "Shield" end

-- ตรงกับกฎปัจจุบัน (รวม 24 ใบ) ถ้าเปลี่ยนกฎให้แก้ที่นี่ และแก้ใน DeckRules ฝั่งเซิร์ฟเวอร์ด้วย
DeckBuilder.QUOTA = Config and Config.DECK_COMPOSITION or { Character = 12, Weapon = 5, Spell = 7 }
local TYPES = { "Character", "Weapon", "Spell" }
local TYPE_ORDER = { Character = 1, Weapon = 2, Spell = 3 }
local TYPE_EMOJI = { Character = "🤪", Weapon = "🗡️", Spell = "✨" }
local SWAP_SFX = { "Boing", "Honk", "Quack", "Slip", "Pop" }

local function borderStroke(t)
	local s = UIKit.stroke(C.Outline, t)
	s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	return s
end

local function tile(parent, def, order)
	local holder, face = UIKit.comicBox({ Name = def.Id, Parent = parent, Color = C.CardBg, ShadowOffset = 4, LayoutOrder = order })
	local z = face.ZIndex
	UIKit.new("Frame", { BackgroundColor3 = Theme.TypeColor[def.Type] or C.Gray, BorderSizePixel = 0, Size = UDim2.fromScale(1, 0.2),
		ZIndex = z, Parent = face }, { UIKit.corner(Theme.Radius) })
	UIKit.label({ Text = Theme.TypeLabel[def.Type] or def.Type, Size = UDim2.fromScale(0.6, 0.16), Position = UDim2.fromScale(0.5, 0.02),
		AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 16, ZIndex = z + 1, Parent = face })
	UIKit.label({ Text = def.Emoji or TYPE_EMOJI[def.Type] or "❓", StrokeThickness = 0, Size = UDim2.fromScale(0.6, 0.32),
		Position = UDim2.fromScale(0.5, 0.23), AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 60, ZIndex = z + 1, Parent = face })
	UIKit.label({ Text = def.Name or def.Id, Size = UDim2.fromScale(0.92, 0.15), Position = UDim2.fromScale(0.5, 0.57),
		AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 18, ZIndex = z + 1, Parent = face })
	local stat = def.Type == "Character" and string.format("⚔%s ❤%s", tostring(def.ATK or "?"), tostring(def.HP or "?"))
		or def.Type == "Weapon" and ("+" .. tostring(def.Bonus or "?"))
		or (Theme.RarityLabel[def.Rarity] or "")
	UIKit.label({ Text = stat, Color = C.Yellow, Size = UDim2.fromScale(0.9, 0.12), Position = UDim2.fromScale(0.5, 0.74),
		AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 16, ZIndex = z + 1, Parent = face })

	local cost = UIKit.new("Frame", { BackgroundColor3 = C.Blue, Size = UDim2.fromOffset(34, 34), Position = UDim2.fromOffset(-8, -8),
		ZIndex = z + 3, Parent = holder }, { UIKit.corner(UDim.new(1, 0)), UIKit.stroke(C.Outline, 3) })
	UIKit.label({ Text = tostring(def.Cost or 0), Size = UDim2.fromScale(0.8, 0.8), Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = CENTER, MaxTextSize = 22, ZIndex = z + 4, Parent = cost })
	UIKit.tierBadge(holder, def.Rarity).Position = UDim2.new(1, -4, 0, 4)
	FX.rarityGlow(holder, def.Rarity, { Sparkles = false }) -- ในตารางไม่ใส่ประกาย เพื่อไม่ให้หนักเครื่อง
	local _, countLbl = UIKit.badge(holder, "0/0", C.Pink, { Size = UDim2.fromOffset(64, 26), Position = UDim2.new(0.5, 0, 1, -2),
		AnchorPoint = CENTER, ZIndex = z + 5 })
	local hit = UIKit.new("TextButton", { Text = "", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = z + 6, Parent = holder })
	return holder, countLbl, hit
end

-- opts = { Cards = {[id]=def}, Owned = {[id]=จำนวน}, Deck = {id,...}, OnSave = function(ids) return ok, msg end }
function DeckBuilder.Open(parent, opts)
	opts = opts or {}
	local cards, owned = {}, opts.Owned or {}
	for id, def in pairs(opts.Cards or {}) do
		if type(def) == "table" and def.Type ~= "Leader" then
			local copy = table.clone(def)
			copy.Id = copy.Id or id
			cards[id] = copy
		end
	end
	local deck = {}
	for _, id in ipairs(opts.Deck or {}) do deck[id] = (deck[id] or 0) + 1 end

	local panel = UIKit.panel(parent, "จัดเด็คกาวๆ", C.Pink)
	local function sorter(a, b)
		local da, db = cards[a], cards[b]
		if TYPE_ORDER[da.Type] ~= TYPE_ORDER[db.Type] then return TYPE_ORDER[da.Type] < TYPE_ORDER[db.Type] end
		if (da.Cost or 0) ~= (db.Cost or 0) then return (da.Cost or 0) < (db.Cost or 0) end
		return tostring(da.Name) < tostring(db.Name)
	end
	local function count(t)
		local n = 0
		for id, k in pairs(deck) do if cards[id] and cards[id].Type == t then n += k end end
		return n
	end

	-- ฝั่งซ้าย: คอลเลกชัน
	local left = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0.62, -10, 1, -64), Position = UDim2.new(0, 14, 0, 50), Parent = panel })
	local tabs = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 46), Parent = left }, {
		UIKit.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }) })
	local grid = UIKit.new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, -56),
		Position = UDim2.new(0, 0, 0, 56), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 10, ScrollBarImageColor3 = C.Pink, Parent = left }, {
		UIKit.new("UIGridLayout", { CellSize = UDim2.fromOffset(124, 172), CellPadding = UDim2.fromOffset(16, 18), SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 10), PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 14) }) })

	-- ฝั่งขวา: เด็ค
	local right = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(0.38, -24, 1, -64), Position = UDim2.new(0.62, 10, 0, 50), Parent = panel }, {
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder }) })
	local meters = {}
	for i, t in ipairs(TYPES) do
		local holder, face = UIKit.comicBox({ Parent = right, Size = UDim2.new(1, -10, 0, 44), LayoutOrder = i, Color = C.TableDark, ShadowOffset = 4 })
		local fill = UIKit.new("Frame", { BackgroundColor3 = Theme.TypeColor[t], BorderSizePixel = 0, Size = UDim2.fromScale(0, 1),
			ZIndex = face.ZIndex, Parent = face }, { UIKit.corner(Theme.Radius) })
		local lbl = UIKit.label({ Text = "", Size = UDim2.new(1, -16, 1, -8), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
			MaxTextSize = 24, ZIndex = face.ZIndex + 1, Parent = face })
		meters[t] = { holder = holder, fill = fill, lbl = lbl, last = -1 }
	end
	local list = UIKit.new("ScrollingFrame", { BackgroundColor3 = C.TableDark, BackgroundTransparency = 0.2, BorderSizePixel = 0,
		Size = UDim2.new(1, -10, 1, -236), LayoutOrder = 10, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 8, Parent = right }, {
		UIKit.corner(12), UIKit.stroke(C.Outline, 3),
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 6), PaddingLeft = UDim.new(0, 6) }) })
	local btnRow = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, -10, 0, 60), LayoutOrder = 20, Parent = right }, {
		UIKit.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder }) })

	local tiles, refresh, remove = {}, nil, nil

	local function shieldCount()
		local n = 0
		for id, k in pairs(deck) do if cards[id] and isShield(cards[id]) then n += k end end
		return n
	end

	local function add(id, holder)
		local def = cards[id]
		local q = DeckBuilder.QUOTA[def.Type]
		if not q then return end
		if (deck[id] or 0) >= maxCopies(def) then
			UIKit.shake(holder); UIKit.sfx("Honk", 0.1)
			UIKit.toast((def.Name or id) .. " ใส่ได้สูงสุด " .. maxCopies(def) .. " ใบ", C.Orange)
			return
		end
		if isShield(def) and shieldCount() >= (Config.MAX_SHIELDS_IN_DECK or 2) then
			UIKit.shake(holder); UIKit.sfx("Honk", 0.1)
			UIKit.toast("การ์ดโล่ใส่ได้ไม่เกิน " .. (Config.MAX_SHIELDS_IN_DECK or 2) .. " ใบ", C.Orange)
			return
		end
		if count(def.Type) >= q then
			UIKit.shake(holder); UIKit.sfx("Honk", 0.1)
			UIKit.toast((Theme.TypeLabel[def.Type] or def.Type) .. " เต็มแล้ว! (" .. q .. ")", C.Red)
			return
		end
		if (deck[id] or 0) >= (owned[id] or 0) then
			UIKit.shake(holder); UIKit.sfx("Honk", 0.1)
			UIKit.toast("มีใบนี้แค่ " .. (owned[id] or 0) .. " ใบ ไปสุ่มเพิ่มก่อน!", C.Orange)
			return
		end
		deck[id] = (deck[id] or 0) + 1
		UIKit.sfx(SWAP_SFX[math.random(#SWAP_SFX)], 0.25)
		UIKit.jelly(holder, 0.2)
		if (Theme.RarityTier[def.Rarity] or 1) >= 4 then FX.sparkles(holder, Theme.Rarity[def.Rarity], 10) end
		refresh()
	end

	remove = function(id)
		if not deck[id] then return end
		deck[id] -= 1
		if deck[id] <= 0 then deck[id] = nil end
		UIKit.sfx("Slip", 0.25)
		if tiles[id] then UIKit.jelly(tiles[id].holder, -0.12) end
		refresh()
	end

	local ids = {}
	for id, n in pairs(owned) do
		if n > 0 and cards[id] and DeckBuilder.QUOTA[cards[id].Type] then table.insert(ids, id) end
	end
	table.sort(ids, sorter)
	for i, id in ipairs(ids) do
		local holder, countLbl, hit = tile(grid, cards[id], i)
		tiles[id] = { holder = holder, count = countLbl, type = cards[id].Type }
		hit.Activated:Connect(function() add(id, holder) end)
		hit.MouseButton2Click:Connect(function() remove(id) end)
	end

	for i, f in ipairs({ { "All", "ทั้งหมด", C.Yellow }, { "Character", "ตัวละคร", C.Pink }, { "Weapon", "อาวุธ", C.Orange }, { "Spell", "สกิล", C.Blue } }) do
		UIKit.button({ Parent = tabs, Text = f[2], Color = f[3], Size = UDim2.new(0.24, -6, 1, 0), LayoutOrder = i, Lip = 4,
			Tilt = (i % 2 == 0) and 2 or -2, MaxTextSize = 22, OnClick = function()
				for _, t in pairs(tiles) do t.holder.Visible = (f[1] == "All" or t.type == f[1]) end
			end })
	end

	local saveBtn = UIKit.button({ Parent = btnRow, Text = "เซฟเด็ค!", Color = C.Green, Size = UDim2.new(0.62, -6, 1, 0), LayoutOrder = 1,
		Debounce = 1, OnClick = function()
			local out = {}
			for id, k in pairs(deck) do for _ = 1, k do table.insert(out, id) end end
			if not opts.OnSave then return end
			local okc, ok, msg = pcall(opts.OnSave, out)
			if not okc then warn("[DeckBuilder] OnSave error: " .. tostring(ok)); ok, msg = false, "เซฟไม่ผ่าน ลองใหม่" end
			if ok then
				UIKit.toast("เซฟแล้ว! เด็คนี้กาวมาก", C.Green)
				FX.sparkles(panel, C.Lime, 24)
			else
				local text = msg
				if opts.Message then text = opts.Message(msg) end
				UIKit.toast(tostring(text or "เซฟไม่ผ่าน ลองใหม่"), C.Red)
			end
		end })
	UIKit.button({ Parent = btnRow, Text = "ล้าง", Color = C.Red, Size = UDim2.new(0.38, -6, 1, 0), LayoutOrder = 2,
		OnClick = function() deck = {}; UIKit.sfx("Fart", 0.2); refresh() end })

	refresh = function()
		local valid = true
		for _, t in ipairs(TYPES) do
			local n, q, m = count(t), DeckBuilder.QUOTA[t], meters[t]
			valid = valid and n == q
			UIKit.tween(m.fill, 0.25, { Size = UDim2.fromScale(math.clamp(n / q, 0, 1), 1) }, Enum.EasingStyle.Back)
			local txt = string.format("%s %d/%d%s", Theme.TypeLabel[t], n, q, n == q and " ✔" or "")
			if n ~= m.last then
				if m.last >= 0 then UIKit.bounceText(m.lbl, txt, 0.25) else UIKit.setText(m.lbl, txt) end
				if n == q and m.last >= 0 then FX.sparkles(m.holder, Theme.TypeColor[t], 8) end
				m.last = n
			end
		end
		for id, t in pairs(tiles) do UIKit.setText(t.count, string.format("%d/%d", deck[id] or 0, owned[id] or 0)) end
		for _, ch in ipairs(list:GetChildren()) do if ch:IsA("GuiButton") then ch:Destroy() end end
		local inDeck = {}
		for id in pairs(deck) do if cards[id] then table.insert(inDeck, id) end end
		table.sort(inDeck, sorter)
		for i, id in ipairs(inDeck) do
			local def = cards[id]
			local row = UIKit.new("TextButton", { Text = "", AutoButtonColor = false, BackgroundColor3 = Theme.TypeColor[def.Type] or C.Gray,
				Size = UDim2.new(1, -12, 0, 34), LayoutOrder = i, Parent = list }, { UIKit.corner(10), borderStroke(2.5) })
			UIKit.label({ Text = string.format("x%d  %s", deck[id], def.Name or id), AlignX = Enum.TextXAlignment.Left,
				Size = UDim2.new(1, -54, 1, -6), Position = UDim2.new(0, 10, 0, 3), MaxTextSize = 20, Parent = row })
			UIKit.label({ Text = "T" .. (Theme.RarityTier[def.Rarity] or 1), Color = Theme.Rarity[def.Rarity] or C.White,
				Size = UDim2.new(0, 38, 1, -6), Position = UDim2.new(1, -44, 0, 3), MaxTextSize = 20, Parent = row })
			row.Activated:Connect(function() remove(id) end)
		end
		UIKit.setDisabled(saveBtn, not valid)
	end
	refresh()
	return panel
end

return DeckBuilder]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/DragController.lua"] = [[
-- ระบบลากวางที่ใช้ได้ทั้งเมาส์และทัชสกรีน
-- รับการลากทีละอันเท่านั้น และยกเลิกเมื่อกด Esc / คลิกขวา / ออกจากหน้าต่าง / การ์ดหายไป
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local S = require(ReplicatedStorage:WaitForChild("Shared"):WaitForChild("UI"):WaitForChild("Style"))

local Drag = {}
local THRESHOLD = 8 -- ขยับเกินกี่พิกเซลถึงนับว่าลาก (น้อยกว่านี้ = แตะ)

local gui = S.screen("DragLayer", 20, Players.LocalPlayer:WaitForChild("PlayerGui"))
local layer = S.new("Frame", { Name = "Layer", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = gui })
local line = S.new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = S.C.Accent,
	Visible = false, ZIndex = 10, Parent = layer })
local head = S.new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(16, 16),
	Rotation = 45, BackgroundColor3 = S.C.Accent, Visible = false, ZIndex = 11, Parent = layer })
S.stroke(S.C.Ink, 2, head)

local active = nil

local function vec(input) return Vector2.new(input.Position.X, input.Position.Y) end
local function toLayer(p) return p - layer.AbsolutePosition end

local function inside(g, p)
	if not g.Parent or not g.Visible then return false end
	local a, s = g.AbsolutePosition, g.AbsoluteSize
	return p.X >= a.X and p.Y >= a.Y and p.X <= a.X + s.X and p.Y <= a.Y + s.Y
end

-- เลือกเป้าที่เล็กที่สุดที่ครอบจุดนั้น (การ์ดชนะโซนใหญ่)
local function hitTest(a)
	local best, bestArea = nil, math.huge
	for _, t in a.targets do
		local g = t.Gui
		if g and inside(g, a.pos) then
			local area = g.AbsoluteSize.X * g.AbsoluteSize.Y
			if area < bestArea then best, bestArea = t, area end
		end
	end
	return best
end

local function call(fn, ...)
	if not fn then return end
	local ok, err = pcall(fn, ...)
	if not ok then warn("[Drag] " .. tostring(err)) end
end

local function finish(drop)
	local a = active
	if not a then return end
	active = nil
	if a.dragging and drop then a.hover = hitTest(a) end
	if a.ghost then a.ghost:Destroy() end
	line.Visible, head.Visible = false, false
	local spec = a.spec
	if a.dragging then
		call(spec.OnEnd)
		if spec.OnDrop then task.spawn(spec.OnDrop, drop and a.hover or nil) end
	elseif drop and spec.OnTap then
		task.spawn(spec.OnTap)
	end
end

local function startDragging(a)
	local spec = a.spec
	if spec.CanStart then
		local ok, allowed = pcall(spec.CanStart)
		if not ok or not allowed then
			active = nil
			return false
		end
	end
	a.dragging = true
	if spec.Targets then
		local ok, list = pcall(spec.Targets)
		a.targets = (ok and typeof(list) == "table") and list or {}
	end
	if spec.Ghost then
		local ok, g = pcall(spec.Ghost)
		if ok and typeof(g) == "Instance" then
			g.Parent = layer
			a.ghost = g
		end
	end
	call(spec.OnStart)
	return true
end

function Drag.Begin(input, spec)
	if active then return false end
	local p = vec(input)
	active = {
		spec = spec, input = input, start = p, pos = p, dragging = false, targets = {},
		isMouse = input.UserInputType == Enum.UserInputType.MouseButton1,
	}
	return true
end

function Drag.Cancel() finish(false) end
function Drag.IsActive() return active ~= nil end
function Drag.IsDragging() return active ~= nil and active.dragging end
function Drag.DraggingSource() return active and active.dragging and active.spec.Source or nil end

RunService.RenderStepped:Connect(function()
	local a = active
	if not a then return end
	if a.isMouse and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
		finish(true) -- กันกรณีพลาด InputEnded (เช่นปล่อยเมาส์นอกหน้าต่าง)
		return
	end
	if not a.dragging then
		if (a.pos - a.start).Magnitude < THRESHOLD then return end
		if not startDragging(a) then return end
	end
	local lp = toLayer(a.pos)
	if a.ghost then
		local lift = a.isMouse and 0 or a.ghost.AbsoluteSize.Y * 0.35 -- ทัช: ยกการ์ดขึ้นไม่ให้นิ้วบัง
		a.ghost.Position = UDim2.fromOffset(lp.X, lp.Y - lift)
	end
	if a.spec.Arrow then
		local from = toLayer(a.start)
		local d = lp - from
		local len = d.Magnitude
		line.Visible, head.Visible = len > 4, len > 4
		line.Size = UDim2.fromOffset(len, 4)
		line.Position = UDim2.fromOffset((from.X + lp.X) / 2, (from.Y + lp.Y) / 2)
		line.Rotation = math.deg(math.atan2(d.Y, d.X))
		head.Position = UDim2.fromOffset(lp.X, lp.Y)
	end
	local hover = hitTest(a)
	if hover ~= a.hover then
		a.hover = hover
		call(a.spec.OnHover, hover)
	end
end)

local function onMove(input)
	local a = active
	if not a then return end
	if a.isMouse then
		if input.UserInputType == Enum.UserInputType.MouseMovement then a.pos = vec(input) end
	elseif input == a.input then
		a.pos = vec(input)
	end
end

local function onEnd(input)
	local a = active
	if not a then return end
	if (a.isMouse and input.UserInputType == Enum.UserInputType.MouseButton1) or input == a.input then
		a.pos = vec(input)
		finish(true)
	end
end

UserInputService.InputChanged:Connect(onMove)
UserInputService.TouchMoved:Connect(onMove)
UserInputService.InputEnded:Connect(onEnd)
UserInputService.TouchEnded:Connect(onEnd)
UserInputService.InputBegan:Connect(function(input)
	if active and (input.KeyCode == Enum.KeyCode.Escape or input.UserInputType == Enum.UserInputType.MouseButton2) then
		Drag.Cancel()
	end
end)
UserInputService.WindowFocusReleased:Connect(Drag.Cancel)

return Drag
]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/FarmUI.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/FarmUI.lua
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Debris = game:GetService("Debris")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local FarmUI = {}

local function now() return workspace:GetServerTimeNow() end

local function sample()
	local t = now()
	return {
		{ Id = "GlueGarden", Name = "สวนกาว", Emoji = "🌻", Color = C.Lime, Rate = 6, Cap = 120, LastClaim = t - 600, Level = 1 },
		{ Id = "GemMine", Name = "เหมืองเจม", Emoji = "💎", Color = C.Blue, Rate = 1, Cap = 20, LastClaim = t - 900, Level = 1 },
		{ Id = "MemePond", Name = "บ่อเลี้ยงมีม", Emoji = "🐸", Color = C.Pink, Rate = 3, Cap = 60, LastClaim = t - 300, Level = 1 },
	}
end

local function fly(panel, emoji, fromGui, toGui, n)
	local pa, ps = panel.AbsolutePosition, panel.AbsoluteSize
	local function rel(g)
		local c = g.AbsolutePosition + g.AbsoluteSize / 2 - pa
		return UDim2.fromScale(c.X / ps.X, c.Y / ps.Y)
	end
	local a, b = rel(fromGui), rel(toGui)
	for i = 1, n do
		task.delay(i * 0.04, function()
			local l = UIKit.new("TextLabel", { BackgroundTransparency = 1, Text = emoji, TextScaled = true, Size = UDim2.fromOffset(34, 34),
				AnchorPoint = CENTER, Position = a, ZIndex = 90, Parent = panel })
			local mid = a:Lerp(b, 0.5) + UDim2.fromScale((math.random() - 0.5) * 0.3, -0.2)
			UIKit.tween(l, 0.25, { Position = mid })
			task.delay(UIKit.dur(0.25), function()
				if l.Parent then UIKit.tween(l, 0.3, { Position = b }, Enum.EasingStyle.Quad, Enum.EasingDirection.In) end
			end)
			Debris:AddItem(l, UIKit.dur(0.6) + 0.1)
		end)
	end
	UIKit.sfx("Coin", 0.2)
end

-- opts = { Farms = {...}, Wallet = number, WalletEmoji = "🪙",
--          OnClaim = function(id) return ok, amount end, OnUpgrade = function(id) return ok, newFarm end }
function FarmUI.Open(parent, opts)
	opts = opts or {}
	local farms = opts.Farms or sample()
	local wallet, wEmoji = opts.Wallet or 0, opts.WalletEmoji or "🪙"
	local panel = UIKit.panel(parent, "ฟาร์มชิลๆ", C.Green)
	local walletBadge, walletLbl = UIKit.badge(panel, wEmoji .. " " .. wallet, C.Yellow, { Size = UDim2.fromOffset(190, 42),
		Position = UDim2.new(0, 22, 0, 52), Tilt = -3, MaxTextSize = 26, ZIndex = 60 })

	local row = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, -40, 1, -130), Position = UDim2.new(0, 20, 0, 110), Parent = panel }, {
		UIKit.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0.02, 0),
			HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })

	local views = {}
	for i, f in ipairs(farms) do
		local holder, face = UIKit.comicBox({ Parent = row, Size = UDim2.fromScale(0.31, 1), LayoutOrder = i, Color = C.CardBg,
			Tilt = (i % 2 == 0) and 1.5 or -1.5 })
		local z = face.ZIndex
		UIKit.new("Frame", { BackgroundColor3 = f.Color or C.Lime, BorderSizePixel = 0, Size = UDim2.fromScale(1, 0.45), ZIndex = z, Parent = face },
			{ UIKit.corner(Theme.Radius) })
		local icon = UIKit.label({ Text = f.Emoji or "🌱", StrokeThickness = 0, Size = UDim2.fromScale(0.5, 0.3), Position = UDim2.fromScale(0.5, 0.06),
			AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 90, ZIndex = z + 1, Parent = face })
		TweenService:Create(icon, TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
			{ Rotation = 8, Position = icon.Position - UDim2.fromScale(0, 0.02) }):Play()
		UIKit.label({ Text = f.Name, Size = UDim2.fromScale(0.9, 0.09), Position = UDim2.fromScale(0.5, 0.47), AnchorPoint = Vector2.new(0.5, 0),
			MaxTextSize = 28, ZIndex = z + 1, Parent = face })
		local lvBadge, lvLbl = UIKit.badge(holder, "Lv." .. (f.Level or 1), C.Purple, { Size = UDim2.fromOffset(70, 28),
			Position = UDim2.new(1, -6, 0, 6), AnchorPoint = Vector2.new(1, 0), Tilt = 8, ZIndex = z + 3 })
		local track = UIKit.new("Frame", { BackgroundColor3 = C.Ink, Size = UDim2.fromScale(0.86, 0.07), Position = UDim2.fromScale(0.5, 0.6),
			AnchorPoint = Vector2.new(0.5, 0), ZIndex = z + 1, Parent = face }, { UIKit.corner(UDim.new(1, 0)), UIKit.stroke(C.Outline, 2.5) })
		local fill = UIKit.new("Frame", { BackgroundColor3 = f.Color or C.Lime, BorderSizePixel = 0, Size = UDim2.fromScale(0, 1), ZIndex = z + 2,
			Parent = track }, { UIKit.corner(UDim.new(1, 0)) })
		local stored = UIKit.label({ Text = "0/" .. f.Cap, Size = UDim2.fromScale(0.9, 1.3), Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = CENTER, MaxTextSize = 18, ZIndex = z + 3, Parent = track })
		UIKit.label({ Text = string.format("+%s / นาที", tostring(f.Rate)), Color = C.Yellow, Size = UDim2.fromScale(0.8, 0.06),
			Position = UDim2.fromScale(0.5, 0.69), AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 18, ZIndex = z + 1, Parent = face })
		local fullBadge = UIKit.badge(holder, "เต็ม!!", C.Red, { Size = UDim2.fromOffset(76, 30), Position = UDim2.new(0, -6, 0, 6), Tilt = -10, ZIndex = z + 3 })
		fullBadge.Visible = false

		local v = { fill = fill, stored = stored, fullBadge = fullBadge, value = 0 }
		v.claim = UIKit.button({ Parent = face, Text = "เก็บ!", Color = C.Lime, Size = UDim2.fromScale(0.86, 0.11), Position = UDim2.fromScale(0.5, 0.77),
			AnchorPoint = Vector2.new(0.5, 0), ZIndex = z + 2, Debounce = 0.8, OnClick = function()
				if v.value < 1 then return end
				local ok, amount
				if opts.OnClaim then ok, amount = opts.OnClaim(f.Id) else ok, amount = true, v.value end -- ถ้าไม่ส่ง OnClaim มาจะเป็นโหมดตัวอย่าง
				if not ok then UIKit.toast(tostring(amount or "เก็บไม่ได้ ลองใหม่"), C.Red) return end
				amount = tonumber(amount) or 0
				f.LastClaim = now()
				fly(panel, f.Emoji or wEmoji, v.claim, walletBadge, math.clamp(amount, 3, 12))
				task.delay(UIKit.dur(0.45), function()
					UIKit.countTo(walletLbl, wallet, wallet + amount, 0.6, wEmoji .. " %d")
					wallet += amount
				end)
				FX.sparkles(holder, f.Color or C.Lime, 10)
			end })
		UIKit.button({ Parent = face, Text = "อัปเกรด", Color = C.Orange, Size = UDim2.fromScale(0.6, 0.08), Position = UDim2.fromScale(0.5, 0.9),
			AnchorPoint = Vector2.new(0.5, 0), Lip = 4, MaxTextSize = 20, ZIndex = z + 2, Debounce = 1, OnClick = function()
				if not opts.OnUpgrade then UIKit.toast("ยังไม่เปิดระบบอัปเกรด", C.Orange) return end
				local ok, nf = opts.OnUpgrade(f.Id)
				if not ok then UIKit.toast(tostring(nf or "เงินไม่พอ!"), C.Red) return end
				if type(nf) == "table" then for k, val in pairs(nf) do f[k] = val end end
				UIKit.bounceText(lvLbl, "Lv." .. (f.Level or 1), 0.4)
				FX.sparkles(holder, C.Yellow, 16)
				UIKit.sfx("LevelUp")
			end })
		views[f.Id] = v
	end

	local acc, tick = 0, 0
	local conn = RunService.Heartbeat:Connect(function(dt)
		acc += dt
		if acc < 0.2 then return end
		acc = 0
		tick += 1
		for _, f in ipairs(farms) do
			local v = views[f.Id]
			local val = math.min(f.Cap, math.floor(math.max(0, now() - (f.LastClaim or now())) / 60 * f.Rate))
			v.value = val
			v.fill.Size = UDim2.fromScale(val / f.Cap, 1)
			v.stored.Text = string.format("%d/%d", val, f.Cap)
			v.fullBadge.Visible = val >= f.Cap
			if val >= f.Cap and tick % 5 == 0 then UIKit.jelly(v.fullBadge, 0.25) end
			UIKit.setDisabled(v.claim, val < 1)
		end
	end)
	panel.Destroying:Connect(function() conn:Disconnect() end)
	return panel
end

return FarmUI]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/GateRoller.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/GateRoller.lua
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)
local CardView = require(Shared.UI.CardView)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local ORDER = { "Golden", "Pumped", "Normal", "Droopy", "Poop" }
local GateRoller = {}

local function pause(t) task.wait(UIKit.dur(t)) end

local function cardVisual(parent, card)
	local holder = UIKit.new("Frame", { Name = "GateCard", BackgroundTransparency = 1, AnchorPoint = CENTER,
		Position = UDim2.fromScale(0.5, 1.3), Size = UDim2.fromScale(0.14, 0.3), ZIndex = 320, Parent = parent },
		{ UIKit.new("UIAspectRatioConstraint", { AspectRatio = 0.72 }) })
	local ok, view = pcall(function() return card and CardView.new(card, {}) end)
	local g = ok and view and (typeof(view) == "Instance" and view or view.Root)
	if g then
		g.AnchorPoint, g.Position, g.Size = CENTER, UDim2.fromScale(0.5, 0.5), UDim2.fromScale(1, 1)
		g.Parent = holder
	else -- การ์ดที่ไม่เห็นหน้า (เช่น ฝั่งศัตรู) แสดงเป็นหลังการ์ดเครื่องหมาย ?
		local _, face = UIKit.comicBox({ Parent = holder, Color = C.Purple, ZIndex = 320 })
		UIKit.label({ Text = "?", Font = Theme.FontAlt, Color = C.Yellow, MaxTextSize = 120, ZIndex = 322, Parent = face })
	end
	return holder
end

local function sunburst(parent)
	local r = UIKit.new("Frame", { Name = "Rays", BackgroundTransparency = 1, AnchorPoint = CENTER, Position = UDim2.fromScale(0.5, 0.45),
		Size = UDim2.fromScale(1.6, 1.6), ZIndex = 301, Parent = parent }, { UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1 }) })
	for i = 0, 11 do
		UIKit.new("Frame", { BackgroundColor3 = C.Yellow, BackgroundTransparency = 0.82, BorderSizePixel = 0, AnchorPoint = CENTER,
			Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(0.07, 0, 1, 0), Rotation = i * 15, ZIndex = 301, Parent = r })
	end
	FX.spin(r, 25)
	return r
end

local function run(parent, card, outcomeId, isMine)
	local info = Theme.GateInfo[outcomeId] or Theme.GateInfo.Normal
	local color = Theme.GateColor[outcomeId] or C.Blue

	local root = UIKit.new("Frame", { Name = "GateRoll", BackgroundColor3 = C.TableDark, BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1), ZIndex = 300, Parent = parent })
	UIKit.tween(root, 0.25, { BackgroundTransparency = 0.25 })
	sunburst(root)
	local head = UIKit.title({ Parent = root, Text = isMine and "เกตของเรา!!" or "เกตฝั่งศัตรู!!", Color = isMine and C.Lime or C.Pink,
		Size = UDim2.fromScale(0.6, 0.12), Position = UDim2.fromScale(0.5, 0.1), AnchorPoint = CENTER, ZIndex = 330 })
	UIKit.bounceText(head, nil, 0.5)

	local portal = FX.summonCircle(root, { Size = UDim2.fromScale(0.36, 0.36), Position = UDim2.fromScale(0.5, 0.45),
		Square = true, Color = C.Purple, ZIndex = 305 })
	portal:SetActive(true)
	UIKit.sfx("PortalOpen", 0.1)

	-- 1) การ์ดลอยขึ้นมา แล้วหมุนตัวหายเข้าไปในประตู
	local cardH = cardVisual(root, card)
	UIKit.tween(cardH, 0.45, { Position = UDim2.fromScale(0.5, 0.45) }, Enum.EasingStyle.Back)
	pause(0.6)
	UIKit.tween(cardH, 0.4, { Rotation = 360 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
	UIKit.tween(UIKit.getScale(cardH), 0.4, { Scale = 0.1 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
	pause(0.4)
	cardH.Visible = false
	portal:Burst(C.Purple)

	-- 2) วงล้อสล็อต หมุนเร็วแล้วค่อยๆ ช้าลง
	local reelHolder, reel = UIKit.comicBox({ Parent = root, Size = UDim2.fromScale(0.36, 0.11), Position = UDim2.fromScale(0.5, 0.76),
		AnchorPoint = CENTER, Color = C.White, Tilt = -2, ZIndex = 330 })
	local reelLabel = UIKit.label({ Text = "", Size = UDim2.new(1, -20, 1, -10), Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = CENTER, MaxTextSize = 44, ZIndex = 332, Parent = reel })
	local steps, start = 16 + math.random(0, 5), math.random(1, #ORDER)
	for i = 1, steps do
		local id = (i == steps) and outcomeId or ORDER[(start + i) % #ORDER + 1]
		local gi = Theme.GateInfo[id] or info
		reel.BackgroundColor3 = Theme.GateColor[id] or C.Blue
		UIKit.bounceText(reelLabel, gi.Emoji .. " " .. gi.Text, 0.15)
		UIKit.sfx("Tick", 0.3)
		if i > steps - 3 then UIKit.shake(reelHolder, 5) end
		pause(0.04 + (i / steps) ^ 3 * 0.42)
	end

	-- 3) เผยผล
	local verdict, vColor
	if info.Kind == "Win" then
		verdict, vColor = "เปิดติด!!!", C.Yellow
		FX.flash(root, color); FX.shockwave(reelHolder, color); FX.sparkles(root, color, 30)
		UIKit.rain(root, info.Emoji, 22)
		UIKit.sfx("GateWin")
	elseif info.Kind == "Fail" then
		verdict, vColor = "เกลือ!!!", C.Orange
		FX.flash(root, C.Red); UIKit.shake(root, 22); UIKit.shake(reelHolder, 14)
		UIKit.rain(root, info.Emoji, 18)
		UIKit.sfx("GateFail")
	else
		verdict, vColor = "เฉยๆ อะ...", C.Gray
		UIKit.sfx("Boing")
		local weed = UIKit.label({ Text = "🌾", StrokeThickness = 0, Size = UDim2.fromOffset(64, 64),
			Position = UDim2.fromScale(-0.1, 0.62), ZIndex = 335, Parent = root })
		UIKit.tween(weed, 1.4, { Position = UDim2.fromScale(1.1, 0.62), Rotation = 720 }, Enum.EasingStyle.Linear)
	end
	local vFront = UIKit.title({ Parent = root, Text = verdict, Color = vColor, Size = UDim2.fromScale(0.7, 0.18),
		Position = UDim2.fromScale(0.5, 0.45), AnchorPoint = CENTER, Tilt = info.Kind == "Fail" and 6 or -6, MaxTextSize = 110, ZIndex = 340 })
	UIKit.bounceText(vFront, nil, 0.8)
	UIKit.jelly(reelHolder, 0.35)
	pause(1.5)

	-- 4) ปิดฉาก
	UIKit.tween(root, 0.3, { BackgroundTransparency = 1 })
	for _, ch in ipairs(root:GetChildren()) do
		if ch:IsA("GuiObject") then
			UIKit.tween(UIKit.getScale(ch), 0.25, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		end
	end
	pause(0.32)
	root:Destroy()
end

function GateRoller.Play(parent, card, outcomeId, isMine, onDone)
	if not parent then if onDone then onDone() end return end
	task.spawn(function()
		local ok, err = pcall(run, parent, card, outcomeId, isMine)
		if not ok then warn("[GateRoller]", err) end
		if onDone then onDone() end
	end)
end

return GateRoller]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/HandFan.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/HandFan.lua
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)
local Config = require(Shared.Config)

local C = UIKit.Theme.Color
local MAX_HAND = Config.MAX_HAND or 5
local DRAW_PER_TURN = Config.DRAW_PER_TURN or 2

local HandFan = {}
local states = setmetatable({}, { __mode = "k" })

-- CardView อาจคืนมาเป็น Instance หรือ table ที่มี .Root
local function rootOf(v)
	if typeof(v) == "Instance" then return v end
	if type(v) == "table" then return v.Root or v.Frame or v.Gui or v.Instance end
	return nil
end
HandFan.rootOf = rootOf

-- กฎเดียวกับ Match:Draw: ขาดกี่ใบจั่วเท่านั้น แต่ไม่เกิน DRAW_PER_TURN
function HandFan.DrawPreview(handCount)
	return math.clamp(MAX_HAND - handCount, 0, DRAW_PER_TURN)
end

local function targetFor(st, i, n)
	local off = i - (n + 1) / 2
	local spread = math.min(7, 28 / math.max(n - 1, 1))   -- องศาต่อใบ
	local step = math.min(0.16, 0.8 / math.max(n, 1))     -- ระยะห่างแนวนอน
	local x, y, rot, scale = 0.5 + off * step, 1 + off * off * 0.022, off * spread, 1
	local h = st.hover and table.find(st.cards, st.hover)
	if h then
		if i == h then
			y, rot, scale = 0.84, 0, 1.18
		else
			x += (i < h and -1 or 1) * 0.045              -- ใบข้างๆ หลบให้
		end
	end
	if st.cards[i] == st.held then y, scale = 1.15, 0.85 end -- ใบที่กำลังลากจะยุบลง
	return UDim2.fromScale(x, y), rot, scale
end

local function arrange(st, fresh)
	local n = #st.cards
	for i, g in ipairs(st.cards) do
		local pos, rot, scale = targetFor(st, i, n)
		g.ZIndex = (g == st.hover) and 60 or 10 + i
		local delay = fresh and fresh[g]
		local t = delay and 0.45 or 0.22
		local function go()
			if not g.Parent then return end
			UIKit.tween(g, t, { Position = pos, Rotation = rot }, Enum.EasingStyle.Back)
			UIKit.tween(UIKit.getScale(g), t, { Scale = scale }, Enum.EasingStyle.Back)
		end
		if delay then
			task.delay(UIKit.dur(delay), function()
				go()
				UIKit.sfx("Draw", 0.2)
				FX.sparkles(st.container, C.Yellow, 8, Vector2.new(pos.X.Scale, 0.6))
			end)
		else
			go()
		end
	end
end

local function updateCounter(st, n, grew)
	local full = n >= MAX_HAND
	UIKit.setText(st.countLabel, string.format("มือ %d/%d", n, MAX_HAND))
	st.countBadge.BackgroundColor3 = full and C.Red or C.Yellow
	local nxt = HandFan.DrawPreview(n)
	UIKit.setText(st.drawLabel, nxt > 0 and ("เทิร์นหน้าจั่ว +" .. nxt) or "เทิร์นหน้าไม่ได้จั่ว")
	st.drawBadge.BackgroundColor3 = nxt > 0 and C.Blue or C.Gray
	if grew then
		UIKit.jelly(st.countBadge, 0.3)
		if full then UIKit.popup(st.countBadge, "มือเต็ม!", C.Red) end
	end
end

local function hook(st, g)
	g.AnchorPoint = Vector2.new(0.5, 1)
	g.MouseEnter:Connect(function()
		if st.held then return end
		st.hover = g
		arrange(st)
		UIKit.sfx("CardHover", 0.25)
	end)
	g.MouseLeave:Connect(function()
		if st.hover == g then st.hover = nil; arrange(st) end
	end)
end

function HandFan.Container(parent, position, size, anchor)
	local c = UIKit.new("Frame", {
		Name = "HandFan", BackgroundTransparency = 1, Position = position or UDim2.fromScale(0.2, 0.7),
		Size = size or UDim2.fromScale(0.6, 0.3), AnchorPoint = anchor or Vector2.zero, Parent = parent,
	})
	local countBadge, countLabel = UIKit.badge(c, "มือ 0/" .. MAX_HAND, C.Yellow, {
		Size = UDim2.fromOffset(130, 34), Position = UDim2.new(0, 0, 0, -6), AnchorPoint = Vector2.new(0, 1), ZIndex = 70 })
	local drawBadge, drawLabel = UIKit.badge(c, "", C.Blue, {
		Size = UDim2.fromOffset(190, 30), Position = UDim2.new(0, 140, 0, -8), AnchorPoint = Vector2.new(0, 1), Tilt = 3, MaxTextSize = 16, ZIndex = 70 })
	states[c] = {
		container = c, cards = {}, known = setmetatable({}, { __mode = "k" }), lastN = 0,
		countBadge = countBadge, countLabel = countLabel, drawBadge = drawBadge, drawLabel = drawLabel,
	}
	updateCounter(states[c], 0, false)
	return c
end

function HandFan.Layout(container, views)
	local st = states[container]
	if not st then return end
	local list = {}
	for _, v in ipairs(views or {}) do
		local g = rootOf(v)
		if g then table.insert(list, g) end
	end
	st.cards = list
	local n = #list
	-- ดูการ์ดใหม่จากจำนวนใบ ไม่ใช่จาก instance ถ้า MatchUI สร้างการ์ดใหม่ทุกครั้งที่ render การ์ดเก่าจะได้ไม่บินเข้ามาซ้ำ
	local drawn = math.max(0, n - st.lastN)
	local fresh = {}
	for i, g in ipairs(list) do
		if g.Parent ~= container then g.Parent = container end
		if not st.known[g] then
			st.known[g] = true
			hook(st, g)
			if i > n - drawn then
				fresh[g] = (i - (n - drawn) - 1) * 0.15      -- บินเข้ามาทีละใบจากฝั่งกองเด็ค
				g.Position, g.Rotation = UDim2.fromScale(1.2, 0.1), 40
				UIKit.getScale(g).Scale = 0.3
			else
				local pos, rot, sc = targetFor(st, i, n)
				g.Position, g.Rotation = pos, rot
				UIKit.getScale(g).Scale = sc
			end
		end
	end
	if st.hover and not table.find(list, st.hover) then st.hover = nil end
	if st.held and not table.find(list, st.held) then st.held = nil end
	st.lastN = n
	updateCounter(st, n, drawn > 0)
	arrange(st, fresh)
end

function HandFan.SetHeld(container, view, on)
	local st = states[container]
	if not st then return end
	st.held = on and rootOf(view) or nil
	if on then st.hover = nil end
	arrange(st)
end

function HandFan.Reject(view)
	local g = rootOf(view)
	if not g then return end
	UIKit.shake(g, 10)
	UIKit.sfx("Honk", 0.1)
end

return HandFan]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/Inspect.lua"] = [[
-- แผงดูรายละเอียดการ์ด (ชี้เมาส์ หรือแตะ)
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local S = require(ReplicatedStorage:WaitForChild("Shared"):WaitForChild("UI"):WaitForChild("Style"))
local CardFace = require(script.Parent:WaitForChild("CardFace"))

local Inspect = {}
local panel, face, keywords, flavor

function Inspect.Init(parent)
	if panel then return end
	panel = S.new("TextButton", {
		Name = "Inspect", AutoButtonColor = false, Text = "", BackgroundColor3 = S.C.Panel,
		AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.42, 0),
		Size = UDim2.fromScale(0.2, 0.6), Visible = false, ZIndex = 40, Parent = parent,
	}, { S.corner(6), S.pad(10), S.new("UISizeConstraint", { MinSize = Vector2.new(170, 250), MaxSize = Vector2.new(300, 470) }) })
	S.stroke(S.C.Line, 1, panel)
	local holder = S.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 0.66), Parent = panel })
	face = CardFace.new(nil, {})
	face.Root.Active = false
	face.Root.Parent = holder
	keywords = S.text({ Font = S.Font.Bold, Color = S.C.Accent, Max = 13,
		Position = UDim2.fromScale(0, 0.69), Size = UDim2.fromScale(1, 0.08), Parent = panel })
	flavor = S.text({ Color = S.C.TextDim, Max = 12, YAlign = "Top",
		Position = UDim2.fromScale(0, 0.79), Size = UDim2.fromScale(1, 0.21), Parent = panel })
	panel.Activated:Connect(Inspect.Hide)
end

function Inspect.Show(card)
	if not panel or not card then return end
	face:Update(card)
	face:SetStatus("", false)
	keywords.Text = CardFace.KeywordText(card)
	flavor.Text = S.clean(card.Flavor or card.Desc or "")
	panel.Visible = true
end

function Inspect.Hide()
	if panel then panel.Visible = false end
end

return Inspect]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/LobbyUI.lua"] = [[
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Decks = require(Shared:WaitForChild("Decks"))
local DeckRules = require(Shared:WaitForChild("DeckRules"))
local CardData = require(Shared:WaitForChild("CardData"))
local S = require(Shared:WaitForChild("UI"):WaitForChild("Style"))
local Net = require(script.Parent:WaitForChild("Net"))
local CardFace = require(script.Parent:WaitForChild("CardFace"))
local Inspect = require(script.Parent:WaitForChild("Inspect"))
-- หน้าจอใหม่ (โหมดตัวอย่าง): โหลดแบบ pcall เพื่อไม่ให้ล็อบบี้พังถ้าไฟล์ใดมีปัญหา
local function tryRequire(name)
	local inst = script.Parent:FindFirstChild(name)
	if not inst then return nil end
	local ok, mod = pcall(require, inst)
	if not ok then warn("[LobbyUI] โหลด " .. name .. " ไม่ได้: " .. tostring(mod)) return nil end
	return mod
end
local BountyBoard = tryRequire("BountyBoard")
local TournamentBracket = tryRequire("TournamentBracket")
local FarmUI = tryRequire("FarmUI")
local TowerUI = tryRequire("TowerUI")
local DeckBuilder = tryRequire("DeckBuilder")

-- ฟาร์มจริง: เซิร์ฟเวอร์ส่งเวลาเป็น unix (os.time) ส่วน FarmUI ใช้ workspace:GetServerTimeNow() จึงต้องแปลงฐานเวลา
local function openFarm(overlay, wallet, onGems)
	local ok, farms, serverUnix = Net.invoke("GetFarms")
	if not ok then S.toast(Net.message(farms), "bad") return end
	local offset = workspace:GetServerTimeNow() - serverUnix
	local list = {}
	for i, f in farms do
		local c = table.clone(f)
		c.LastClaim = f.LastClaim + offset
		c.Color = ({ S.C.Good, S.C.Info, S.C.Pink })[(i - 1) % 3 + 1]
		list[i] = c
	end
	FarmUI.Open(overlay, { Farms = list, Wallet = wallet or 0, WalletEmoji = "💎",
		OnClaim = function(id)
			local okC, amount = Net.invoke("ClaimFarm", id)
			if okC and onGems then onGems() end
			return okC, okC and amount or Net.message(amount)
		end,
		OnUpgrade = function(id)
			local okU, nf = Net.invoke("UpgradeFarm", id)
			if not okU then return false, Net.message(nf) end
			nf.LastClaim = nf.LastClaim + offset
			if onGems then onGems() end
			return true, nf
		end })
end

local LobbyUI = {}

local TAB_COLOR = { Battle = S.C.Bad, Deck = S.C.Info, Gacha = S.C.Pink, Quests = S.C.Good, Stats = S.C.Violet, Fun = S.C.Teal }
local TABS = {
	{ Id = "Battle", Text = "ต่อสู้" }, { Id = "Deck", Text = "เด็ค" }, { Id = "Gacha", Text = "กาชา" },
	{ Id = "Quests", Text = "เควสต์" }, { Id = "Stats", Text = "สถิติ" }, { Id = "Fun", Text = "สนุก" },
}
-- สีประจำผู้นำ (เดิมทุกใบเป็นสีเทาเหมือนกันหมด)
local LEADER_STYLE = {
	LEADER_LUNG = { Color = S.C.Accent, Tag = "ลุง" },
	LEADER_PA = { Color = S.C.Pink, Tag = "ป้า" },
	LEADER_KID = { Color = S.C.Teal, Tag = "เด็ก" },
}
local STAT_NAMES = {
	Matches = "แมตช์ทั้งหมด", Wins = "ชนะ", Losses = "แพ้", Draws = "เสมอ", Surrenders = "ยอมแพ้",
	MatchesPvP = "แมตช์ PvP", MatchesBot = "แมตช์บอท", WinsPvP = "ชนะ PvP", WinsBot = "ชนะบอท",
	LossesPvP = "แพ้ PvP", LossesBot = "แพ้บอท", GemsEarned = "เพชรที่ได้รับ", BestGemsOneMatch = "เพชรสูงสุดต่อแมตช์",
	PlaySec = "เวลาเล่นรวม (วิ)", LongestMatchSec = "แมตช์ที่นานที่สุด (วิ)", ShortestWinSec = "ชนะเร็วที่สุด (วิ)",
	BountyEarned = "ค่าหัวที่ได้รับ",
}

function LobbyUI.Build(hud, overlay)
	Inspect.Init(overlay)
	local profile, stats = nil, nil
	local leaderIndex, queueMode, queueElapsed = 1, nil, 0
	local currentTab = "Battle"
	local panels = {}
	local statusLabel = nil

	-- ===== พื้นหลังทึบเต็มจอ =====
	local backdrop = S.new("Frame", { Name = "Backdrop", BackgroundColor3 = S.C.Bg, Size = UDim2.fromScale(1, 1), Parent = hud })
	S.new("Frame", { Name = "BandTop", BackgroundColor3 = S.C.Violet, BackgroundTransparency = 0.8,
		Size = UDim2.fromScale(1, 0.4), Parent = backdrop })
	S.new("Frame", { Name = "BandBottom", BackgroundColor3 = S.C.Pink, BackgroundTransparency = 0.88,
		AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.fromScale(1, 0.3), Parent = backdrop })

	-- ===== โครงหลัก: คอลัมน์แนวตั้ง [แถบบน | เนื้อหา(กินที่เหลือ)] =====
	local root = S.new("Frame", { Name = "LobbyRoot", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = backdrop }, {
		S.pad(12),
		S.new("UIListLayout", { Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder }),
	})

	local topBar = S.new("Frame", { Name = "TopBar", BackgroundColor3 = S.C.Panel, LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 46), Parent = root }, { S.corner(8), S.pad(6) })
	S.stroke(S.C.Violet, 1.5, topBar)
	S.text({ Font = S.Font.Heavy, Text = "GAWA CARDS", Color = S.C.Accent, Max = 26,
		Size = UDim2.new(0.5, 0, 1, 0), Parent = topBar })
	local gemBox = S.new("Frame", { BackgroundColor3 = S.C.Ink, AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5), Size = UDim2.new(0, 150, 1, 0), Parent = topBar }, { S.corner(6) })
	S.stroke(S.C.Accent, 1.5, gemBox)
	local gemLabel = S.text({ Font = S.Font.Bold, Color = S.C.Accent, Max = 18, XAlign = "Center", Parent = gemBox })

	-- แถวเนื้อหา: [เมนูซ้าย | แผงขวา(กินที่เหลือ)] เรียงแนวนอน
	local body = S.new("Frame", { Name = "Body", BackgroundTransparency = 1, LayoutOrder = 2,
		Size = UDim2.new(1, 0, 1, -56), Parent = root }, {
		S.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10),
			SortOrder = Enum.SortOrder.LayoutOrder }),
	})

	local menu = S.new("Frame", { Name = "Menu", BackgroundTransparency = 1, LayoutOrder = 1,
		Size = UDim2.new(0, 140, 1, 0), Parent = body }, {
		S.new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }),
	})

	local panel = S.new("Frame", { Name = "Panel", BackgroundColor3 = S.C.Panel, LayoutOrder = 2,
		Size = UDim2.new(1, -150, 1, 0), Parent = body }, { S.corner(8), S.pad(10) })
	S.stroke(S.C.Violet, 2, panel)

	-- ===== หน้า: Frame แนวตั้ง [หัวเรื่อง | เนื้อหา] =====
	local page = nil
	local function newPage(title)
		if page then page:Destroy() end
		page = S.new("Frame", { Name = "Page", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = panel }, {
			S.new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
		})
		S.header(page, title, TAB_COLOR[currentTab], 1)
		local content = S.new("Frame", { Name = "Content", BackgroundTransparency = 1, LayoutOrder = 2,
			Size = UDim2.new(1, 0, 1, -42), Parent = page })
		return content
	end

	local tabButtons = {}
	local function paintTabs()
		for id, btn in tabButtons do
			local on = id == currentTab
			S.setBase(btn, on and TAB_COLOR[id] or S.C.Panel2)
			btn.TextColor3 = on and S.C.Paper or S.C.TextDim
		end
	end

	local function open(id)
		currentTab = id
		paintTabs()
		if panels[id] then panels[id]() end
	end

	for i, tab in TABS do
		tabButtons[tab.Id] = S.button({ Text = tab.Text, Max = 16, Color = S.C.Panel2, LayoutOrder = i,
			Size = UDim2.new(1, 0, 0, 36), Parent = menu, OnClick = function() open(tab.Id) end })
	end

	local function refreshIfOpen(id)
		if currentTab == id then panels[id]() end
	end

	-- ===== 1) ต่อสู้ =====
	panels.Battle = function()
		local c = newPage("เลือกผู้นำและโหมดต่อสู้")
		S.new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = c })

		-- การ์ดผู้นำ 3 ใบ เรียงแนวนอน
		local row = S.new("Frame", { BackgroundTransparency = 1, LayoutOrder = 1, Size = UDim2.new(1, 0, 1, -(22 + 52 + 16)), Parent = c }, {
			S.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0.02, 0),
				HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center,
				SortOrder = Enum.SortOrder.LayoutOrder }),
		})
		for i, id in Decks.Leaders do
			local card = CardData[id] or {}
			local st = LEADER_STYLE[id] or { Color = S.C.Accent }
			local picked = i == leaderIndex
			local tile = S.new("TextButton", { AutoButtonColor = false, Text = "", LayoutOrder = i,
				BackgroundColor3 = picked and st.Color or S.C.Panel2, Size = UDim2.new(0.31, 0, 1, 0), Parent = row },
				{ S.corner(8), S.pad(6) })
			S.stroke(picked and S.C.Paper or st.Color, picked and 3 or 1.5, tile)
			-- เนื้อหาในการ์ดปรับตามความสูงจริง: เตี้ยก็เหลือแค่ชื่อ ไม่ให้ตัวหนังสือทับกัน
			local nameL = S.text({ Name = "Name", Font = S.Font.Heavy, Text = card.Name or id,
				Color = picked and S.C.Ink or S.C.Text, Max = 16, XAlign = "Center", Size = UDim2.fromScale(1, 1), Parent = tile })
			local descL = S.text({ Name = "Desc", Text = S.clean(card.Desc or ""),
				Color = picked and S.C.Ink or S.C.TextDim, Max = 12, XAlign = "Center", YAlign = "Top",
				Position = UDim2.fromScale(0, 0.36), Size = UDim2.fromScale(1, 0.46), Parent = tile })
			local hpL = S.text({ Name = "HP", Font = S.Font.Bold, Text = "HP " .. tostring(card.HP or Config.LEADER_HP),
				Color = picked and S.C.Ink or st.Color, Max = 14, XAlign = "Center",
				Position = UDim2.fromScale(0, 0.84), Size = UDim2.fromScale(1, 0.16), Parent = tile })
			local function layoutTile()
				local h = tile.AbsoluteSize.Y
				local roomy = h >= 110
				descL.Visible, hpL.Visible = roomy, roomy
				nameL.Size = roomy and UDim2.fromScale(1, 0.34) or UDim2.fromScale(1, 1)
			end
			tile:GetPropertyChangedSignal("AbsoluteSize"):Connect(layoutTile)
			task.defer(layoutTile)
			tile.Activated:Connect(function()
				if leaderIndex ~= i then leaderIndex = i; panels.Battle() end
			end)
		end

		-- สถานะ
		statusLabel = S.text({ Font = S.Font.Bold, LayoutOrder = 2, Max = 15, XAlign = "Center",
			Text = queueMode and ("กำลังค้นหาคู่แข่ง... " .. queueElapsed .. " วิ") or "พร้อมรบ",
			Color = queueMode and S.C.Accent or S.C.Teal, Size = UDim2.new(1, 0, 0, 22), Parent = c })

		-- ปุ่มโหมด
		local btns = S.new("Frame", { BackgroundTransparency = 1, LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 52), Parent = c }, {
			S.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0.03, 0),
				HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }),
		})
		S.button({ Text = queueMode and "ยกเลิกการจับคู่" or "จับคู่ PvP", Max = 18, LayoutOrder = 1,
			Color = queueMode and S.C.Bad or S.C.Good, TextColor = S.C.Paper, Size = UDim2.new(0.47, 0, 1, 0), Parent = btns,
			OnClick = function()
				if queueMode then
					Net.invoke("Queue", "Cancel")
					queueMode = nil
					panels.Battle()
				else
					local ok, res = Net.invoke("Queue", "PvP", Decks.Leaders[leaderIndex])
					if ok then queueMode, queueElapsed = "PvP", 0; panels.Battle()
					else S.toast(Net.message(res), "bad") end
				end
			end })
		S.button({ Text = "ซ้อมกับบอท", Max = 18, LayoutOrder = 2, Color = S.C.Violet, TextColor = S.C.Paper,
			Size = UDim2.new(0.47, 0, 1, 0), Parent = btns,
			OnClick = function()
				local ok, res = Net.invoke("Queue", "Bot", Decks.Leaders[leaderIndex])
				if not ok then S.toast(Net.message(res), "bad") end
			end })
	end

	-- ===== การ์ดเป็นตาราง =====
	local function cardGrid(parent, ids, order)
		local grid = S.scroll({ Parent = parent, LayoutOrder = order or 1, Size = UDim2.fromScale(1, 1),
			Layout = S.new("UIGridLayout", { CellSize = UDim2.fromOffset(78, 108), CellPadding = UDim2.fromOffset(8, 8),
				SortOrder = Enum.SortOrder.LayoutOrder }) })
		for i, id in ids do
			local c = CardData[id]
			if c then
				local v = CardFace.new(c, { Size = UDim2.fromScale(1, 1), NoAspect = true })
				v.Root.LayoutOrder = i
				v.Root.Parent = grid
				v.Root.MouseEnter:Connect(function() Inspect.Show(c) end)
				v.Root.MouseLeave:Connect(Inspect.Hide)
			end
		end
		return grid
	end

	-- ===== 2) เด็ค =====
	panels.Deck = function()
		local c = newPage(("เด็คของคุณ (%d ใบ)"):format(DeckRules.Size))
		S.new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = c })
		local holder = S.new("Frame", { BackgroundTransparency = 1, LayoutOrder = 1, Size = UDim2.new(1, 0, 1, -(DeckBuilder and 100 or 48)), Parent = c })
		cardGrid(holder, profile and profile.Deck or Decks.Starter)
		if DeckBuilder and profile then
			-- ตัวจัดเด็คใหม่ ใช้ SaveDeck เดิมของเซิร์ฟเวอร์ (คืนค่า ok, ข้อความ)
			S.button({ Text = "จัดเด็ค (แบบใหม่)", Max = 16, LayoutOrder = 2, Color = S.C.Pink, TextColor = S.C.Paper,
				Size = UDim2.new(1, 0, 0, 40), Parent = c, OnClick = function()
					DeckBuilder.Open(overlay, { Cards = CardData, Owned = profile.Collection, Deck = profile.Deck,
						Message = Net.message,
						OnSave = function(ids)
							local ok, err = Net.invoke("SaveDeck", ids)
							return ok, err
						end })
				end })
		end
		S.button({ Text = "บันทึกเด็ค", Max = 16, LayoutOrder = 3, Color = S.C.Info, TextColor = S.C.Paper,
			Size = UDim2.new(0.4, 0, 0, 38), Parent = c,
			OnClick = function()
				local ok, err = Net.invoke("SaveDeck", profile and profile.Deck or Decks.Starter)
				if ok then S.toast("บันทึกเด็คสำเร็จ", "good") else S.toast(Net.message(err), "bad") end
			end })
	end

	-- ===== 3) กาชา =====
	local lastPull = {}
	panels.Gacha = function()
		local c = newPage("สุ่มการ์ด")
		S.new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = c })
		S.text({ Text = ("ราคา %d เพชร ต่อครั้ง หรือ %d เพชร ต่อ 10 ครั้ง"):format(Config.GACHA_COST_1, Config.GACHA_COST_10),
			Color = S.C.TextDim, Max = 14, XAlign = "Center", LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 20), Parent = c })
		local holder = S.new("Frame", { BackgroundTransparency = 1, LayoutOrder = 2, Size = UDim2.new(1, 0, 1, -100), Parent = c })
		if #lastPull > 0 then cardGrid(holder, lastPull)
		else S.text({ Text = "กดปุ่มด้านล่างเพื่อสุ่มการ์ด", Color = S.C.TextDim, Max = 16, XAlign = "Center", Parent = holder }) end

		local function pull(n)
			local ok, res = Net.invoke("Gacha", n)
			if not ok then S.toast(Net.message(res), "bad") return end
			lastPull = {}
			for _, item in res do table.insert(lastPull, item.Id) end
			S.toast(n == 1 and "สุ่มสำเร็จ" or "สุ่ม 10 ครั้งสำเร็จ", "good")
			refreshIfOpen("Gacha")
		end
		local btns = S.new("Frame", { BackgroundTransparency = 1, LayoutOrder = 3, Size = UDim2.new(1, 0, 0, 46), Parent = c }, {
			S.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0.03, 0),
				HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }),
		})
		S.button({ Text = ("สุ่ม 1 ครั้ง (%d)"):format(Config.GACHA_COST_1), Max = 16, LayoutOrder = 1,
			Color = S.C.Pink, TextColor = S.C.Paper, Size = UDim2.new(0.47, 0, 1, 0), Parent = btns, OnClick = function() pull(1) end })
		S.button({ Text = ("สุ่ม 10 ครั้ง (%d)"):format(Config.GACHA_COST_10), Max = 16, LayoutOrder = 2,
			Color = S.C.Accent, TextColor = S.C.Ink, Size = UDim2.new(0.47, 0, 1, 0), Parent = btns, OnClick = function() pull(10) end })
	end

	-- ===== 4) เควสต์ =====
	panels.Quests = function()
		local c = newPage("เควสต์ประจำวัน")
		local list = S.scroll({ Parent = c, Size = UDim2.fromScale(1, 1), Gap = 8 })
		local quests = profile and profile.Quests and profile.Quests.List or {}
		if #quests == 0 then
			S.text({ Text = "กำลังโหลดเควสต์...", Color = S.C.TextDim, Max = 15, Size = UDim2.new(1, 0, 0, 30), Parent = list })
		end
		for i, q in quests do
			local done = q.Progress >= q.Goal
			local row = S.new("Frame", { BackgroundColor3 = S.C.Panel2, LayoutOrder = i, Size = UDim2.new(1, -8, 0, 62), Parent = list },
				{ S.corner(6), S.pad(8) })
			S.stroke(q.Claimed and S.C.Line or (done and S.C.Good or S.C.Violet), 1.5, row)
			S.text({ Font = S.Font.Bold, Text = q.Text, Max = 15, Size = UDim2.fromScale(0.62, 0.5), Parent = row })
			-- แถบความคืบหน้า
			local barBack = S.new("Frame", { BackgroundColor3 = S.C.Bg, Position = UDim2.fromScale(0, 0.62),
				Size = UDim2.fromScale(0.6, 0.26), Parent = row }, { S.corner(4) })
			S.new("Frame", { BackgroundColor3 = done and S.C.Good or S.C.Info,
				Size = UDim2.fromScale(math.clamp(q.Progress / q.Goal, 0, 1), 1), Parent = barBack }, { S.corner(4) })
			S.text({ Font = S.Font.Bold, Text = q.Progress .. "/" .. q.Goal, Max = 12, XAlign = "Center", ZIndex = 2, Parent = barBack })
			if q.Claimed then
				S.text({ Text = "รับแล้ว", Color = S.C.TextDim, Font = S.Font.Bold, Max = 14, XAlign = "Center",
					Position = UDim2.fromScale(0.66, 0), Size = UDim2.fromScale(0.34, 1), Parent = row })
			elseif done then
				S.button({ Text = "รับ " .. q.Reward .. " เพชร", Max = 14, Color = S.C.Good, TextColor = S.C.Paper,
					Position = UDim2.fromScale(0.66, 0.05), Size = UDim2.fromScale(0.34, 0.9), Parent = row,
					OnClick = function()
						local ok, res = Net.invoke("ClaimQuest", q.Id)
						if ok then S.toast("ได้รับ " .. res .. " เพชร", "good"); LobbyUI.Refresh()
						else S.toast(Net.message(res), "bad") end
					end })
			else
				S.text({ Text = q.Reward .. " เพชร", Color = S.C.Accent, Font = S.Font.Bold, Max = 15, XAlign = "Center",
					Position = UDim2.fromScale(0.66, 0), Size = UDim2.fromScale(0.34, 1), Parent = row })
			end
		end
	end

	-- ===== 5) สถิติ =====
	panels.Stats = function()
		local c = newPage("สถิติผู้เล่น")
		local list = S.scroll({ Parent = c, Size = UDim2.fromScale(1, 1), Gap = 5 })
		local st = stats
		if typeof(st) ~= "table" then
			S.text({ Text = "กำลังโหลดสถิติ...", Color = S.C.TextDim, Max = 15, Size = UDim2.new(1, 0, 0, 30), Parent = list })
			return
		end
		local keys = {}
		for k, v in st do
			if typeof(v) == "number" or typeof(v) == "string" then table.insert(keys, tostring(k)) end
		end
		table.sort(keys)
		for i, k in keys do
			local row = S.new("Frame", { BackgroundColor3 = (i % 2 == 0) and S.C.Panel2 or S.C.Bg, LayoutOrder = i,
				Size = UDim2.new(1, -8, 0, 30), Parent = list }, { S.corner(4), S.pad(5) })
			S.text({ Text = STAT_NAMES[k] or k, Max = 14, Size = UDim2.fromScale(0.62, 1), Parent = row })
			S.text({ Font = S.Font.Bold, Text = tostring(st[k]), Color = S.C.Accent, Max = 14, XAlign = "Right",
				Position = UDim2.fromScale(0.62, 0), Size = UDim2.fromScale(0.38, 1), Parent = row })
		end
	end

	-- ===== 6) สนุก: หน้าจอใหม่ (ตอนนี้เป็นข้อมูลตัวอย่าง ยังไม่ต่อเซิร์ฟเวอร์) =====
	panels.Fun = function()
		local c = newPage("โหมดสนุก (ตัวอย่าง)")
		local list = S.scroll({ Parent = c, Size = UDim2.fromScale(1, 1), Gap = 8 })
		local entries = {
			{ Text = "หอคอย", Color = S.C.Violet, Mod = TowerUI },
			{ Text = "ประกาศจับ (Bounty)", Color = S.C.Accent, Mod = BountyBoard },
			{ Text = "ทัวร์นาเมนต์", Color = S.C.Info, Mod = TournamentBracket },
			{ Text = "ฟาร์ม", Color = S.C.Good, Mod = FarmUI, Open = function() openFarm(overlay, profile and profile.Gems, LobbyUI.Refresh) end },
		}
		for i, e in entries do
			S.button({ Text = e.Text, Max = 18, Color = e.Color, LayoutOrder = i, Size = UDim2.new(1, -8, 0, 48), Parent = list,
				OnClick = function()
					if not e.Mod then S.toast("หน้านี้ยังโหลดไม่ได้", "bad") return end
					local ok, err = pcall(e.Open or function() return e.Mod.Open(overlay) end)
					if not ok then warn("[LobbyUI] เปิด " .. e.Text .. " ไม่ได้: " .. tostring(err)); S.toast("เปิดหน้านี้ไม่ได้", "bad") end
				end })
		end
	end

	-- ===== ข้อมูลโปรไฟล์ =====
	function LobbyUI.Refresh()
		local ok, res = pcall(function() return Net.invoke("GetProfile") end)
		if ok and typeof(res) == "table" then
			profile = res
			gemLabel.Text = (profile.Gems or 0) .. " เพชร"
		end
		local okS, st = pcall(function() return Net.invoke("GetStats") end)
		if okS and typeof(st) == "table" then stats = st end
		panels[currentTab]()
	end

	function LobbyUI.ResetQueue() queueMode = nil end

	Net.on("ProfileChanged", function(p)
		if typeof(p) ~= "table" then return end
		profile = p
		gemLabel.Text = (profile.Gems or 0) .. " เพชร"
		if currentTab == "Quests" or currentTab == "Deck" then panels[currentTab]() end
	end)

	-- นับเวลารอจับคู่
	task.spawn(function()
		while task.wait(1) do
			if queueMode then
				queueElapsed += 1
				if currentTab == "Battle" and statusLabel and statusLabel.Parent then
					statusLabel.Text = "กำลังค้นหาคู่แข่ง... " .. queueElapsed .. " วิ"
				end
			end
		end
	end)

	open("Battle")
	task.spawn(LobbyUI.Refresh)
end

return LobbyUI
]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/MatchBackdrop.lua"] = [[
-- StarterPlayerScripts/UIClient/MatchBackdrop (ModuleScript)
-- พื้นโต๊ะ + แผ่นรองสนาม + เส้นแบ่งกลาง + แสงบอกตา + ประกายลอย
local TweenService = game:GetService("TweenService")
local UIShared = game:GetService("ReplicatedStorage"):WaitForChild("Shared"):WaitForChild("UI")
local Theme = require(UIShared:WaitForChild("Theme"))
local Settings = require(UIShared:WaitForChild("Settings"))

local Backdrop = {}
Backdrop.__index = Backdrop

local function new(class, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(props) do o[k] = v end
	o.Parent = parent
	return o
end

local function fade(a, b)
	return NumberSequence.new({ NumberSequenceKeypoint.new(0, a), NumberSequenceKeypoint.new(1, b) })
end

function Backdrop.new(parent)
	local self = setmetatable({}, Backdrop)
	local root = new("Frame", { Name = "Backdrop", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 0 }, parent)
	new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.fromRGB(52, 132, 88), Color3.fromRGB(20, 56, 44)) }, root)
	self.Root = root

	local mat = new("Frame", {
		Name = "Mat", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.115),
		Size = UDim2.fromScale(0.66, 0.525), BackgroundColor3 = Color3.fromRGB(255, 245, 215), BackgroundTransparency = 0.85,
	}, root)
	new("UICorner", { CornerRadius = UDim.new(0.06, 0) }, mat)
	new("UIStroke", { Thickness = 3, Color = Color3.fromRGB(255, 240, 200), Transparency = 0.5 }, mat)

	self.Line = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.375),
		Size = UDim2.new(0.64, 0, 0, 4), BackgroundColor3 = Theme.Color.Yellow, BorderSizePixel = 0,
	}, root)
	new("UIGradient", { Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1),
	}) }, self.Line)

	self.MyGlow = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 1), Size = UDim2.fromScale(1, 0.4),
		BackgroundColor3 = Theme.Color.Yellow, BackgroundTransparency = 1, BorderSizePixel = 0,
	}, root)
	new("UIGradient", { Rotation = 90, Transparency = fade(1, 0.55) }, self.MyGlow)
	self.OppGlow = new("Frame", {
		Size = UDim2.fromScale(1, 0.3), BackgroundColor3 = Theme.Color.Red, BackgroundTransparency = 1, BorderSizePixel = 0,
	}, root)
	new("UIGradient", { Rotation = 90, Transparency = fade(0.6, 1) }, self.OppGlow)

	for _ = 1, 14 do task.spawn(self._sparkle, self) end
	return self
end

function Backdrop:_sparkle()
	local dot = new("Frame", { Size = UDim2.fromOffset(6, 6), BackgroundColor3 = Color3.fromRGB(255, 250, 200), BackgroundTransparency = 1, BorderSizePixel = 0 }, self.Root)
	new("UICorner", { CornerRadius = UDim.new(1, 0) }, dot)
	task.wait(math.random() * 8)
	while dot.Parent do
		if not Settings.Get("Effects") then dot.BackgroundTransparency = 1 task.wait(1) continue end
		local x = math.random()
		dot.Position = UDim2.fromScale(x, 1.02)
		dot.BackgroundTransparency = 0.3 + math.random() * 0.4
		local tw = TweenService:Create(dot, TweenInfo.new(7 + math.random() * 6, Enum.EasingStyle.Linear), {
			Position = UDim2.fromScale(x + (math.random() - 0.5) * 0.1, -0.02), BackgroundTransparency = 1,
		})
		tw:Play()
		tw.Completed:Wait()
	end
end

-- ตาเรา = ขอบล่างเรืองทอง / ตาศัตรู = ขอบบนเรืองแดง
function Backdrop:SetTurn(isMine)
	if self.Turn == isMine then return end
	self.Turn = isMine
	local ti = TweenInfo.new(0.5)
	TweenService:Create(self.MyGlow, ti, { BackgroundTransparency = isMine and 0 or 1 }):Play()
	TweenService:Create(self.OppGlow, ti, { BackgroundTransparency = isMine and 1 or 0 }):Play()
	TweenService:Create(self.Line, ti, { BackgroundColor3 = isMine and Theme.Color.Yellow or Theme.Color.Red }):Play()
end

return Backdrop]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/MatchHUD.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/MatchHUD.lua
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)
local Config = require(Shared.Config)
local okCD, CardData = pcall(require, Shared.CardData)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local PPT = Config.POINTS_PER_TURN or 5
local TURN_TIME = Config.TURN_TIME or 120
local FIELD_SLOTS = Config.FIELD_SLOTS or 3

local MatchHUD = {}
MatchHUD.__index = MatchHUD

local function now() return workspace:GetServerTimeNow() end

local function defOf(c)
	if type(c) == "table" then return c.Def or c end
	if okCD and type(CardData) == "table" then return CardData[c] end
	return nil
end


-- ชิ้นลอยแยกอิสระ: ขนาดอิงสัดส่วนจอ แต่มีพื้น/เพดานเป็น pixel เพื่อไม่ให้ถูกบีบเป็นแถบเมื่อ viewport เตี้ย
local function floatLimit(holder, minW, minH, maxW, maxH)
	UIKit.new("UISizeConstraint", { MinSize = Vector2.new(minW, minH), MaxSize = Vector2.new(maxW or 100000, maxH or 100000), Parent = holder })
end

---------------------------------------------------------------- HP
local function buildHP(self, side)
	local mine = side == "me"
	local holder, face = UIKit.comicBox({ Name = side .. "HP", Parent = self.root, Size = UDim2.fromScale(0.26, 0.07),
		Position = mine and UDim2.new(0, 16, 0, 44) or UDim2.new(1, -16, 0, 44),
		AnchorPoint = mine and Vector2.zero or Vector2.new(1, 0), Color = C.TableDark, Tilt = mine and -1.5 or 1.5, ZIndex = 20 })
	floatLimit(holder, 200, 38, 420, 64)
	local name = UIKit.label({ Text = mine and "เรา" or "ศัตรู", Color = mine and C.Lime or C.Pink, Size = UDim2.new(0.7, 0, 0, 26),
		Position = UDim2.new(mine and 0 or 1, 0, 0, -4), AnchorPoint = Vector2.new(mine and 0 or 1, 1),
		AlignX = mine and Enum.TextXAlignment.Left or Enum.TextXAlignment.Right, MaxTextSize = 24, ZIndex = 25, Parent = holder })
	local track = UIKit.new("Frame", { BackgroundColor3 = C.Ink, Size = UDim2.new(1, -14, 1, -14), Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = CENTER, ZIndex = 22, Parent = face }, { UIKit.corner(8) })
	local anchor, pos = Vector2.new(mine and 0 or 1, 0), UDim2.fromScale(mine and 0 or 1, 0)
	local lag = UIKit.new("Frame", { BackgroundColor3 = C.White, BorderSizePixel = 0, AnchorPoint = anchor, Position = pos,
		Size = UDim2.fromScale(1, 1), ZIndex = 23, Parent = track }, { UIKit.corner(8) })
	local fill = UIKit.new("Frame", { BackgroundColor3 = C.Green, BorderSizePixel = 0, AnchorPoint = anchor, Position = pos,
		Size = UDim2.fromScale(1, 1), ZIndex = 24, Parent = track }, {
		UIKit.corner(8), UIKit.new("UIGradient", { Rotation = 90, Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(170, 170, 170)) }) })
	local num = UIKit.label({ Text = "-", Size = UDim2.fromScale(0.9, 1.1), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		MaxTextSize = 30, ZIndex = 26, Parent = track })
	local shield, shieldLbl = UIKit.badge(holder, "🛡 0", C.Blue, { Size = UDim2.fromOffset(72, 30),
		Position = UDim2.new(mine and 1 or 0, mine and 8 or -8, 0.5, 0), AnchorPoint = Vector2.new(mine and 0 or 1, 0.5), ZIndex = 27 })
	shield.Visible = false
	self.hp[side] = { holder = holder, name = name, fill = fill, lag = lag, num = num, shield = shield, shieldLbl = shieldLbl,
		max = Config.LEADER_HP or 30, shieldVal = 0 }
end

function MatchHUD:SetHP(side, hp, shield, leaderName)
	local b = self.hp[side]
	if not b or hp == nil then return end
	if leaderName and leaderName ~= "" and b.name.Text ~= leaderName then UIKit.setText(b.name, leaderName) end
	b.max = math.max(b.max, hp)
	local ratio = math.clamp(hp / b.max, 0, 1)
	local old = b.hp
	b.hp = hp
	UIKit.tween(b.fill, 0.2, { Size = UDim2.fromScale(ratio, 1),
		BackgroundColor3 = ratio > 0.5 and C.Green or ratio > 0.25 and C.Yellow or C.Red })
	task.delay(UIKit.dur(0.35), function()
		if b.lag.Parent then UIKit.tween(b.lag, 0.5, { Size = UDim2.fromScale(ratio, 1) }) end
	end)
	if old and hp ~= old then
		UIKit.bounceText(b.num, hp, 0.4)
		if hp < old then
			UIKit.shake(b.holder, 10); UIKit.sfx("Hit", 0.2)
			UIKit.popup(b.holder, "-" .. (old - hp), C.Red)
		else
			UIKit.sfx("Heal", 0.1)
			UIKit.popup(b.holder, "+" .. (hp - old), C.Green)
		end
	else
		UIKit.setText(b.num, hp)
	end
	shield = shield or 0
	b.shield.Visible = shield > 0
	if shield ~= b.shieldVal then
		UIKit.bounceText(b.shieldLbl, "🛡 " .. shield, 0.3)
		b.shieldVal = shield
	end
end

---------------------------------------------------------------- Points
local OFF_CELL = Color3.fromRGB(50, 40, 80)

local function buildPoints(self)
	local holder, face = UIKit.comicBox({ Name = "Points", Parent = self.root, Size = UDim2.fromScale(0.2, 0.09),
		Position = UDim2.new(0, 16, 1, -16), AnchorPoint = Vector2.new(0, 1), Color = C.TableDark, Tilt = -2, ZIndex = 20 })
	floatLimit(holder, 190, 46, 340, 78)
	UIKit.label({ Text = "พลังกาว", Color = C.Lime, Size = UDim2.new(0.5, 0, 0, 24), Position = UDim2.new(0, 6, 0, -4),
		AnchorPoint = Vector2.new(0, 1), AlignX = Enum.TextXAlignment.Left, MaxTextSize = 22, ZIndex = 25, Parent = holder })
	local row = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(0.68, 0.6), Position = UDim2.fromScale(0.04, 0.5),
		AnchorPoint = Vector2.new(0, 0.5), ZIndex = 22, Parent = face }, {
		UIKit.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0.03, 0),
			VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder }) })
	self.cells = {}
	for i = 1, PPT do
		local cell = UIKit.new("Frame", { Name = "Cell", BackgroundColor3 = C.Lime, Size = UDim2.fromScale(0.94 / PPT - 0.03, 1),
			LayoutOrder = i, ZIndex = 23, Parent = row }, { UIKit.corner(UDim.new(0.4, 0)), UIKit.stroke(C.Outline, 2.5) })
		local g = UIKit.new("UIGradient", { Rotation = 90, Color = Theme.seq(C.White, Color3.fromRGB(200, 200, 200), Color3.fromRGB(140, 140, 140)), Parent = cell })
		self.cells[i] = { frame = cell, grad = g }
	end
	self.pointsNum = UIKit.label({ Text = tostring(PPT), Color = C.Yellow, Size = UDim2.fromScale(0.24, 0.9),
		Position = UDim2.fromScale(0.98, 0.5), AnchorPoint = Vector2.new(1, 0.5), MaxTextSize = 56, ZIndex = 24, Parent = face })
	self.bankBadge, self.bankLbl = UIKit.badge(holder, "+0", C.Pink, { Size = UDim2.fromOffset(84, 28),
		Position = UDim2.new(1, 6, 0, -4), AnchorPoint = Vector2.new(1, 0.5), Tilt = 6, MaxTextSize = 16, ZIndex = 27 })
	self.bankBadge.Visible = false
	self.pointsHolder = holder

	self.shieldHint = UIKit.badge(self.root, "🛡 มีโล่ฝาหม้อ! ลงได้ฟรี 0 พอยต์", C.Blue, {
		Size = UDim2.fromOffset(250, 28), Position = UDim2.new(0, 16, 1, -86), AnchorPoint = Vector2.new(0, 1), Tilt = -2, MaxTextSize = 16, ZIndex = 26 })
	self.shieldHint.Visible = false

	-- เกจกระเพื่อมเหมือนเยลลี่
	local t0 = os.clock()
	table.insert(self.conns, RunService.Heartbeat:Connect(function()
		if not UIKit.effectsOn() then return end
		local t = os.clock() - t0
		for i, c in ipairs(self.cells) do c.grad.Offset = Vector2.new(0, math.sin(t * 4 + i) * 0.15) end
	end))
end

function MatchHUD:SetPoints(points)
	points = points or 0
	local old = self.points
	self.points = points
	for i, c in ipairs(self.cells) do
		local on, was = i <= points, old == nil or i <= old
		c.frame.BackgroundColor3 = on and C.Lime or OFF_CELL
		if old and on ~= was then
			UIKit.jelly(c.frame, 0.4)
			if not on then FX.sparkles(self.pointsHolder, C.Lime, 4, Vector2.new(0.04 + (i - 0.5) / PPT * 0.68, 0.5)) end
		end
	end
	if old and old ~= points then UIKit.bounceText(self.pointsNum, points) else UIKit.setText(self.pointsNum, points) end
	local extra = points - PPT
	self.bankBadge.Visible = extra > 0
	if extra > 0 then UIKit.setText(self.bankLbl, "+" .. extra .. " สะสม") end
	self:_refreshSkip()
end

---------------------------------------------------------------- Skip
local function buildSkip(self, onSkip)
	self.skip, self.skipLabel = UIKit.button({ Name = "Skip", Parent = self.root, Text = "SKIP!", Color = C.Pink,
		Size = UDim2.fromScale(0.16, 0.1), Position = UDim2.new(1, -16, 1, -34), AnchorPoint = Vector2.new(1, 1),
		Tilt = 3, MaxTextSize = 48, Lip = 8, Debounce = 0.6, ZIndex = 30,
		OnClick = function() if onSkip then onSkip() end end })
	floatLimit(self.skip, 130, 48, 260, 84)
	self.skipHint = UIKit.label({ Text = "", Color = C.Yellow, Size = UDim2.new(1.2, 0, 0, 22), Position = UDim2.new(0.5, 0, 1, 6),
		AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 18, ZIndex = 31, Parent = self.skip })
end

function MatchHUD:_refreshSkip()
	local my = self.isMyTurn == true
	UIKit.setDisabled(self.skip, not my)
	if not my then UIKit.setText(self.skipHint, "รอศัตรูอยู่...") return end
	if not self.spent then
		-- ตรงกับ Match:EndTurn: banking = not spentThisTurn
		UIKit.setText(self.skipLabel, "เก็บพอยต์!")
		UIKit.setText(self.skipHint, "ยังไม่ได้ใช้พอยต์ = เก็บไว้เทิร์นหน้า")
		UIKit.setColor(self.skip, C.Blue)
	else
		UIKit.setText(self.skipLabel, "SKIP!")
		UIKit.setText(self.skipHint, "จบเทิร์น ไปเลย!")
		UIKit.setColor(self.skip, C.Pink)
	end
end

---------------------------------------------------------------- Timer
local function buildTimer(self)
	local holder = UIKit.new("Frame", { Name = "Timer", BackgroundTransparency = 1, Size = UDim2.fromOffset(72, 72),
		Position = UDim2.new(0.5, 0, 0, 40), AnchorPoint = Vector2.new(0.5, 0), ZIndex = 30, Parent = self.root },
		{ UIKit.new("UIAspectRatioConstraint", { AspectRatio = 1 }) })
	self.flames = FX.flames(holder, 29)
	UIKit.new("Frame", { Name = "Shadow", BackgroundColor3 = C.Shadow, Size = UDim2.fromScale(1, 1), Position = UDim2.fromOffset(5, 5),
		ZIndex = 30, Parent = holder }, { UIKit.corner(UDim.new(1, 0)) })
	-- CanvasGroup ตัดขอบตามมุมโค้ง ทรายจึงอยู่ในวงกลมพอดี
	local face = UIKit.new("CanvasGroup", { Name = "Face", BackgroundColor3 = C.TableDark, Size = UDim2.fromScale(1, 1), ZIndex = 31,
		Parent = holder }, { UIKit.corner(UDim.new(1, 0)) })
	local sand = UIKit.new("Frame", { BackgroundColor3 = C.Lime, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1), Size = UDim2.fromScale(1, 1), ZIndex = 32, Parent = face })
	UIKit.new("Frame", { Name = "Ring", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 33, Parent = holder },
		{ UIKit.corner(UDim.new(1, 0)), UIKit.stroke(C.Outline, 4) })
	self.timeLbl = UIKit.label({ Text = "2:00", Size = UDim2.fromScale(0.85, 0.5), Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = CENTER, MaxTextSize = 44, ZIndex = 34, Parent = holder })
	self.turnLbl = UIKit.label({ Text = "", Size = UDim2.new(2.6, 0, 0, 28), Position = UDim2.new(0.5, 0, 1, 8),
		AnchorPoint = Vector2.new(0.5, 0), MaxTextSize = 26, ZIndex = 34, Parent = holder })

	local lastSec
	table.insert(self.conns, RunService.Heartbeat:Connect(function()
		if not self.endsAt then return end
		local rem = math.max(0, self.endsAt - now())
		if rem > TURN_TIME + 5 then rem = TURN_TIME end -- กันกรณีเวลาฝั่งเซิร์ฟเวอร์ใช้ฐานเวลาคนละแบบ
		sand.Size = UDim2.fromScale(1, rem / TURN_TIME)
		local sec = math.ceil(rem)
		if sec == lastSec then return end
		lastSec = sec
		self.timeLbl.Text = string.format("%d:%02d", sec // 60, sec % 60)
		self.timeLbl.TextColor3 = sec <= 10 and C.Red or C.White
		sand.BackgroundColor3 = sec > 30 and C.Lime or sec > 10 and C.Orange or C.Red
		self.flames:SetIntensity(sec <= 30 and (31 - sec) / 25 or 0)
		if sec <= 10 and sec > 0 then
			UIKit.bounceText(self.timeLbl, nil, 0.3)
			UIKit.shake(holder, 4 + (10 - sec))
			UIKit.sfx(self.isMyTurn and "TickTock" or "Tick", 0.05)
		end
		-- พอยต์หมดแล้ว ให้ปุ่ม SKIP เด้งเรียกร้องความสนใจ
		if self.isMyTurn and (self.points or 0) == 0 and sec % 2 == 0 then UIKit.jelly(self.skip, 0.1) end
	end))
end

function MatchHUD:Banner(text, color)
	local holder, face = UIKit.comicBox({ Parent = self.root, Size = UDim2.fromScale(0.5, 0.12), Position = UDim2.fromScale(-0.3, 0.42),
		AnchorPoint = CENTER, Color = color, Tilt = -4, ShadowOffset = 8, ZIndex = 200 })
	UIKit.label({ Text = text, Size = UDim2.new(1, -24, 1, -12), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		MaxTextSize = 60, StrokeThickness = 4, ZIndex = 202, Parent = face })
	UIKit.sfx("Whoosh")
	UIKit.tween(holder, 0.35, { Position = UDim2.fromScale(0.5, 0.42) }, Enum.EasingStyle.Back)
	task.delay(UIKit.dur(1.1), function()
		if not holder.Parent then return end
		UIKit.tween(holder, 0.3, { Position = UDim2.fromScale(1.3, 0.42) }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		task.wait(UIKit.dur(0.32))
		holder:Destroy()
	end)
end

function MatchHUD:SetTurn(isMine, endsAt)
	local changed = self.isMyTurn ~= isMine
	self.isMyTurn, self.endsAt = isMine, endsAt
	if changed then
		self.turnLbl.TextColor3 = isMine and C.Lime or C.Pink
		UIKit.bounceText(self.turnLbl, isMine and "ตาเรา!!" or "ตาศัตรู...", 0.4)
		self:Banner(isMine and "ตาเรา!! ลุยยย" or "ตาศัตรู... หายใจลึกๆ", isMine and C.Lime or C.Pink)
	end
	self:_refreshSkip()
end

---------------------------------------------------------------- API หลัก
function MatchHUD.new(gui, cb)
	cb = cb or {}
	local self = setmetatable({ hp = {}, conns = {} }, MatchHUD)
	self.root = UIKit.new("Frame", { Name = "MatchHUD", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 20, Parent = gui })
	buildHP(self, "me")
	buildHP(self, "opp")
	buildPoints(self)
	buildSkip(self, cb.OnSkip)
	buildTimer(self)
	return self
end

function MatchHUD:Apply(s)
	self:SetHP("me", s.myHP, s.myShield, s.myLeader)
	self:SetHP("opp", s.oppHP, s.oppShield, s.oppLeader)
	self.spent = s.mySpent == true or (type(s.mySpent) == "number" and s.mySpent > 0)
	self:SetTurn(s.isMyTurn == true, s.turnEndsAt)
	self:SetPoints(s.myPoints)
	local hasShield = false
	for _, c in ipairs(s.myHand or {}) do
		local d = defOf(c)
		if d and (d.Cost or 1) == 0 and type(d.Effect) == "table" and d.Effect.Kind == "Shield" then hasShield = true break end
	end
	self.shieldHint.Visible = hasShield and s.isMyTurn == true
end

-- วงซัมมอนรูปวงรีใต้ช่องสนาม (ใต้ตาข่าย) ZIndex 0 เพื่อให้อยู่หลังการ์ดเสมอ
function MatchHUD.decorateSlot(slot, mine)
	return FX.summonCircle(slot, { Size = UDim2.fromScale(1.3, 0.5), Position = UDim2.fromScale(0.5, 0.9),
		Color = mine and C.Pink or C.Blue, ZIndex = 0 })
end

local function keyOf(u)
	if type(u) ~= "table" then return u end
	return u.Uid or u.uid or u.InstanceId or u.Id
end

-- เทียบสนามก่อนกับหลัง: ลงตัวละครใหม่ = ระเบิดสีชมพู, ใส่อาวุธ = ระเบิดสีส้ม
function MatchHUD.diffField(prev, cur, circles)
	prev, cur = prev or {}, cur or {}
	for i = 1, FIELD_SLOTS do
		local a, b, circle = prev[i], cur[i], circles[i]
		if circle then
			if b and keyOf(a) ~= keyOf(b) then
				circle:Burst(Theme.TypeColor.Character)
			elseif type(a) == "table" and type(b) == "table" and b.Weapon and keyOf(a.Weapon) ~= keyOf(b.Weapon) then
				circle:Burst(Theme.TypeColor.Weapon)
			end
			circle:SetActive(b ~= nil and b ~= false)
		end
	end
end

function MatchHUD:Destroy()
	for _, c in ipairs(self.conns) do c:Disconnect() end
	self.root:Destroy()
end

return MatchHUD]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/MatchUI.lua"] = [[
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Shared = ReplicatedStorage:WaitForChild("Shared")
local Config = require(Shared:WaitForChild("Config"))
local Rules = require(Shared:WaitForChild("Rules"))
local S = require(Shared:WaitForChild("UI"):WaitForChild("Style"))
local Net = require(script.Parent:WaitForChild("Net"))
local CardFace = require(script.Parent:WaitForChild("CardFace"))
local Drag = require(script.Parent:WaitForChild("DragController"))
local Inspect = require(script.Parent:WaitForChild("Inspect"))

-- โมดูลหน้าตาใหม่ โหลดแบบ pcall: ถ้าไฟล์ใดพัง แมตช์ยังเล่นได้ด้วย UI เดิม
local function tryRequire(name)
	local inst = script.Parent:FindFirstChild(name)
	if not inst then return nil end
	local ok, mod = pcall(require, inst)
	if not ok then warn("[MatchUI] โหลด " .. name .. " ไม่ได้: " .. tostring(mod)) return nil end
	return mod
end
local MatchHUD = tryRequire("MatchHUD")
local HandFan = tryRequire("HandFan")
local GateRoller = tryRequire("GateRoller")

local OUTCOME = { Golden = "ทองคำ", Pumped = "พลังพุ่ง", Normal = "ปกติ", Droopy = "ห่อเหี่ยว", Poop = "ซวย" }

local function reasonText(reason, won)
	if reason == "LEADER_DOWN" then return won and "ผู้นำคู่แข่งล้ม" or "ผู้นำของคุณล้ม" end
	if reason == "SURRENDER" then return won and "คู่แข่งยอมแพ้" or "คุณยอมแพ้" end
	if reason == "LEFT" then return "คู่แข่งออกจากเกม" end
	if reason == "FATIGUE" then return "การ์ดในกองหมด" end
	if reason == "AFK_LIGHTNING" then return won and "คู่แข่งไม่เล่นหลายเทิร์น" or "คุณไม่ได้เล่นหลายเทิร์น" end
	return tostring(reason or "")
end

local MatchUI = {}

function MatchUI.Build(gui, overlay, cb)
	cb = cb or {}
	Inspect.Init(overlay)

	local ui = {}
	local state, matchId = nil, nil
	local ended = false
	local views = { hand = {}, myField = {}, oppField = {}, myGate = {} }
	local activeTargets = nil
	local applyGlows, endTurn, exitMatch

	local root = S.new("Frame", { Name = "MatchRoot", BackgroundColor3 = S.C.Felt,
		Size = UDim2.fromScale(1, 1), Visible = false, Parent = gui }, { S.pad(10) })

	local function glowStroke(parent)
		local s = S.stroke(S.C.Info, 2, parent)
		s.Name = "Glow"
		s.Transparency = 1
		return s
	end

	ui.board = S.new("Frame", { Name = "BoardZone", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 0.75), Parent = root })
	ui.boardGlow = glowStroke(ui.board)

	local function band(name, y, h)
		return S.new("Frame", { Name = name, BackgroundTransparency = 1,
			Position = UDim2.fromScale(0, y), Size = UDim2.fromScale(1, h), Parent = root })
	end
	local oppBarF = band("OppBar", 0, 0.08)
	local oppBoardF = band("OppBoard", 0.09, 0.25)
	local midF = band("Mid", 0.35, 0.05)
	local myBoardF = band("MyBoard", 0.41, 0.25)
	local myBarF = band("MyBar", 0.67, 0.08)
	local handF = band("Hand", 0.76, 0.24)

	local function leaderBar(parent, width)
		local bar = S.new("Frame", { BackgroundColor3 = S.C.FeltDark, Size = UDim2.fromScale(width, 1), Parent = parent }, { S.corner(4) })
		local glow = glowStroke(bar)
		local name = S.text({ Font = S.Font.Bold, Max = 18, Position = UDim2.fromScale(0.02, 0.1), Size = UDim2.fromScale(0.32, 0.8), Parent = bar })
		local hpBack = S.new("Frame", { BackgroundColor3 = S.C.Bg, Position = UDim2.fromScale(0.36, 0.22),
			Size = UDim2.fromScale(0.3, 0.56), Parent = bar }, { S.corner(3) })
		local hpFill = S.new("Frame", { BackgroundColor3 = S.C.Bad, Size = UDim2.fromScale(1, 1), Parent = hpBack }, { S.corner(3) })
		local hpText = S.text({ Font = S.Font.Bold, Max = 14, XAlign = "Center", ZIndex = 2, Parent = hpBack })
		local shield = S.text({ Font = S.Font.Medium, Max = 14, Color = S.C.Info, XAlign = "Center",
			Position = UDim2.fromScale(0.67, 0.1), Size = UDim2.fromScale(0.1, 0.8), Parent = bar })
		local info = S.text({ Max = 13, Color = S.C.TextDim, XAlign = "Right",
			Position = UDim2.fromScale(0.78, 0.1), Size = UDim2.fromScale(0.2, 0.8), Parent = bar })
		return { Frame = bar, Glow = glow, Name = name, HpFill = hpFill, HpText = hpText, Shield = shield, Info = info }
	end

	local function addSlot(row)
		local i = #row.Slots + 1
		local slot = S.new("Frame", { Name = "Slot" .. i, BackgroundColor3 = S.C.FeltDark, BackgroundTransparency = 0.35,
			Size = UDim2.fromScale(0.3, 0.96), LayoutOrder = i, Parent = row.Field }, {
			S.corner(5),
			S.new("UIAspectRatioConstraint", { AspectRatio = CardFace.ASPECT,
				AspectType = Enum.AspectType.FitWithinMaxSize, DominantAxis = Enum.DominantAxis.Height }),
		})
		S.stroke(S.C.Line, 1, slot)
		S.text({ Name = "Empty", Text = "ว่าง", Color = S.C.Line, Max = 14, XAlign = "Center", Parent = slot })
		row.Slots[i] = slot
	end

	local function boardRow(parent)
		local row = { Slots = {} }
		row.Gate = S.new("Frame", { BackgroundColor3 = S.C.FeltDark, Size = UDim2.fromScale(0.13, 1), Parent = parent }, { S.corner(4) })
		row.GateGlow = glowStroke(row.Gate)
		S.text({ Text = "เกต", Font = S.Font.Bold, Color = S.C.TextDim, Max = 13, XAlign = "Center",
			Size = UDim2.fromScale(1, 0.13), Parent = row.Gate })
		row.GateSlot = S.new("Frame", { BackgroundTransparency = 1, Position = UDim2.fromScale(0.08, 0.15),
			Size = UDim2.fromScale(0.84, 0.82), Parent = row.Gate })
		row.Field = S.new("Frame", { BackgroundTransparency = 1, Position = UDim2.fromScale(0.15, 0),
			Size = UDim2.fromScale(0.7, 1), Parent = parent }, {
			S.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
				HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center,
				Padding = UDim.new(0.025, 0), SortOrder = Enum.SortOrder.LayoutOrder }),
		})
		row.FieldGlow = glowStroke(row.Field)
		row.Info = S.text({ Max = 13, Color = S.C.TextDim, XAlign = "Center",
			Position = UDim2.fromScale(0.87, 0), Size = UDim2.fromScale(0.13, 1), Parent = parent })
		for _ = 1, Config.FIELD_SLOTS do addSlot(row) end
		return row
	end

	ui.opp = leaderBar(oppBarF, 1)
	ui.oppRow = boardRow(oppBoardF)
	ui.oppRow.FaceDown = S.new("Frame", { BackgroundColor3 = S.C.Panel2, Size = UDim2.fromScale(1, 1),
		AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Visible = false, Parent = ui.oppRow.GateSlot }, {
		S.corner(5), S.new("UIAspectRatioConstraint", { AspectRatio = CardFace.ASPECT }),
	})
	S.text({ Text = "คว่ำ", Color = S.C.TextDim, Max = 13, XAlign = "Center", Parent = ui.oppRow.FaceDown })
	ui.myRow = boardRow(myBoardF)
	ui.me = leaderBar(myBarF, 0.6)

	ui.turn = S.text({ Font = S.Font.Heavy, Max = 20, Size = UDim2.fromScale(0.2, 1), Parent = midF })
	local timerBack = S.new("Frame", { BackgroundColor3 = S.C.FeltDark, Position = UDim2.fromScale(0.22, 0.3),
		Size = UDim2.fromScale(0.36, 0.4), Parent = midF }, { S.corner(3) })
	ui.timerFill = S.new("Frame", { BackgroundColor3 = S.C.Accent, Size = UDim2.fromScale(1, 1), Parent = timerBack }, { S.corner(3) })
	ui.timerText = S.text({ Font = S.Font.Bold, Max = 16, Position = UDim2.fromScale(0.59, 0), Size = UDim2.fromScale(0.07, 1), Parent = midF })
	ui.log = S.text({ Color = S.C.TextDim, Max = 14, Position = UDim2.fromScale(0.67, 0), Size = UDim2.fromScale(0.21, 1), Parent = midF })
	
	local surrenderArmed = 0
	ui.surrender = S.button({ Text = "ยอมแพ้", Max = 13, Color = S.C.Panel, Position = UDim2.fromScale(0.89, 0.08),
		Size = UDim2.fromScale(0.11, 0.84), Parent = midF, OnClick = function(btn)
			if os.clock() - surrenderArmed < 3 then
				surrenderArmed = 0
				btn.Text = "ยอมแพ้"
				Net.fire("Surrender")
			else
				surrenderArmed = os.clock()
				btn.Text = "ยืนยัน?"
				task.delay(3, function()
					if os.clock() - surrenderArmed >= 2.9 then btn.Text = "ยอมแพ้" end
				end)
			end
		end })

	local pts = S.new("Frame", { BackgroundColor3 = S.C.FeltDark, Position = UDim2.fromScale(0.615, 0),
		Size = UDim2.fromScale(0.165, 1), Parent = myBarF }, { S.corner(4) })
	S.text({ Text = "แต้ม", Color = S.C.TextDim, Max = 12, XAlign = "Center", Size = UDim2.fromScale(1, 0.38), Parent = pts })
	ui.points = S.text({ Font = S.Font.Heavy, Color = S.C.Accent, Max = 24, XAlign = "Center",
		Position = UDim2.fromScale(0, 0.36), Size = UDim2.fromScale(1, 0.6), Parent = pts })
	ui.endBtn = S.button({ Text = "จบเทิร์น", Max = 20, Color = S.C.Accent, TextColor = S.C.Ink,
		Position = UDim2.fromScale(0.795, 0), Size = UDim2.fromScale(0.205, 1), Parent = myBarF,
		Debounce = 0.6, OnClick = function() endTurn() end })

	if HandFan then
		-- พัดการ์ด: จัดตำแหน่งเอง ห้ามมี UIListLayout (จะแย่งกันจัด)
		ui.hand = HandFan.Container(handF, UDim2.fromScale(0, 0), UDim2.fromScale(1, 1))
	else
		ui.hand = S.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = handF }, {
			S.new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal,
				HorizontalAlignment = Enum.HorizontalAlignment.Center, VerticalAlignment = Enum.VerticalAlignment.Center,
				Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder }),
		})
	end

	-- HUD ใหม่ (HP / พลังกาว / SKIP / นาฬิกา) ทับของเดิม: ซ่อนของเดิมไม่ให้ขึ้นซ้อนกัน 2 ชุด
	-- สร้างใหม่ทุกแมตช์ และทำลายตอนจบ (วงซัมมอนอยู่ในช่องสนาม ต้องลบเองด้วย ไม่งั้นแมตช์ถัดไปจะซ้อนกัน)
	local hud, myCircles, oppCircles, prevState = nil, {}, {}, nil
	local oldHud = { ui.endBtn, pts, ui.turn, timerBack, ui.timerText, ui.me.HpFill.Parent, ui.me.Shield, ui.opp.HpFill.Parent, ui.opp.Shield }

	local function teardownHud()
		for _, c in myCircles do pcall(c.Destroy, c) end
		for _, c in oppCircles do pcall(c.Destroy, c) end
		myCircles, oppCircles, prevState = {}, {}, nil
		if hud then pcall(hud.Destroy, hud); hud = nil end
		for _, g in oldHud do g.Visible = true end -- ถ้า HUD ใหม่หาย ของเดิมต้องกลับมา
	end

	local function buildHud()
		if not MatchHUD or hud then return end
		local okHud, res = pcall(MatchHUD.new, root, { OnSkip = function() endTurn() end })
		if not okHud then
			warn("[MatchUI] MatchHUD.new ล้มเหลว ใช้ UI เดิมแทน: " .. tostring(res))
			return
		end
		hud = res
		for i, slot in ipairs(ui.myRow.Slots) do myCircles[i] = MatchHUD.decorateSlot(slot, true) end
		for i, slot in ipairs(ui.oppRow.Slots) do oppCircles[i] = MatchHUD.decorateSlot(slot, false) end
		for _, g in oldHud do g.Visible = false end
	end

	local result = S.new("Frame", { Name = "MatchResult", BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.35,
		Size = UDim2.fromScale(1, 1), Visible = false, Active = true, ZIndex = 30, Parent = overlay })
	local rbox = S.new("Frame", { BackgroundColor3 = S.C.Panel, AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.34, 0.36), ZIndex = 31, Parent = result }, {
		S.corner(6), S.new("UISizeConstraint", { MinSize = Vector2.new(280, 200), MaxSize = Vector2.new(460, 300) }),
	})
	S.stroke(S.C.Line, 1, rbox)
	ui.resTitle = S.text({ Font = S.Font.Heavy, Max = 40, XAlign = "Center", Position = UDim2.fromScale(0.05, 0.08),
		Size = UDim2.fromScale(0.9, 0.28), ZIndex = 32, Parent = rbox })
	ui.resReason = S.text({ Color = S.C.TextDim, Max = 16, XAlign = "Center", Position = UDim2.fromScale(0.05, 0.38),
		Size = UDim2.fromScale(0.9, 0.14), ZIndex = 32, Parent = rbox })
	ui.resReward = S.text({ Font = S.Font.Bold, Color = S.C.Accent, Max = 20, XAlign = "Center",
		Position = UDim2.fromScale(0.05, 0.53), Size = UDim2.fromScale(0.9, 0.14), ZIndex = 32, Parent = rbox })
	S.button({ Text = "กลับล็อบบี้", Color = S.C.Accent, TextColor = S.C.Ink, AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0.74), Size = UDim2.fromScale(0.5, 0.17), ZIndex = 32, Parent = rbox,
		OnClick = function() exitMatch() end })

	local function setZoneGlow(stroke, mode)
		if not mode then stroke.Transparency = 1 return end
		stroke.Transparency = 0
		stroke.Color = mode == "hover" and S.C.Accent or S.C.Info
		stroke.Thickness = mode == "hover" and 3 or 2
	end

	local function markTargets(hover)
		for _, t in activeTargets or {} do
			local mode = t == hover and "hover" or "target"
			if t.View then t.View:SetGlow(mode) elseif t.Glow then setZoneGlow(t.Glow, mode) end
		end
	end

	local function clearTargets()
		for _, t in activeTargets or {} do
			if t.Glow then setZoneGlow(t.Glow, nil) end
		end
		activeTargets = nil
		applyGlows()
	end

	local function addChars(t, list, map)
		for _, c in list or {} do
			local v = map[c.Uid]
			if v then table.insert(t, { Gui = v.Root, View = v, Value = c.Uid }) end
		end
	end

	local function playTargets(card)
		local t = {}
		if card.Type == "Character" then
			if #state.myField < Config.FIELD_SLOTS then
				table.insert(t, { Gui = ui.myRow.Field, Glow = ui.myRow.FieldGlow, Value = "Field" })
			end
			if not state.myGate then
				table.insert(t, { Gui = ui.myRow.Gate, Glow = ui.myRow.GateGlow, Value = "Gate" })
			end
		elseif card.Type == "Weapon" then
			addChars(t, state.myField, views.myField)
			addChars(t, state.oppField, views.oppField)
			table.insert(t, { Gui = ui.opp.Frame, Glow = ui.opp.Glow, Value = "LEADER" })
		else
			local kind = Rules.TargetType(card)
			if kind == "EnemyChar" then
				addChars(t, state.oppField, views.oppField)
			elseif kind == "AllyChar" then
				addChars(t, state.myField, views.myField)
			elseif kind == "Ally" then
				addChars(t, state.myField, views.myField)
				table.insert(t, { Gui = ui.me.Frame, Glow = ui.me.Glow, Value = "MY_LEADER" })
			else
				table.insert(t, { Gui = ui.board, Glow = ui.boardGlow })
			end
		end
		return t
	end

	local function attackTargets()
		local t = {}
		local taunt = Rules.HasTaunt(state.oppField)
		if taunt then
			for _, c in state.oppField do
				if Rules.HasKeyword(c, "Taunt") then
					local v = views.oppField[c.Uid]
					if v then table.insert(t, { Gui = v.Root, View = v, Value = c.Uid }) end
				end
			end
		else
			addChars(t, state.oppField, views.oppField)
			table.insert(t, { Gui = ui.opp.Frame, Glow = ui.opp.Glow, Value = "LEADER" })
		end
		return t
	end

	applyGlows = function()
		if not state or not state.isMyTurn then
			for _, v in views.hand do v:SetGlow("none") end
			for _, v in views.myField do v:SetGlow("none") end
			return
		end
		local pts = state.myPoints or 0
		for _, c in state.myHand do
			local v = views.hand[c.Uid]
			if v then
				local afford = (c.Cost or 0) <= pts
				v:SetGlow(afford and "playable" or "none")
				v:SetCostWarning(not afford)
			end
		end
		for _, c in state.myField do
			local v = views.myField[c.Uid]
			if v then
				v:SetGlow(c.CanAttack and "ready" or "none")
			end
		end
	end

	function endTurn()
		if not state or not state.isMyTurn or ended then return end
		Net.fire("EndTurn")
	end

	exitMatch = function()
		teardownHud()
		result.Visible = false
		root.Visible = false
		ended = false
		state = nil
		matchId = nil -- ไม่งั้นแมตช์ถัดไปจะถูกเมินเพราะ matchId ไม่ตรง
		if cb.OnExit then cb.OnExit() end
	end

	-- ผูกปุ่มการ์ดในมือ (รองรับทั้งแตะเพื่อดู และลากเพื่อเล่น)
	local function bindHand(faceCard, card)
		faceCard.Root.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
			if not state or not state.isMyTurn or ended then
				if input.UserInputType == Enum.UserInputType.MouseButton1 then Inspect.Show(card) end
				return
			end
			Drag.Begin(input, {
				Source = card.Uid,
				CanStart = function()
					if (card.Cost or 0) > (state.myPoints or 0) then
						if HandFan then HandFan.Reject(faceCard) end -- แต้มไม่พอ: การ์ดสั่นให้รู้
						return false
					end
					if HandFan then HandFan.SetHeld(ui.hand, faceCard, true) end -- ใบที่ลากยุบลงจากพัด
					return true
				end,
				Ghost = function()
					local g = CardFace.new(card, { Size = UDim2.fromOffset(88, 122) })
					g.Root.ZIndex = 50
					return g.Root
				end,
				Targets = function()
					activeTargets = playTargets(card)
					markTargets(nil)
					return activeTargets
				end,
				OnHover = markTargets,
				OnEnd = function()
					if HandFan then HandFan.SetHeld(ui.hand, faceCard, false) end
					clearTargets()
				end,
				OnDrop = function(target)
					if not target then return end
					local val = target.Value
					local ok, err = Net.invoke("PlayCard", card.Uid, val) -- val: Field/Gate/LEADER/MY_LEADER/Uid หรือ nil (เวทไม่ต้องเลือกเป้า)
					if not ok then S.toast(Net.message(err), "bad") end
				end,
				OnTap = function() Inspect.Show(card) end,
			})
		end)
	end

	-- ผูกปุ่มตัวละครในสนาม (ลากเพื่อโจมตี)
	local function bindField(faceCard, card)
		faceCard.Root.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
			if not state or not state.isMyTurn or ended or not card.CanAttack then
				if input.UserInputType == Enum.UserInputType.MouseButton1 then Inspect.Show(card) end
				return
			end
			Drag.Begin(input, {
				Source = card.Uid,
				Arrow = true,
				CanStart = function() return card.CanAttack == true end,
				Targets = function()
					activeTargets = attackTargets()
					markTargets(nil)
					return activeTargets
				end,
				OnHover = markTargets,
				OnEnd = clearTargets,
				OnDrop = function(target)
					if not target then return end
					local ok, err = Net.invoke("Attack", card.Uid, target.Value)
					if not ok then S.toast(Net.message(err), "bad") end
				end,
				OnTap = function() Inspect.Show(card) end,
			})
		end)
	end

	local function syncZone(container, list, viewMap, isHand)
		local alive = {}
		for _, c in list or {} do
			local uid = c.Uid
			alive[uid] = true
			local v = viewMap[uid]
			if not v then
				v = CardFace.new(c, {})
				v.Root.Parent = container
				if isHand then bindHand(v, c) else bindField(v, c) end
				if not (isHand and HandFan) then v:PopIn() end -- พัดการ์ดมีอนิเมชันบินเข้ามาเอง
				viewMap[uid] = v
			else
				v:Update(c)
			end
		end
		for uid, v in viewMap do
			if not alive[uid] then
				v:Destroy()
				viewMap[uid] = nil
			end
		end
	end

	local function render(s)
		state = s
		local isNewMatch = matchId == nil
		matchId = s.matchId
		root.Visible = true
		-- เรียกทุกครั้งที่เริ่มแมตช์ใหม่ (เดิมตั้ง cb.OnStart = nil ทำให้แมตช์ที่ 2 ไม่ซ่อนล็อบบี้)
		if isNewMatch and cb.OnStart then cb.OnStart() end
		if isNewMatch then buildHud() end

		ui.turn.Text = if s.isMyTurn then "เทิร์นของคุณ" else "ตาคู่แข่ง"
		ui.turn.TextColor3 = s.isMyTurn and S.C.Accent or S.C.TextDim
		ui.points.Text = tostring(s.myPoints or 0)
		ui.endBtn:SetAttribute("Disabled", not s.isMyTurn)

		ui.me.Name.Text = s.myLeader
		ui.me.HpText.Text = tostring(s.myHP)
		ui.me.HpFill.Size = UDim2.fromScale(math.clamp(s.myHP / Config.LEADER_HP, 0, 1), 1)
		ui.me.Shield.Text = (s.myShield and s.myShield > 0) and ("โล่ " .. s.myShield) or ""
		ui.me.Info.Text = ("กอง %d | สุสาน %d"):format(s.myDeck, s.myGrave)

		ui.opp.Name.Text = s.oppLeader
		ui.opp.HpText.Text = tostring(s.oppHP)
		ui.opp.HpFill.Size = UDim2.fromScale(math.clamp(s.oppHP / Config.LEADER_HP, 0, 1), 1)
		ui.opp.Shield.Text = (s.oppShield and s.oppShield > 0) and ("โล่ " .. s.oppShield) or ""
		ui.opp.Info.Text = ("มือ %d | กอง %d"):format(s.oppHandCount, s.oppDeck)

		syncZone(ui.hand, s.myHand, views.hand, true)
		syncZone(ui.myRow.Field, s.myField, views.myField, false)
		syncZone(ui.oppRow.Field, s.oppField, views.oppField, false)

		if HandFan then
			-- เรียงตามลำดับในมือที่เซิร์ฟเวอร์ส่งมา
			local ordered = {}
			for _, c in ipairs(s.myHand or {}) do
				local v = views.hand[c.Uid]
				if v then table.insert(ordered, v) end
			end
			HandFan.Layout(ui.hand, ordered)
		end
		if hud then
			local okA, errA = pcall(function()
				hud:Apply(s)
				if prevState then
					MatchHUD.diffField(prevState.myField, s.myField, myCircles)
					MatchHUD.diffField(prevState.oppField, s.oppField, oppCircles)
				end
			end)
			if not okA then warn("[MatchUI] HUD: " .. tostring(errA)) end
		end
		prevState = s

		-- ช่องเกต
		ui.myRow.GateSlot:ClearAllChildren()
		views.myGate = nil
		if s.myGate then
			local v = CardFace.new(s.myGate, {})
			v.Root.Parent = ui.myRow.GateSlot
			views.myGate = v
		end
		ui.oppRow.FaceDown.Visible = s.oppGateFilled

		applyGlows()
	end

	Net.on("StateUpdate", function(s)
		if ended then return end -- StateUpdate ที่ถูก defer อาจมาหลัง MatchEnded: ห้ามวาดทับหน้าผลลัพธ์
		if typeof(s) ~= "table" then return end
		-- แมตช์ใหม่: matchId ยังเป็น nil (หลัง exitMatch) ให้รับ id แรกที่เข้ามา
		if matchId ~= nil and s.matchId ~= matchId then return end
		render(s)
	end)

	Net.on("GateRolled", function(mine, card, outcome)
		local name = S.clean(card and card.Name or "?")
		local outName = OUTCOME[outcome] or outcome
		S.toast(("เกต: %s ออกผล [%s]"):format(name, outName), mine and "good" or "info")
		if GateRoller then GateRoller.Play(overlay, card, outcome, mine) end
	end)

	Net.on("MatchEnded", function(won, reason, id, reward)
		if id ~= matchId and matchId ~= nil then return end
		ended = true
		teardownHud()
		ui.resTitle.Text = won and "ชนะแล้ว!" or "แพ้แล้ว!"
		ui.resTitle.TextColor3 = won and S.C.Good or S.C.Bad
		ui.resReason.Text = reasonText(reason, won)
		ui.resReward.Text = reward and reward > 0 and ("ได้รับ +" .. reward .. " เพชร") or ""
		result.Visible = true
	end)

	Net.on("Notify", function(text, color)
		S.toast(text, color == "Red" and "bad" or (color == "Green" and "good" or "info"))
	end)

	RunService.RenderStepped:Connect(function(dt)
		if not state or ended then return end
		local rem = math.max(0, (state.turnEndsAt or 0) - workspace:GetServerTimeNow())
		ui.timerText.Text = math.ceil(rem)
		ui.timerFill.Size = UDim2.fromScale(math.clamp(rem / Config.TURN_TIME, 0, 1), 1)
	end)
end

return MatchUI]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/NPCDialogue.lua"] = [=[
-- StarterPlayer/StarterPlayerScripts/UIClient/NPCDialogue.lua
local TweenService = game:GetService("TweenService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local NPCDialogue = {}

local FACE = { Normal = "🙂", Happy = "😆", Angry = "😡", Shock = "😱", Sad = "😭", Smug = "😏", Sus = "🤨" }
local BG = { Normal = C.Yellow, Happy = C.Lime, Angry = C.Red, Shock = C.Blue, Sad = C.Purple, Smug = C.Pink, Sus = C.Orange }
local SLOW = { ["!"] = true, ["?"] = true, ["."] = true, ["…"] = true }

local function loopTween(inst, t, props)
	local tw = TweenService:Create(inst, TweenInfo.new(t, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), props)
	tw:Play()
	return tw
end

local function express(st, expr)
	if st.loop then st.loop:Cancel(); st.loop = nil end
	local p = st.portrait
	p.Rotation, p.Position = 0, st.basePos
	if expr == "Happy" then
		st.loop = loopTween(p, 0.22, { Position = st.basePos - UDim2.fromOffset(0, 12) })
	elseif expr == "Angry" then
		UIKit.shake(st.holder, 14); UIKit.sfx("Honk", 0.2)
	elseif expr == "Shock" then
		UIKit.jelly(p, 0.5); UIKit.sfx("Boing", 0.1)
	elseif expr == "Sad" then
		st.loop = loopTween(p, 1.2, { Rotation = -8, Position = st.basePos + UDim2.fromOffset(0, 8) })
	elseif expr == "Smug" then
		st.loop = loopTween(p, 0.8, { Rotation = 10 })
	else
		st.loop = loopTween(p, 1.4, { Position = st.basePos - UDim2.fromOffset(0, 4) }) -- ขยับเบาๆ เหมือนหายใจ
	end
end

-- lines[i] = { Speaker, Expr, Text, Speed, Next, Choices = {{ Text, Goto, OnPick, Close }} }
-- opts = { Speaker = "ชื่อหลัก", Portraits = { [Speaker] = { Happy = "rbxassetid://..." } }, OnDone = function() end }
function NPCDialogue.Play(parent, lines, opts)
	opts = opts or {}
	local root = UIKit.new("TextButton", { Name = "Dialogue", Text = "", AutoButtonColor = false, BackgroundColor3 = C.TableDark,
		BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 150, Parent = parent })
	UIKit.tween(root, 0.2, { BackgroundTransparency = 0.55 })

	local boxHolder, box = UIKit.comicBox({ Parent = root, Size = UDim2.fromScale(0.78, 0.26), Position = UDim2.fromScale(0.57, 0.96),
		AnchorPoint = Vector2.new(0.5, 1), Color = C.Panel, ShadowOffset = 8, StrokeThickness = 4, ZIndex = 151 })
	local portHolder, portFace = UIKit.comicBox({ Parent = root, Size = UDim2.fromScale(0.16, 0.3), Position = UDim2.fromScale(0.03, 0.96),
		AnchorPoint = Vector2.new(0, 1), Color = C.Yellow, Tilt = -4, ZIndex = 155, Clip = true })
	local portrait = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(0.9, 0.9), Position = UDim2.fromScale(0.05, 0.05),
		ZIndex = 157, Parent = portFace })
	local emoji = UIKit.new("TextLabel", { BackgroundTransparency = 1, TextScaled = true, Text = FACE.Normal, Size = UDim2.fromScale(1, 1),
		ZIndex = 158, Parent = portrait })
	local img = UIKit.new("ImageLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ScaleType = Enum.ScaleType.Fit,
		Visible = false, ZIndex = 158, Parent = portrait })
	local _, nameFace = UIKit.comicBox({ Parent = boxHolder, Size = UDim2.new(0.3, 0, 0, 46), Position = UDim2.new(0.03, 0, 0, -16),
		AnchorPoint = Vector2.new(0, 0.5), Color = C.Pink, Tilt = -3, ZIndex = 158 })
	local nameLbl = UIKit.label({ Text = "", Size = UDim2.new(1, -16, 1, -8), Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = CENTER,
		MaxTextSize = 28, ZIndex = 160, Parent = nameFace })
	local text = UIKit.label({ Text = "", Color = C.Ink, StrokeThickness = 0, Wrap = true, AlignX = Enum.TextXAlignment.Left,
		AlignY = Enum.TextYAlignment.Top, Size = UDim2.new(1, -40, 1, -46), Position = UDim2.new(0, 20, 0, 34), MaxTextSize = 30,
		ZIndex = 153, Parent = box })
	local arrow = UIKit.label({ Text = "▼", Color = C.Pink, Size = UDim2.fromOffset(30, 30), Position = UDim2.new(1, -26, 1, -20),
		AnchorPoint = CENTER, Visible = false, ZIndex = 154, Parent = box })
	loopTween(arrow, 0.35, { Position = arrow.Position + UDim2.fromOffset(0, 6) })
	local choices = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(0.3, 0.3), Position = UDim2.new(0.95, 0, 0.7, -10),
		AnchorPoint = Vector2.new(1, 1), ZIndex = 170, Parent = root }, {
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 10), VerticalAlignment = Enum.VerticalAlignment.Bottom, SortOrder = Enum.SortOrder.LayoutOrder }) })

	local st = { portrait = portrait, holder = portHolder, basePos = portrait.Position }
	local idx, typing, skip, waitingChoice, finished = 0, false, false, false, false

	local function finish()
		if finished then return end
		finished = true
		if st.loop then st.loop:Cancel() end
		UIKit.tween(root, 0.2, { BackgroundTransparency = 1 })
		UIKit.tween(UIKit.getScale(boxHolder), 0.18, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		UIKit.tween(UIKit.getScale(portHolder), 0.18, { Scale = 0 }, Enum.EasingStyle.Back, Enum.EasingDirection.In)
		task.delay(UIKit.dur(0.2), function() root:Destroy() end)
		if opts.OnDone then opts.OnDone() end
	end

	local show
	local function jump(i)
		if i and lines[i] then show(i) else finish() end
	end

	show = function(i)
		idx = i
		local line = lines[i]
		local speaker = line.Speaker or opts.Speaker or "???"
		local expr = line.Expr or "Normal"
		if nameLbl.Text ~= speaker then UIKit.bounceText(nameLbl, speaker, 0.25) end
		local set = opts.Portraits and opts.Portraits[speaker]
		local imgId = set and set[expr]
		img.Visible, emoji.Visible = imgId ~= nil, imgId == nil
		if imgId then img.Image = imgId else emoji.Text = FACE[expr] or FACE.Normal end
		portFace.BackgroundColor3 = BG[expr] or C.Yellow
		express(st, expr)

		for _, c in ipairs(choices:GetChildren()) do if c:IsA("GuiButton") then c:Destroy() end end
		arrow.Visible = false
		UIKit.setText(text, line.Text or "")
		local gs = {}
		for first, last in utf8.graphemes(text.Text) do table.insert(gs, text.Text:sub(first, last)) end
		text.MaxVisibleGraphemes = 0
		typing, skip = true, false

		task.spawn(function()
			for g = 1, #gs do
				if skip or idx ~= i or finished then break end
				text.MaxVisibleGraphemes = g
				if g % 2 == 0 then UIKit.sfx("Blip", 0.3) end
				task.wait(UIKit.dur(SLOW[gs[g]] and 0.18 or (line.Speed or 0.028)))
			end
			if idx ~= i or finished then return end
			text.MaxVisibleGraphemes = -1
			typing = false
			if line.Choices then
				waitingChoice = true
				for k, ch in ipairs(line.Choices) do
					UIKit.button({ Parent = choices, Text = ch.Text, Color = ({ C.Lime, C.Blue, C.Orange, C.Pink })[(k - 1) % 4 + 1],
						Size = UDim2.new(1, 0, 0, 54), LayoutOrder = k, Tilt = (k % 2 == 0) and 2 or -2, MaxTextSize = 24, ZIndex = 171,
						OnClick = function()
							if not waitingChoice then return end
							waitingChoice = false
							if ch.OnPick then ch.OnPick() end
							if ch.Close then finish() else jump(ch.Goto or idx + 1) end
						end })
				end
			else
				arrow.Visible = true
			end
		end)
	end

	root.Activated:Connect(function()
		if finished or waitingChoice then return end
		if typing then skip = true return end
		UIKit.sfx("Click", 0.2)
		jump(lines[idx].Next or idx + 1)
	end)

	local s = UIKit.getScale(boxHolder)
	s.Scale = 0.3
	UIKit.tween(s, 0.35, { Scale = 1 }, Enum.EasingStyle.Back)
	jump(1)
	return { Close = finish }
end

return NPCDialogue]=]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/Net.lua"] = [[
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Remotes = ReplicatedStorage:WaitForChild("Remotes")

local Net = {}
local locks = {}

local function remote(name) return Remotes:WaitForChild(name, 10) end

-- ส่งได้ทีละคำสั่งต่อกลุ่ม: ถ้ายังไม่ตอบกลับ จะไม่ส่งซ้ำ
function Net.invokeLocked(lock, name, ...)
	if locks[lock] then return false, "BUSY" end
	local r = remote(name)
	if not r then return false, "NET_ERROR" end
	locks[lock] = true
	local res = table.pack(pcall(r.InvokeServer, r, ...))
	locks[lock] = nil
	if not res[1] then
		warn("[Net] " .. name .. ": " .. tostring(res[2]))
		return false, "NET_ERROR"
	end
	return table.unpack(res, 2, res.n)
end

function Net.invoke(name, ...) return Net.invokeLocked(name, name, ...) end
function Net.busy(lock) return locks[lock] == true end
function Net.fire(name, ...)
	local r = remote(name)
	if r then r:FireServer(...) end
end
function Net.on(name, fn)
	local r = remote(name)
	if r then return r.OnClientEvent:Connect(fn) end
	return nil
end

Net.Errors = {
	BUSY = "กำลังทำคำสั่งก่อนหน้า", SLOW_DOWN = "กดเร็วเกินไป รอสักครู่",
	NET_ERROR = "เชื่อมต่อเซิร์ฟเวอร์ไม่สำเร็จ", SERVER_ERROR = "เซิร์ฟเวอร์ขัดข้อง ลองอีกครั้ง",
	NO_MATCH = "ไม่ได้อยู่ในแมตช์", MATCH_OVER = "แมตช์จบแล้ว", NOT_YOUR_TURN = "ยังไม่ถึงตาคุณ",
	INVALID_CARD = "ใช้การ์ดใบนี้ไม่ได้", INVALID_TARGET = "เป้าหมายไม่ถูกต้อง",
	GATE_OCCUPIED = "ช่องเกตมีการ์ดอยู่แล้ว", FIELD_FULL = "สนามเต็มแล้ว",
	NOT_ENOUGH_POINTS = "แต้มไม่พอ", NO_POINTS = "แต้มไม่พอ",
	NOT_ENOUGH_GEMS = "เพชรไม่พอ", DATA_LOADING = "กำลังโหลดข้อมูล ลองใหม่อีกครั้ง",
	IN_MATCH = "อยู่ในแมตช์แล้ว", BAD_LEADER = "เลือกผู้นำไม่ถูกต้อง", BAD_MODE = "โหมดไม่ถูกต้อง",
	NOT_DONE = "เควสต์ยังไม่สำเร็จ", ALREADY_CLAIMED = "รับรางวัลไปแล้ว", BAD_QUEST = "ไม่พบเควสต์",
	BAD_COUNT = "จำนวนครั้งไม่ถูกต้อง", EMPTY_POOL = "ตู้สุ่มยังไม่มีการ์ด",
	BAD_FARM = "ไม่พบฟาร์มนี้", NOTHING_TO_CLAIM = "ยังไม่มีของให้เก็บ", MAX_LEVEL = "เลเวลสูงสุดแล้ว",
}

function Net.message(code)
	if typeof(code) == "string" and code:find("[^%w_]") then return code end -- ข้อความไทยจากเซิร์ฟเวอร์
	return Net.Errors[code] or ("ทำไม่ได้ (" .. tostring(code) .. ")")
end

return Net]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/SettingsPanel.lua"] = [[
-- StarterPlayerScripts/UIClient/SettingsPanel (ModuleScript)
-- ใส่ลงใน UIKit.panel(...).Content ได้ทั้งล็อบบี้และในแมตช์
local UI = game:GetService("ReplicatedStorage"):WaitForChild("Shared"):WaitForChild("UI")
local Theme = require(UI:WaitForChild("Theme"))
local UIKit = require(UI:WaitForChild("UIKit"))
local Settings = require(UI:WaitForChild("Settings"))

local SettingsPanel = {}
local SPEEDS = { 0.5, 1, 1.5, 2 }
local ROW_H = 58

local function pill(parent, text, x, width, color)
	return UIKit.new("TextButton", {
		Text = text, Font = Theme.Font, TextScaled = true, TextColor3 = Color3.new(1, 1, 1),
		BackgroundColor3 = color, Size = UDim2.new(width, 0, 0.7, 0),
		Position = UDim2.fromScale(x, 0.5), AnchorPoint = Vector2.new(1, 0.5), Parent = parent,
	}, {
		UIKit.corner(UDim.new(0.5, 0)),
		UIKit.new("UIStroke", { Thickness = 2, Color = Theme.Color.Outline, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0.18, 0), PaddingBottom = UDim.new(0.18, 0) }),
	})
end

local function row(list, order, title)
	local r = UIKit.new("Frame", {
		Name = "Row", LayoutOrder = order, Size = UDim2.new(1, 0, 0, ROW_H),
		BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.35, Parent = list,
	}, { UIKit.corner(UDim.new(0.3, 0)) })
	UIKit.new("TextLabel", {
		Text = title, Font = Theme.FontBody, TextScaled = true, TextColor3 = Theme.Color.Outline,
		TextXAlignment = Enum.TextXAlignment.Left, BackgroundTransparency = 1,
		Size = UDim2.fromScale(0.55, 0.5), Position = UDim2.fromScale(0.04, 0.5),
		AnchorPoint = Vector2.new(0, 0.5), Parent = r,
	})
	return r
end

local function toggle(list, order, title, key)
	local b = pill(row(list, order, title), "", 0.96, 0.22, Theme.Color.Green)
	local function refresh()
		local on = Settings.Get(key)
		b.Text = on and "เปิด" or "ปิด"
		b.BackgroundColor3 = on and Theme.Color.Green or Theme.Color.Gray
	end
	b.Activated:Connect(function() Settings.Set(key, not Settings.Get(key)) refresh() UIKit.sfx("Click") end)
	refresh()
end

-- opts.OnSurrender = ฟังก์ชันยอมแพ้ (ใส่เฉพาะในแมตช์)
-- คืนค่า ScrollingFrame กลับไป ถ้าจะใส่ของเพิ่มให้ตั้ง LayoutOrder ตั้งแต่ 20 ขึ้นไป
function SettingsPanel.Build(content, opts)
	opts = opts or {}
	local list = UIKit.new("ScrollingFrame", {
		Name = "SettingsList", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0,
		ScrollBarThickness = 6, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = content,
	}, {
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingRight = UDim.new(0, 10), PaddingTop = UDim.new(0, 4) }),
	})

	-- เสียง: − 70% +
	local vr = row(list, 1, "🔊 เสียงเอฟเฟกต์")
	local plus = pill(vr, "+", 0.96, 0.09, Theme.Color.Blue)
	local value = UIKit.new("TextLabel", {
		Font = Theme.Font, TextScaled = true, TextColor3 = Theme.Color.Outline, BackgroundTransparency = 1,
		Size = UDim2.fromScale(0.14, 0.5), Position = UDim2.fromScale(0.855, 0.5), AnchorPoint = Vector2.new(1, 0.5), Parent = vr,
	})
	local minus = pill(vr, "−", 0.705, 0.09, Theme.Color.Blue)
	local function refreshVol() value.Text = math.floor(Settings.Get("Sfx") * 100 + 0.5) .. "%" end
	local function step(d)
		Settings.Set("Sfx", math.clamp((math.floor(Settings.Get("Sfx") * 10 + 0.5) + d) / 10, 0, 1))
		refreshVol() UIKit.sfx("Click")
	end
	plus.Activated:Connect(function() step(1) end)
	minus.Activated:Connect(function() step(-1) end)
	refreshVol()

	-- ความเร็วแอนิเมชัน: กดวน 0.5x → 1x → 1.5x → 2x
	local sb = pill(row(list, 2, "⏩ ความเร็วแอนิเมชัน"), "", 0.96, 0.22, Theme.Color.Blue)
	local function refreshSpeed() sb.Text = Settings.Get("AnimSpeed") .. "x" end
	sb.Activated:Connect(function()
		local i = table.find(SPEEDS, Settings.Get("AnimSpeed")) or 2
		Settings.Set("AnimSpeed", SPEEDS[i % #SPEEDS + 1])
		refreshSpeed() UIKit.sfx("Click")
	end)
	refreshSpeed()

	toggle(list, 3, "✨ แสงและประกาย", "Effects")
	toggle(list, 4, "💥 ตัวเลขลอย", "DamageNumbers")
	toggle(list, 5, "🎯 ลูกศรเล็งเป้า", "TargetArrow")

	if opts.OnSurrender then
		local b = pill(row(list, 10, "🏳️ ยอมแพ้แมตช์นี้"), "ยอมแพ้", 0.96, 0.32, Theme.Color.Red)
		local armed = false
		b.Activated:Connect(function()
			if not armed then -- กดสองครั้งเพื่อกันกดพลาด
				armed = true
				b.Text = "กดอีกครั้ง"
				task.delay(3, function() if armed then armed = false b.Text = "ยอมแพ้" end end)
				return
			end
			armed = false
			b.Text = "ยอมแพ้"
			opts.OnSurrender()
		end)
	end
	return list
end

return SettingsPanel]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/StatsPanel.lua"] = [[
-- StarterPlayerScripts/UIClient/StatsPanel (ModuleScript)
-- หน้าสถิติ: วันนี้ / 7 วัน / ตลอดชีพ | ใส่ลงใน UIKit.panel(...).Content
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UI = ReplicatedStorage:WaitForChild("Shared"):WaitForChild("UI")
local Theme = require(UI:WaitForChild("Theme"))
local UIKit = require(UI:WaitForChild("UIKit"))
local CardData = require(ReplicatedStorage.Shared:WaitForChild("CardData"))

local StatsPanel = {}
local TABS = {
	{ Key = "Today", Text = "📅 วันนี้" },
	{ Key = "Week", Text = "🗓️ 7 วัน" },
	{ Key = "Total", Text = "🏆 ตลอดชีพ" },
}
local ROW_H = 40

local function clock(sec)
	sec = math.max(0, math.floor(sec or 0))
	local h, m, s = sec // 3600, (sec % 3600) // 60, sec % 60
	if h > 0 then return ("%d ชม. %d นาที"):format(h, m) end
	if m > 0 then return ("%d นาที %d วิ"):format(m, s) end
	return ("%d วิ"):format(s)
end

local function num(n) return tostring(math.floor((n or 0) + 0.5)):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "") end
local function pct(n) return ("%.1f%%"):format(n or 0) end
local function cardName(id) local c = id and CardData[id] return c and c.Name or "-" end

-- กลุ่มสถิติ: { หัวข้อ, { {ป้าย, ค่า}, ... } }
local function groups(b)
	local d = b.Derived
	local topPlayed = d.TopPlayedCard and ("%s (%s ครั้ง)"):format(cardName(d.TopPlayedCard), num(d.TopPlayedCount)) or "-"
	local topKill = d.TopKillCard and ("%s (%s ตัว)"):format(cardName(d.TopKillCard), num(d.TopKillCount)) or "-"
	local topLeader = d.TopLeader and ("%s (%s แมตช์)"):format(cardName(d.TopLeader), num(d.TopLeaderMatches)) or "-"
	return {
		{ "⚔️ ผลการแข่ง", {
			{ "แมตช์ทั้งหมด", num(b.Matches) },
			{ "ชนะ", num(b.Wins) }, { "แพ้", num(b.Losses) },
			{ "เสมอ", num(b.Draws) },
			{ "อัตราชนะ", pct(d.WinRate) },
			{ "PvP (ชนะ/แพ้)", ("%s / %s  (%s)"):format(num(b.WinsPvP), num(b.LossesPvP), pct(d.WinRatePvP)) },
			{ "ซ้อมบอท (ชนะ/แพ้)", ("%s / %s  (%s)"):format(num(b.WinsBot), num(b.LossesBot), pct(d.WinRateBot)) },
			{ "ได้เล่นก่อน ชนะ", pct(d.GoingFirstWinRate) },
		} },
		{ "⏱️ เวลา", {
			{ "เวลาเล่นรวม", clock(b.PlaySec) },
			{ "เฉลี่ยต่อแมตช์", clock(d.AvgMatchSec) },
			{ "แมตช์ที่ยาวที่สุด", clock(b.LongestMatchSec) },
			{ "ชนะเร็วที่สุด", b.ShortestWinSec > 0 and clock(b.ShortestWinSec) or "-" },
			{ "เวลาเฉพาะที่ชนะ", clock(b.WinSec) },
			{ "เวลาเฉพาะที่แพ้", clock(b.LossSec) },
		} },
		{ "🔎 คิว", {
			{ "เข้าคิว PvP", num(b.QueuePvP) },
			{ "เข้าคิวซ้อมบอท", num(b.QueueBot) },
			{ "ยกเลิกคิว", num(b.QueueCancel) },
			{ "จับคู่สำเร็จ", num(b.QueueMatched) },
			{ "รอคิวเฉลี่ย", clock(d.AvgQueueWaitSec) },
		} },
		{ "🃏 การ์ด", {
			{ "ลงการ์ดทั้งหมด", num(b.CardsPlayed) },
			{ "ตัวละคร / เวท / อาวุธ", ("%s / %s / %s"):format(num(b.CharactersPlayed), num(b.SpellsPlayed), num(b.WeaponsPlayed)) },
			{ "ลงสนาม / ลงเกต", ("%s / %s"):format(num(b.PlayedToField), num(b.PlayedToGate)) },
			{ "พอยต์ที่ใช้", num(b.PointsSpent) },
			{ "การ์ดต่อแมตช์", tostring(d.CardsPerMatch) },
			{ "จั่วการ์ด", num(b.CardsDrawn) },
			{ "การ์ดที่ใช้บ่อยสุด", topPlayed },
			{ "การ์ดที่ฆ่าได้มากสุด", topKill },
			{ "ผู้นำที่เล่นบ่อยสุด", topLeader },
		} },
		{ "🎲 ช่องเกต", {
			{ "ทอยเกตทั้งหมด", num(b.GateRolls) },
			{ "ร่างทอง ✨", ("%s (%s)"):format(num(b.GateGolden), pct(d.GoldenRate)) },
			{ "ปั่นติด 💪", num(b.GatePumped) },
			{ "ธรรมดา 😐", num(b.GateNormal) },
			{ "ย้วย 😵", num(b.GateDroopy) },
			{ "ก้อนอึ 💩", ("%s (%s)"):format(num(b.GatePoop), pct(d.PoopRate)) },
		} },
		{ "💥 การต่อสู้", {
			{ "โจมตีทั้งหมด", num(b.Attacks) },
			{ "ตีผู้นำ / ตีการ์ด", ("%s / %s"):format(num(b.AttacksAtLeader), num(b.AttacksAtCard)) },
			{ "ตีพลาด (สไลม์)", num(b.AttacksMissed) },
			{ "ดาเมจใส่ผู้นำ", num(b.DamageToLeader) },
			{ "ดาเมจใส่การ์ด", num(b.DamageToCards) },
			{ "ดาเมจที่ผู้นำเราโดน", num(b.DamageTaken) },
			{ "ฆ่าการ์ดศัตรู", num(b.KillsMade) },
			{ "การ์ดเราตาย", num(b.CardsLost) },
			{ "ฮีลรวม", num(b.HealDone) },
			{ "โล่ที่ตั้ง", num(b.ShieldGained) },
			{ "สวมอาวุธ / ปาอาวุธ", ("%s / %s"):format(num(b.WeaponsEquipped), num(b.WeaponsThrown)) },
			{ "โบนัสธาตุ / โทษธาตุ", ("%s / %s"):format(num(b.ElementBonus), num(b.ElementPenalty)) },
		} },
		{ "⏳ เทิร์น", {
			{ "เทิร์นที่เล่น", num(b.Turns) },
			{ "ข้ามเทิร์น (ดองพอยต์)", num(b.TurnsSkipped) },
			{ "พอยต์ที่ดองไว้รวม", num(b.PointsBanked) },
			{ "หมดเวลาเทิร์น", num(b.TurnsTimedOut) },
			{ "ถูกการ์ดหมดกองเล่นงาน", ("%s ครั้ง (-%s HP)"):format(num(b.FatigueTurns), num(b.FatigueDamage)) },
		} },
		{ "🚪 การจบเกม", {
			{ "ยอมแพ้", num(b.Surrenders) },
			{ "แพ้เพราะ AFK", num(b.AfkLosses) },
			{ "หลุด/ออกกลางแมตช์", num(b.Disconnects) },
			{ "ศัตรูหนีออกให้เราชนะ", num(b.OpponentLeft) },
		} },
		{ "💎 รางวัล", {
			{ "เพชรที่ได้จากแมตช์", num(b.GemsEarned) },
			{ "โบนัสค่าหัว", num(b.BountyEarned) },
			{ "เพชรสูงสุดในแมตช์เดียว", num(b.BestGemsOneMatch) },
		} },
	}
end

local function sectionBox(list, order, title)
	local box = UIKit.new("Frame", {
		Name = "Group", LayoutOrder = order, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.3, Parent = list,
	}, {
		UIKit.corner(UDim.new(0, 12)),
		UIKit.new("UIPadding", { PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }),
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder }),
	})
	UIKit.new("TextLabel", {
		LayoutOrder = 0, Size = UDim2.new(1, 0, 0, ROW_H - 4), BackgroundTransparency = 1, Font = Theme.Font,
		Text = title, TextSize = 24, TextColor3 = Theme.Color.Outline, TextXAlignment = Enum.TextXAlignment.Left, Parent = box,
	})
	return box
end

local function statRow(parent, order, label, value)
	local r = UIKit.new("Frame", { LayoutOrder = order, Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, Parent = parent })
	UIKit.new("TextLabel", {
		Size = UDim2.fromScale(0.55, 1), BackgroundTransparency = 1, Font = Theme.FontBody, Text = label, TextSize = 18,
		TextColor3 = Color3.fromRGB(90, 80, 70), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r,
	})
	UIKit.new("TextLabel", {
		Size = UDim2.fromScale(0.45, 1), Position = UDim2.fromScale(0.55, 0), BackgroundTransparency = 1, Font = Theme.FontBody,
		Text = value, TextSize = 18, TextColor3 = Theme.Color.Outline, TextXAlignment = Enum.TextXAlignment.Right,
		TextTruncate = Enum.TextTruncate.AtEnd, Parent = r,
	})
end

-- กราฟแท่งแมตช์ 7 วันล่าสุด (ชนะ = เขียว, แพ้ = แดง)
local function dayChart(list, order, days)
	local box = sectionBox(list, order, "📈 แมตช์ 7 วันล่าสุด")
	local area = UIKit.new("Frame", { LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 120), BackgroundTransparency = 1, Parent = box })
	local peak = 1
	for _, d in ipairs(days) do peak = math.max(peak, d.Wins + d.Losses) end
	for i, d in ipairs(days) do
		local x = (i - 1) / #days
		local col = UIKit.new("Frame", { Size = UDim2.fromScale(1 / #days, 1), Position = UDim2.fromScale(x, 0), BackgroundTransparency = 1, Parent = area })
		local wH, lH = d.Wins / peak * 0.7, d.Losses / peak * 0.7
		UIKit.new("Frame", { -- แพ้ (ล่าง)
			AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 0.78), Size = UDim2.fromScale(0.5, lH),
			BackgroundColor3 = Theme.Color.Red, BorderSizePixel = 0, Parent = col,
		}, { UIKit.corner(UDim.new(0.2, 0)) })
		UIKit.new("Frame", { -- ชนะ (วางบนแพ้)
			AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 0.78 - lH), Size = UDim2.fromScale(0.5, wH),
			BackgroundColor3 = Theme.Color.Green, BorderSizePixel = 0, Parent = col,
		}, { UIKit.corner(UDim.new(0.2, 0)) })
		UIKit.new("TextLabel", {
			Position = UDim2.fromScale(0, 0.8), Size = UDim2.fromScale(1, 0.2), BackgroundTransparency = 1, Font = Theme.FontBody,
			Text = d.Day:sub(9, 10) .. "/" .. d.Day:sub(6, 7), TextSize = 14, TextColor3 = Color3.fromRGB(90, 80, 70), Parent = col,
		})
		if d.Wins + d.Losses > 0 then
			UIKit.new("TextLabel", {
				AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.5, 0.78 - lH - wH), Size = UDim2.fromScale(1, 0.14),
				BackgroundTransparency = 1, Font = Theme.FontBody, Text = tostring(d.Wins + d.Losses), TextSize = 14,
				TextColor3 = Theme.Color.Outline, Parent = col,
			})
		end
	end
end

-- สรุปผู้นำ (แมตช์/ชนะ/แพ้)
local function leaderTable(list, order, b)
	local rows = {}
	for id, l in pairs(b.Leaders) do table.insert(rows, { id = id, l = l }) end
	if #rows == 0 then return end
	table.sort(rows, function(a, c) return (a.l.Matches or 0) > (c.l.Matches or 0) end)
	local box = sectionBox(list, order, "👑 สถิติรายผู้นำ")
	for i, r in ipairs(rows) do
		statRow(box, i, cardName(r.id), ("%s แมตช์ • ชนะ %s • แพ้ %s"):format(num(r.l.Matches), num(r.l.Wins), num(r.l.Losses)))
	end
end

-- การ์ดที่ใช้บ่อย 8 อันดับ
local function cardTable(list, order, b)
	local rows = {}
	for id, c in pairs(b.Cards) do
		if (c.Played or 0) > 0 then table.insert(rows, { id = id, c = c }) end
	end
	if #rows == 0 then return end
	table.sort(rows, function(a, c) return a.c.Played > c.c.Played end)
	local box = sectionBox(list, order, "🃏 การ์ดที่ใช้บ่อย 8 อันดับ")
	for i = 1, math.min(8, #rows) do
		local r = rows[i]
		statRow(box, i, ("%d. %s"):format(i, cardName(r.id)),
			("ลง %s • ฆ่า %s • ตาย %s"):format(num(r.c.Played), num(r.c.Kills), num(r.c.Deaths)))
	end
end

function StatsPanel.Build(content, fetch)
	local tabBar = UIKit.new("Frame", { Size = UDim2.fromScale(1, 0.1), BackgroundTransparency = 1, Parent = content }, {
		UIKit.new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0.02, 0),
			HorizontalAlignment = Enum.HorizontalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})
	local body = UIKit.new("ScrollingFrame", {
		Size = UDim2.fromScale(1, 0.88), Position = UDim2.fromScale(0, 0.12), BackgroundTransparency = 1, BorderSizePixel = 0,
		ScrollBarThickness = 6, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = content,
	}, {
		UIKit.new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
		UIKit.new("UIPadding", { PaddingRight = UDim.new(0, 10) }),
	})

	local snapshot, current, loading = nil, "Today", false
	local buttons = {}

	local function render()
		for _, c in ipairs(body:GetChildren()) do
			if c:IsA("GuiObject") then c:Destroy() end
		end
		if not snapshot then
			UIKit.new("TextLabel", {
				Size = UDim2.new(1, 0, 0, 80), BackgroundTransparency = 1, Font = Theme.Font, TextSize = 26,
				Text = loading and "⏳ กำลังโหลดสถิติ..." or "โหลดสถิติไม่สำเร็จ ลองเปิดใหม่อีกครั้ง",
				TextColor3 = Theme.Color.Outline, Parent = body,
			})
			return
		end
		local b = snapshot[current]
		local n = 0
		local function nextOrder() n = n + 1 return n end
		UIKit.new("TextLabel", {
			LayoutOrder = nextOrder(), Size = UDim2.new(1, 0, 0, 28), BackgroundTransparency = 1, Font = Theme.FontBody, TextSize = 18,
			Text = ("🔥 ชนะติดต่อกันตอนนี้ %d  •  สูงสุด %d  •  วันที่ %s (เวลาไทย)"):format(snapshot.Streak, snapshot.BestStreak, snapshot.DayKey),
			TextColor3 = Color3.fromRGB(90, 80, 70), Parent = body,
		})
		if b.Matches == 0 and b.QueuePvP + b.QueueBot == 0 then
			UIKit.new("TextLabel", {
				LayoutOrder = nextOrder(), Size = UDim2.new(1, 0, 0, 60), BackgroundTransparency = 1, Font = Theme.Font, TextSize = 22,
				Text = "ยังไม่มีข้อมูลในช่วงนี้ ลงสนามสักตาแล้วกลับมาดูนะ 🎮", TextColor3 = Theme.Color.Outline, Parent = body,
			})
		end
		if current == "Week" then dayChart(body, nextOrder(), snapshot.Days) end
		for _, g in ipairs(groups(b)) do
			local box = sectionBox(body, nextOrder(), g[1])
			for i, r in ipairs(g[2]) do statRow(box, i, r[1], r[2]) end
		end
		leaderTable(body, nextOrder(), b)
		cardTable(body, nextOrder(), b)
	end

	local function refreshTabs()
		for key, btn in pairs(buttons) do
			UIKit.setColor(btn, key == current and Theme.Color.Pink or Theme.Color.Gray)
		end
	end

	for i, tab in ipairs(TABS) do
		local btn = UIKit.button({
			Text = tab.Text, Color = Theme.Color.Gray, Size = UDim2.fromScale(0.3, 1), Parent = tabBar,
			OnClick = function() current = tab.Key refreshTabs() render() end,
		})
		btn.LayoutOrder = i
		buttons[tab.Key] = btn
	end
	refreshTabs()

	-- เรียกทุกครั้งที่เปิดหน้า เพื่อให้ตัวเลขสดเสมอ
	local api = {}
	function api.Refresh()
		loading = true
		render()
		task.spawn(function()
			local ok, result = pcall(fetch)
			loading = false
			snapshot = ok and typeof(result) == "table" and result or nil
			if body.Parent then render() end
		end)
	end
	api.Refresh()
	return api
end

return StatsPanel
]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/TargetArrow.lua"] = [[
-- StarterPlayerScripts/UIClient/TargetArrow (ModuleScript)
-- ลูกศรโค้งแบบ Hearthstone จากการ์ดที่เลือกไปหาเมาส์/นิ้ว
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local GuiService = game:GetService("GuiService")
local UI = game:GetService("ReplicatedStorage"):WaitForChild("Shared"):WaitForChild("UI")
local Theme = require(UI:WaitForChild("Theme"))
local Settings = require(UI:WaitForChild("Settings"))

local Arrow = {}
local DOTS = 16
local holder, dots, reticle, conn, source

local function make(class, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(props) do o[k] = v end
	o.Parent = parent
	return o
end

function Arrow.Stop()
	if conn then conn:Disconnect() conn = nil end
	if holder then holder:Destroy() holder = nil end
	source = nil
end

function Arrow.Start(fromObj, color)
	Arrow.Stop()
	if not (fromObj and Settings.Get("TargetArrow")) then return end
	local sg = fromObj:FindFirstAncestorWhichIsA("ScreenGui")
	if not sg then return end
	color = color or Theme.Color.Red
	source = fromObj

	holder = make("Frame", { Name = "TargetArrow", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 150 }, sg)
	dots = {}
	for i = 1, DOTS do
		local s = 6 + i * 0.7
		local d = make("Frame", {
			Size = UDim2.fromOffset(s, s), AnchorPoint = Vector2.new(0.5, 0.5),
			BackgroundColor3 = color, BorderSizePixel = 0, ZIndex = 151,
		}, holder)
		make("UICorner", { CornerRadius = UDim.new(1, 0) }, d)
		make("UIStroke", { Thickness = 1.5, Color = Theme.Color.Outline }, d)
		dots[i] = d
	end
	reticle = make("Frame", {
		Size = UDim2.fromOffset(48, 48), AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1, ZIndex = 152,
	}, holder)
	make("UICorner", { CornerRadius = UDim.new(1, 0) }, reticle)
	make("UIStroke", { Thickness = 4, Color = color }, reticle)
	for _, sz in ipairs({ UDim2.new(1.4, 0, 0, 3), UDim2.new(0, 3, 1.4, 0) }) do
		make("Frame", {
			Size = sz, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			BackgroundColor3 = color, BorderSizePixel = 0, ZIndex = 152,
		}, reticle)
	end

	conn = RunService.RenderStepped:Connect(function()
		if not (source and source.Parent) then Arrow.Stop() return end
		local a = source.AbsolutePosition + source.AbsoluteSize / 2 - sg.AbsolutePosition
		local mouse = UserInputService:GetMouseLocation()
		-- ScreenGui ที่ IgnoreGuiInset=false วาดใต้แถบ Roblox: ต้องหัก inset ด้านบน ถ้า IgnoreGuiInset=true ไม่ต้องหัก
		local inset = sg.IgnoreGuiInset and Vector2.zero or GuiService:GetGuiInset()
		local m = mouse - inset - sg.AbsolutePosition
		local ctrl = (a + m) / 2 + Vector2.new(0, -math.min((m - a).Magnitude * 0.35, 160))
		local phase = (os.clock() * 1.5) % 1
		for i, d in ipairs(dots) do
			local t = math.clamp((i - 1 + phase) / DOTS, 0, 1)
			local u = 1 - t
			local p = a * (u * u) + ctrl * (2 * u * t) + m * (t * t)
			d.Position = UDim2.fromOffset(p.X, p.Y)
			d.BackgroundTransparency = 0.6 * u
		end
		reticle.Position = UDim2.fromOffset(m.X, m.Y)
		reticle.Rotation = (os.clock() * 90) % 360
	end)
end

-- เรียกได้ทุกเฟรม: ถ้าการ์ดต้นทางเปลี่ยนจะเริ่มใหม่ ถ้าเป็น nil จะซ่อน
function Arrow.Follow(obj, color)
	if obj == source then return end
	Arrow.Stop()
	if obj then Arrow.Start(obj, color) end
end

return Arrow]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/TournamentBracket.lua"] = [=[
-- StarterPlayer/StarterPlayerScripts/UIClient/TournamentBracket.lua
local TweenService = game:GetService("TweenService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local TournamentBracket = {}

local SAMPLE = {
	{ { A = "ไก่ทอดซีอิ๊ว", B = "ลุงเป็ด", Winner = "A" }, { A = "แมวส้ม", B = "คุณ", Winner = "B" } },
	{ { A = "เจ้าปลาทอง", B = "ไก่ทอดซีอิ๊ว", From = { nil, 1 } }, { A = "บอสถุงเท้า", B = "คุณ", From = { nil, 2 } } },
	{ { From = { 1, 2 } } },
}

-- opts = { Rounds = {...}, RoundNames = {...}, Me = "ชื่อเรา", Title = "...", OnJoin = function() end }
function TournamentBracket.Open(parent, opts)
	opts = opts or {}
	local rounds = opts.Rounds or SAMPLE
	local names = opts.RoundNames or { "รอบแรก", "รอบรอง", "ชิงแชมป์!!" }
	local me, R = opts.Me or "คุณ", #rounds
	local panel = UIKit.panel(parent, opts.Title or "ทัวร์นาเมนต์มหากาว", C.Blue)
	local area = UIKit.new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, -40, 1, -110), Position = UDim2.new(0, 20, 0, 84), Parent = panel })

	local colW = 0.82 / R
	local boxW, boxH = colW * 0.8, 0.18
	local function xc(r) return (r - 0.5) * colW end

	-- คำนวณตำแหน่งแกน Y: แมตช์ที่มี From จะอยู่ตรงกลางระหว่างแมตช์ต้นทาง
	local ys = {}
	for r, matches in ipairs(rounds) do
		ys[r] = {}
		for j, m in ipairs(matches) do
			local y
			if m.From and r > 1 then
				local a = m.From[1] and ys[r - 1][m.From[1]]
				local b = m.From[2] and ys[r - 1][m.From[2]]
				y = (a and b) and (a + b) / 2 or a or b
			end
			ys[r][j] = y or (j - 0.5) / #matches
		end
	end

	local function line(x1, y1, x2, y2, lit)
		UIKit.new("Frame", { BackgroundColor3 = lit and C.Yellow or C.White, BackgroundTransparency = lit and 0 or 0.5, BorderSizePixel = 0,
			AnchorPoint = CENTER, Position = UDim2.fromScale((x1 + x2) / 2, (y1 + y2) / 2),
			Size = UDim2.new(math.abs(x2 - x1), 5, math.abs(y2 - y1), 5), ZIndex = 2, Parent = area })
	end
	for r = 2, R do
		for j, m in ipairs(rounds[r]) do
			for k = 1, 2 do
				local src = m.From and m.From[k]
				if src and ys[r - 1][src] then
					local sy, ty = ys[r - 1][src], ys[r][j]
					local x1, x2 = xc(r - 1) + boxW / 2, xc(r) - boxW / 2
					local mx, lit = (x1 + x2) / 2, rounds[r - 1][src].Winner ~= nil
					line(x1, sy, mx, sy, lit); line(mx, sy, mx, ty, lit); line(mx, ty, x2, ty, lit)
				end
			end
		end
	end

	for r, matches in ipairs(rounds) do
		UIKit.label({ Text = names[r] or ("รอบ " .. r), Color = r == R and C.Yellow or C.White, Size = UDim2.new(colW, 0, 0, 34),
			Position = UDim2.new(xc(r), 0, 0, -30), AnchorPoint = CENTER, Tilt = -3, MaxTextSize = 28, Parent = area })
		for j, m in ipairs(matches) do
			local holder, face = UIKit.comicBox({ Parent = area, Size = UDim2.fromScale(boxW, boxH), Position = UDim2.fromScale(xc(r), ys[r][j]),
				AnchorPoint = CENTER, Color = C.TableDark, Tilt = (j % 2 == 0) and 1.5 or -1.5, ShadowOffset = 4, ZIndex = 5 })
			local z = face.ZIndex
			for k, key in ipairs({ "A", "B" }) do
				local name = m[key] or "???"
				local won, lost = m.Winner == key, m.Winner ~= nil and m.Winner ~= key
				local row = UIKit.new("Frame", { BackgroundColor3 = won and C.Green or lost and C.Gray or C.Purple, BackgroundTransparency = lost and 0.3 or 0,
					Size = UDim2.new(1, -10, 0.5, -6), Position = UDim2.new(0, 5, (k - 1) * 0.5, 4), ZIndex = z + 1, Parent = face },
					{ UIKit.corner(8), UIKit.stroke(name == me and C.Pink or C.Outline, name == me and 4 or 2) })
				UIKit.label({ Text = (won and "👑 " or lost and "💀 " or "") .. name, AlignX = Enum.TextXAlignment.Left,
					Size = UDim2.new(1, -12, 1, -4), Position = UDim2.new(0, 8, 0, 2), MaxTextSize = 20, ZIndex = z + 2, Parent = row })
			end
			UIKit.badge(holder, "VS", C.Yellow, { Size = UDim2.fromOffset(40, 24), Position = UDim2.new(1, 4, 0.5, 0), AnchorPoint = CENTER,
				Tilt = 10, MaxTextSize = 16, ZIndex = z + 4 })
		end
	end

	-- ถ้วยแชมป์
	local final = rounds[R] and rounds[R][1]
	local champ = final and final.Winner and final[final.Winner]
	local fy = ys[R] and ys[R][1] or 0.5
	line(xc(R) + boxW / 2, fy, 0.9, fy, champ ~= nil)
	local trophy = UIKit.label({ Text = "🏆", StrokeThickness = 0, Size = UDim2.fromOffset(110, 110), Position = UDim2.fromScale(0.93, fy),
		AnchorPoint = CENTER, MaxTextSize = 100, ZIndex = 8, Parent = area })
	trophy.TextTransparency = champ and 0 or 0.6
	UIKit.label({ Text = champ or "???", Color = C.Yellow, Size = UDim2.new(0.16, 0, 0, 34), Position = UDim2.new(0.93, 0, fy, 66),
		AnchorPoint = CENTER, MaxTextSize = 26, ZIndex = 8, Parent = area })
	if champ then
		TweenService:Create(trophy, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Rotation = 10 }):Play()
		FX.sparkles(area, C.Yellow, 20, Vector2.new(0.93, fy))
		UIKit.rain(panel, "🎉", 14)
	end

	if opts.OnJoin then
		UIKit.button({ Parent = panel, Text = "ลงแข่ง!", Color = C.Lime, Size = UDim2.fromOffset(170, 56), Position = UDim2.new(1, -20, 1, -14),
			AnchorPoint = Vector2.new(1, 1), Tilt = -3, Debounce = 1, OnClick = opts.OnJoin })
	end
	return panel
end

return TournamentBracket]=]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/TowerUI.lua"] = [[
-- StarterPlayer/StarterPlayerScripts/UIClient/TowerUI.lua
local TweenService = game:GetService("TweenService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("Shared")
local UIKit = require(Shared.UI.UIKit)
local FX = require(Shared.UI.FX)

local Theme = UIKit.Theme
local C, CENTER = Theme.Color, UIKit.CENTER
local TowerUI = {}
local FLOOR_H = 124

local function sampleFloors()
	local names = { "ห้องเก็บถุงเท้า", "ชั้นแมวนอนทับคีย์บอร์ด", "โถงเสียงไวไฟหลุด", "ห้องรอคิวห้องน้ำ",
		"ลานกาวลอยฟ้า", "ห้องประชุมที่ควรเป็นอีเมล", "ครัวมาม่าตอนตีสาม", "ระเบียงคนลืมรหัส" }
	local bosses = { "🦆", "🐸", "🗿", "🤡" }
	local floors = {}
	for i = 1, 20 do
		local boss = i % 5 == 0
		floors[i] = { Name = names[(i - 1) % #names + 1], Boss = boss and bosses[i // 5] or nil,
			Reward = boss and ("💎 x" .. i * 10) or ("🪙 x" .. i * 50) }
	end
	return floors
end

local function loop(inst, t, props)
	TweenService:Create(inst, TweenInfo.new(t, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), props):Play()
end

-- opts = { Floors = {{Name, Boss, Reward}}, Current = ชั้นที่ยังไม่ผ่าน, OnChallenge = function(i, floor) end }
function TowerUI.Open(parent, opts)
	opts = opts or {}
	local floors = opts.Floors or sampleFloors()
	local n, current = #floors, opts.Current or 1
	local panel = UIKit.panel(parent, "หอคอยแห่งความกาว", C.Purple)

	local scroll = UIKit.new("ScrollingFrame", { BackgroundColor3 = C.Blue, BorderSizePixel = 0, Size = UDim2.new(1, -28, 1, -70),
		Position = UDim2.new(0, 14, 0, 56), CanvasSize = UDim2.fromOffset(0, n * FLOOR_H + 80), ScrollBarThickness = 10,
		ScrollBarImageColor3 = C.Yellow, Parent = panel }, {
		UIKit.corner(12), UIKit.stroke(C.Outline, 3),
		UIKit.new("UIGradient", { Rotation = 90, Color = Theme.seq(C.Purple, C.Pink, C.Blue) }) })
	UIKit.new("Frame", { Name = "Rope", BackgroundColor3 = C.Brown, BorderSizePixel = 0, Size = UDim2.new(0, 14, 0, n * FLOOR_H),
		Position = UDim2.new(0.5, -7, 0, 40), ZIndex = 1, Parent = scroll }, { UIKit.stroke(C.Outline, 2) })

	for i = 1, n do
		local f = floors[i]
		local y, boss = (n - i) * FLOOR_H + 40, f.Boss ~= nil
		local state = i < current and "Clear" or i == current and "Now" or "Lock"
		local color = state == "Clear" and C.Green or state == "Now" and C.Yellow or C.Gray
		if boss and state ~= "Clear" then color = state == "Now" and C.Red or C.Gray:Lerp(C.Red, 0.35) end

		local holder, face = UIKit.comicBox({ Parent = scroll, Size = UDim2.new(boss and 0.66 or 0.52, 0, 0, FLOOR_H - 28),
			Position = UDim2.new(i % 2 == 0 and 0.58 or 0.42, 0, 0, y), AnchorPoint = Vector2.new(0.5, 0), Color = color,
			Tilt = (i % 2 == 0) and 2 or -2, ZIndex = 3 })
		local z = face.ZIndex
		UIKit.label({ Text = "ชั้น " .. i, Size = UDim2.fromScale(0.3, 0.4), Position = UDim2.fromScale(0.04, 0.08),
			AlignX = Enum.TextXAlignment.Left, MaxTextSize = 30, ZIndex = z + 1, Parent = face })
		UIKit.label({ Text = f.Name, Size = UDim2.fromScale(0.62, 0.3), Position = UDim2.fromScale(0.04, 0.5),
			AlignX = Enum.TextXAlignment.Left, MaxTextSize = 20, ZIndex = z + 1, Parent = face })
		UIKit.label({ Text = "รางวัล " .. tostring(f.Reward or "-"), Color = C.Yellow, Size = UDim2.fromScale(0.5, 0.22),
			Position = UDim2.fromScale(0.04, 0.78), AlignX = Enum.TextXAlignment.Left, MaxTextSize = 16, ZIndex = z + 1, Parent = face })

		if boss then
			local b = UIKit.label({ Text = f.Boss, StrokeThickness = 0, Size = UDim2.fromOffset(84, 84), Position = UDim2.new(1, -10, 0.5, -10),
				AnchorPoint = Vector2.new(1, 0.5), Tilt = -14, MaxTextSize = 80, ZIndex = z + 2, Parent = holder })
			loop(b, 0.45, { Rotation = 14 })
			loop(b, 0.7, { Position = b.Position - UDim2.fromOffset(0, 12) })
			UIKit.badge(holder, "BOSS!", C.Red, { Size = UDim2.fromOffset(86, 30), Position = UDim2.new(0.5, 0, 0, -8),
				AnchorPoint = CENTER, Tilt = -6, ZIndex = z + 3 })
		end

		if state == "Now" then
			local btn = UIKit.button({ Parent = holder, Text = "ปีน!!", Color = C.Pink, Size = UDim2.fromOffset(110, 52),
				Position = UDim2.new(1, boss and -100 or -12, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), Tilt = 4, ZIndex = z + 4,
				Debounce = 1, OnClick = function() if opts.OnChallenge then opts.OnChallenge(i, f) end end })
			loop(UIKit.getScale(btn), 0.5, { Scale = 1.08 })
			FX.rarityGlow(holder, boss and "Mystic" or "Legend")
		else
			UIKit.label({ Text = state == "Clear" and "✔" or "🔒", StrokeThickness = state == "Clear" and 3 or 0,
				Color = C.White, Size = UDim2.fromOffset(46, 46), Position = UDim2.new(1, boss and -100 or -14, 0.5, 0),
				AnchorPoint = Vector2.new(1, 0.5), MaxTextSize = 40, ZIndex = z + 2, Parent = holder })
		end
	end

	task.defer(function()
		scroll.CanvasPosition = Vector2.new(0, math.max(0, (n - current) * FLOOR_H - scroll.AbsoluteSize.Y / 2 + 100))
	end)
	return panel
end

return TowerUI]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/TurnBanner.lua"] = [[
-- StarterPlayerScripts/UIClient/TurnBanner (ModuleScript)
local TweenService = game:GetService("TweenService")
local UI = game:GetService("ReplicatedStorage"):WaitForChild("Shared"):WaitForChild("UI")
local Theme = require(UI:WaitForChild("Theme"))
local UIKit = require(UI:WaitForChild("UIKit"))
local Settings = require(UI:WaitForChild("Settings"))

local Banner = {}
local strip, title, sub
local token = 0

local function kp(t, v) return NumberSequenceKeypoint.new(t, v) end

function Banner.Init(parent)
	strip = UIKit.new("Frame", {
		Name = "TurnBanner", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.375),
		Size = UDim2.fromScale(1, 0), BorderSizePixel = 0, ZIndex = 50, Visible = false,
		ClipsDescendants = true, Parent = parent,
	}, {
		UIKit.new("UIGradient", { Transparency = NumberSequence.new({ kp(0, 1), kp(0.2, 0.15), kp(0.8, 0.15), kp(1, 1) }) }),
	})
	title = UIKit.new("TextLabel", {
		BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromScale(0.6, 0.55),
		Font = Theme.Font, TextScaled = true, ZIndex = 51, Parent = strip,
	}, { UIKit.new("UIStroke", { Thickness = 3, Color = Theme.Color.Outline }) })
	sub = UIKit.new("TextLabel", {
		BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromScale(0.6, 0.22),
		Font = Theme.FontBody, TextScaled = true, TextColor3 = Color3.new(1, 1, 1), ZIndex = 51, Parent = strip,
	})
end

-- isMine = ตาเราหรือไม่ | isStart = เพิ่งเริ่มแมตช์
function Banner.Show(isMine, isStart)
	if not strip then return end
	token += 1
	local my = token
	local sp = Settings.Get("AnimSpeed") or 1

	strip.BackgroundColor3 = isMine and Color3.fromRGB(70, 50, 0) or Color3.fromRGB(70, 10, 20)
	title.TextColor3 = isMine and Theme.Color.Yellow or Theme.Color.Red
	if isStart then
		title.Text = "⚔️ เริ่มแมตช์!"
		sub.Text = isMine and "คุณได้เริ่มก่อน 🔥" or "ศัตรูได้เริ่มก่อน 😈"
	else
		title.Text = isMine and "ตาของคุณ!" or "ตาของศัตรู"
		sub.Text = isMine and "ลงการ์ด • เลือกการ์ดโจมตี • กดจบเทิร์น"
			or "ระหว่างรอ คลิกขวาหรือกดค้างที่การ์ดเพื่อดูข้อมูลได้"
	end

	strip.Visible = true
	strip.Size = UDim2.fromScale(1, 0)
	title.Position = UDim2.fromScale(-0.3, 0.4)
	sub.Position = UDim2.fromScale(1.3, 0.82)
	local slide = TweenInfo.new(0.35 / sp, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	TweenService:Create(strip, TweenInfo.new(0.25 / sp, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = UDim2.fromScale(1, 0.18) }):Play()
	TweenService:Create(title, slide, { Position = UDim2.fromScale(0.5, 0.4) }):Play()
	TweenService:Create(sub, slide, { Position = UDim2.fromScale(0.5, 0.82) }):Play()
	UIKit.sfx(isMine and "Turn" or "Click") -- ใส่ Sound ชื่อ "Turn" ใน SoundService.SFX ได้ (ถ้าไม่มีจะเงียบ)

	task.delay(1.4 / sp, function()
		if token ~= my then return end
		local out = TweenInfo.new(0.25 / sp, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		TweenService:Create(title, out, { Position = UDim2.fromScale(1.3, 0.4) }):Play()
		TweenService:Create(sub, out, { Position = UDim2.fromScale(-0.3, 0.82) }):Play()
		local t = TweenService:Create(strip, out, { Size = UDim2.fromScale(1, 0) })
		t:Play()
		t.Completed:Wait()
		if token == my then strip.Visible = false end
	end)
end

return Banner]]
SOURCES["StarterPlayer/StarterPlayerScripts/UIClient/init.client.lua"] = [[
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local StarterGui = game:GetService("StarterGui")

local UIFolder = ReplicatedStorage:WaitForChild("Shared"):WaitForChild("UI")
local UIKit = require(UIFolder:WaitForChild("UIKit"))
local S = require(UIFolder:WaitForChild("Style"))
local LobbyUI = require(script:WaitForChild("LobbyUI"))
local MatchUI = require(script:WaitForChild("MatchUI"))

local playerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false) end)

for _, name in { "LobbyHUD", "MatchUI", "Overlay" } do
	local old = playerGui:FindFirstChild(name)
	if old then old:Destroy() end
end

local hud = S.screen("LobbyHUD", 1, playerGui)
local match = S.screen("MatchUI", 5, playerGui)
local overlay = S.screen("Overlay", 10, playerGui)
UIKit.toastParent = overlay
S.toastParent = overlay

LobbyUI.Build(hud, overlay)
MatchUI.Build(match, overlay, {
	OnStart = function()
		hud.Enabled = false
		LobbyUI.ResetQueue()
	end,
	OnExit = function()
		hud.Enabled = true
		LobbyUI.Refresh()
	end,
})]]
SOURCES["tools/sim/bundle.lua"] = [=====[
local SOURCES = {}
SOURCES["ReplicatedStorage/Shared/CardData.lua"] = [[
-- ReplicatedStorage/Shared/CardData (ModuleScript)
-- ใส่ Art = "rbxassetid://..." หลังอัปโหลดภาพ (ถ้าไม่ใส่จะแสดงอีโมจิแทน)
local Config = require(script.Parent:WaitForChild("Config"))

local function char(name, cost, atk, hp, element, rarity, keywords, flavor)
	return { Name = name, Type = "Character", Cost = cost, ATK = atk, HP = hp, Element = element,
		Rarity = rarity, Keywords = keywords or {}, Flavor = flavor }
end
local function spell(name, cost, rarity, effect, desc, flavor)
	return { Name = name, Type = "Spell", Cost = cost, Rarity = rarity, Effect = effect, Desc = desc, Flavor = flavor }
end
local function weapon(name, cost, rarity, bonus, freeze, desc, flavor)
	return { Name = name, Type = "Weapon", Cost = cost, Rarity = rarity, Bonus = bonus, Durability = 2,
		Freeze = freeze or nil, Desc = desc, Flavor = flavor }
end
local function leader(name, ability, desc, flavor, emoji)
	return { Name = name, Type = "Leader", Emoji = emoji, Cost = 0, ATK = 0, HP = Config.LEADER_HP, Rarity = "Legend",
		Ability = ability, Desc = desc, Flavor = flavor }
end

return {
	-- ตัวละคร (ATK + HP + คีย์เวิร์ด×2 = พอยต์×3 + 2)
	KAI_CHON     = char("ไก่ชนเดือด", 1, 2, 3, "Muen", "Common", nil, "ขันตีสี่ทุกวัน ไม่สนว่าใครจะนอน"),
	MAEW_SOM     = char("แมวส้มนักเลง", 1, 2, 1, "Biao", "Common", { "Rush" }, "แมวส้มทุกตัวใช้สมองร่วมกันหนึ่งก้อน"),
	LOOKCHIN     = char("ลูกชิ้นกลิ้งได้", 2, 3, 5, "Sati", "Common", nil, "หลุดจากไม้แล้วไม่เคยหันหลังกลับ"),
	PA_MOUTH     = char("ป้าข้างบ้านเม้าท์มอย", 2, 1, 5, "Sati", "Rare", { "Taunt" }, "รู้ทุกเรื่องในซอย ยกเว้นเรื่องตัวเอง"),
	PILLOW_THIEF = char("จอมโจรขโมยหมอน", 2, 3, 3, "Muen", "Rare", { "Steal" }, "ขโมยได้ทุกอย่าง ยกเว้นเวลานอน"),
	BIAO_KID     = char("เด็กเบียวตาซ้ายเรืองแสง", 3, 6, 5, "Biao", "Rare", nil, "ผนึกพลังไว้ในผ้าพันแผล (จริงๆ แค่ตาแดง)"),
