SOURCES["tools/sim/t_sim.lua"] = [=[
SIM_GAMES = 500
MOCK = H.M
local function path(p) for inst, info in pairs(H.sources) do if info.path == p then return inst end end error("no " .. p) end
local N = tonumber(SIM_GAMES) or 200
local MAXT = 12000 -- virtual seconds per game

local results = { games = 0, ended = 0, stuck = 0, reasons = {}, winsFirst = 0, winsSecond = 0, turns = 0, violations = {}, errors = {} }
local function viol(seed, msg)
	results.violations[msg] = results.violations[msg] or { n = 0, seed = seed }
	results.violations[msg].n += 1
end

for g = 1, N do
	SIM_SEED, SIM_RNG_N = g, 0
	H.resetCache()
	local Config = H.load(path("ReplicatedStorage/Shared/Config.lua"))
	local Decks = H.load(path("ReplicatedStorage/Shared/Decks.lua"))
	local CardData = H.load(path("ReplicatedStorage/Shared/CardData.lua"))
	local Match = H.load(path("ServerStorage/Modules/Match.lua"))

	local bots = { { IsBot = true, Name = "BotA" }, { IsBot = true, Name = "BotB" } }
	local m = Match.new(bots[1], bots[2], Decks.Starter, Decks.Starter, Decks.Leaders[(g % 3) + 1], Decks.Leaders[((g + 1) % 3) + 1])
	local endedWith
	m.OnEnded = function(_, winner, reason) endedWith = { winner = winner, reason = reason }; return {} end

	local total0 = {}
	for _, b in ipairs(bots) do total0[b] = #m.sides[b].deck end

	local function check()
		for _, b in ipairs(bots) do
			local s = m.sides[b]
			if s.points < 0 then viol(g, "points < 0") end
			if s.points > Config.MAX_BANKED_POINTS then viol(g, "points > MAX_BANKED_POINTS") end
			if #s.field > Config.FIELD_SLOTS then viol(g, "field > FIELD_SLOTS") end
			if #s.hand > Config.MAX_HAND then viol(g, "hand > MAX_HAND") end
			if s.shield < 0 then viol(g, "shield < 0") end
			if s.leaderHP > Config.LEADER_HP + 0 and s.leaderHP > (s.maxHP or Config.LEADER_HP) then viol(g, "leaderHP above max (overheal)") end
			-- card conservation: deck+hand+field+graveyard+gate = initial deck size (tokens excluded by flag)
			local n = #s.deck + #s.hand + #s.field + #s.graveyard + (s.gate and 1 or 0)
			if n < total0[b] and not m.ended then viol(g, "cards lost (fewer than initial)") end
			local seen = {}
			for _, zone in ipairs({ s.deck, s.hand, s.field, s.graveyard }) do
				for _, c in ipairs(zone) do
					if seen[c.Uid] then viol(g, "duplicate Uid across zones") end
					seen[c.Uid] = true
					if zone == s.field and (c.HP or 0) <= 0 then viol(g, "dead card left on field") end
					if (c.ATK or 0) < 0 then viol(g, "negative ATK") end
				end
			end
			if s.gate then if seen[s.gate.Uid] then viol(g, "gate card also in another zone") end end
		end
	end

	local ok, err = pcall(function()
		m:Start()
		local t, lastTurn = 0, 0
		while not m.ended and t < MAXT do
			MOCK.pump(1); t += 1
			check()
		end
		check()
	end)
	if not ok then table.insert(results.errors, "seed " .. g .. ": " .. tostring(err)) end
	for _, e in ipairs(MOCK.taskErrors or {}) do table.insert(results.errors, "seed " .. g .. " task: " .. e) end
	MOCK.taskErrors = {}

	results.games += 1
	if m.ended and endedWith then
		results.ended += 1
		results.reasons[endedWith.reason] = (results.reasons[endedWith.reason] or 0) + 1
		local a, b = m.sides[bots[1]].leaderHP, m.sides[bots[2]].leaderHP
		local w = endedWith.winner
		if m.firstPlayer == w then results.winsFirst += 1 else results.winsSecond += 1 end
		if endedWith.reason == "LEADER_DOWN" or endedWith.reason == "FATIGUE" then
			local wl, ll = m.sides[w].leaderHP, m.sides[m:Opponent(w)].leaderHP
			if not (ll <= 0) then viol(g, "winner declared but loser HP > 0 (" .. endedWith.reason .. ")") end
		end
		results.turns += m.turnToken
	else
		results.stuck += 1
	end
	-- cleanup pending timers between games
	MOCK.pump(Config.TURN_TIME + 5)
end

print(("games=%d ended=%d stuck=%d  firstWins=%d secondWins=%d  avgTurnTokens=%.1f"):format(results.games, results.ended, results.stuck, results.winsFirst, results.winsSecond, results.turns / math.max(1, results.ended)))
for r, n in pairs(results.reasons) do print("  reason", r, n) end
local nv = 0
for msg, v in pairs(results.violations) do nv += 1; print(("VIOLATION x%d (first seed %d): %s"):format(v.n, v.seed, msg)) end
print("distinct violations:", nv)
local shown = {}
for _, e in ipairs(results.errors) do if not shown[e] and #shown < 8 then shown[e] = true; shown[#shown + 1] = e; print("ERR", e) end end
print("total error lines:", #results.errors)
]=]

local MOCK = (function()
-- Minimal mock-Roblox runtime (Luau). Loads repo modules with their own env.

local M = {}

local function Signal()
	local s = { _h = {} }
	function s:Connect(f) local c = { f = f, Connected = true }; table.insert(self._h, c)
		return { Disconnect = function() c.Connected = false end } end
	function s:Once(f) return self:Connect(f) end
	function s:Wait() return end
	function s:Fire(...)
		for _, c in ipairs(table.clone(self._h)) do
			if c.Connected then
				local co = coroutine.create(c.f)
				local ok, e = coroutine.resume(co, ...)
				if not ok then M.handlerErrors = M.handlerErrors or {}; table.insert(M.handlerErrors, tostring(e)) end
			end
		end
	end
	return s
end
M.Signal = Signal

local SIGNALS = { Activated=1, MouseButton1Click=1, MouseButton1Down=1, MouseButton1Up=1, MouseButton2Click=1,
	MouseEnter=1, MouseLeave=1, InputBegan=1, InputEnded=1, InputChanged=1, Changed=1, ChildAdded=1, ChildRemoved=1,
	Destroying=1, AncestryChanged=1, TouchLongPress=1, FocusLost=1, Heartbeat=1, RenderStepped=1, Completed=1,
	OnClientEvent=1, OnServerEvent=1, PlayerAdded=1, PlayerRemoving=1, MouseMoved=1, TouchTap=1, TouchMoved=1, TouchEnded=1, TouchStarted=1, TouchPinch=1, TouchPan=1, WindowFocused=1, WindowFocusReleased=1,  MouseButton2Down=1, MouseButton2Up=1 }

local ClassIs = {
	TextButton = { GuiButton=1, GuiObject=1, GuiBase2d=1, TextButton=1 },
	ImageButton = { GuiButton=1, GuiObject=1, ImageButton=1 },
	Frame = { GuiObject=1, Frame=1 }, ScrollingFrame = { GuiObject=1, ScrollingFrame=1 },
	TextLabel = { GuiObject=1, TextLabel=1 }, ImageLabel = { GuiObject=1, ImageLabel=1 },
	TextBox = { GuiObject=1, TextBox=1 },
}

local function newInstance(class)
	local inst = { ClassName = class, Name = class, _children = {}, _attrs = {}, _props = {}, _parent = nil }
	local mt = {}
	local function setParent(self, p)
		if self._parent then
			for i, c in ipairs(self._parent._children) do if c == self then table.remove(self._parent._children, i) break end end
		end
		rawset(self, "_parent", p)
		if p then table.insert(p._children, self) end
	end
	function inst:IsA(c) return c == class or c == "Instance" or (ClassIs[class] and ClassIs[class][c]) or false end
	function inst:GetChildren() return table.clone(self._children) end
	function inst:GetDescendants()
		local out = {}
		local function walk(n) for _, c in ipairs(n._children) do table.insert(out, c); walk(c) end end
		walk(self); return out end
	function inst:FindFirstChild(n, rec)
		for _, c in ipairs(self._children) do if c.Name == n then return c end end
		if rec then for _, c in ipairs(self:GetDescendants()) do if c.Name == n then return c end end end
	end
	function inst:FindFirstChildOfClass(cn) for _, c in ipairs(self._children) do if c.ClassName == cn then return c end end end
	function inst:FindFirstChildWhichIsA(cn) for _, c in ipairs(self._children) do if c:IsA(cn) then return c end end end
	function inst:WaitForChild(n) return self:FindFirstChild(n) or error("WaitForChild timeout: "..n.." in "..self.Name, 2) end
	function inst:Destroy() rawset(self, "_destroyed", true); for _, c in ipairs(table.clone(self._children)) do c:Destroy() end; setParent(self, nil) end
	function inst:ClearAllChildren() for _, c in ipairs(table.clone(self._children)) do c:Destroy() end end
	function inst:SetAttribute(k, v) self._attrs[k] = v end
	function inst:GetAttribute(k) return self._attrs[k] end
	function inst:Clone() local n = newInstance(class); for k, v in pairs(self._props) do n[k] = v end; return n end
	function inst:IsDescendantOf(a) local p = self._parent while p do if p == a then return true end p = p._parent end return false end
	function inst:GetFullName() return self.Name end
	function inst:TweenSize() end function inst:TweenPosition() end
	function inst:Play() end function inst:Stop() end function inst:Pause() end
	inst.AbsoluteSize = {X=800,Y=600}; inst.AbsolutePosition = {X=0,Y=0}; inst.AbsoluteContentSize = {X=0,Y=0}
	mt.__index = function(t, k)
		local v = rawget(t, "_props")[k]
		if v ~= nil then return v end
		if k == "Parent" then return rawget(t, "_parent") end
		if SIGNALS[k] then local s = Signal(); t._props[k] = s; return s end
		if type(k) == "string" then
			for _, c in ipairs(rawget(t, "_children")) do if c.Name == k then return c end end
		end
		return nil
	end
	mt.__newindex = function(t, k, v)
		if k == "Parent" then setParent(t, v) return end
		if k == "Name" then rawset(t, "Name", v) return end
		t._props[k] = v
	end
	return setmetatable(inst, mt)
end

M.newInstance = newInstance
return M

end)()
local H = (function()
-- Builds the fake Roblox world + a module loader that mirrors Roblox require semantics.
local M = MOCK
local newInstance, Signal = M.newInstance, M.Signal


-- ───── datatypes ─────
local function vec2(x, y) return { X = x or 0, Y = y or 0 } end
local Vector2 = { new = vec2, zero = vec2(0,0) }
local Vector3 = { new = function(x,y,z) return {X=x or 0,Y=y or 0,Z=z or 0} end }
Vector3.zero = Vector3.new()
local UDim = { new = function(s, o) return { Scale = s or 0, Offset = o or 0 } end }
local UDim2Mt = {}
local function mk2(xs, xo, ys, yo)
	return setmetatable({ X = UDim.new(xs, xo), Y = UDim.new(ys, yo) }, UDim2Mt)
end
UDim2Mt.__add = function(a, b) return mk2(a.X.Scale + b.X.Scale, a.X.Offset + b.X.Offset, a.Y.Scale + b.Y.Scale, a.Y.Offset + b.Y.Offset) end
UDim2Mt.__sub = function(a, b) return mk2(a.X.Scale - b.X.Scale, a.X.Offset - b.X.Offset, a.Y.Scale - b.Y.Scale, a.Y.Offset - b.Y.Offset) end
local UDim2 = {
	new = function(xs, xo, ys, yo) return mk2(xs, xo, ys, yo) end,
	fromScale = function(x, y) return mk2(x, 0, y, 0) end,
	fromOffset = function(x, y) return mk2(0, x, 0, y) end,
}
local function color(r,g,b) local c = {R=r,G=g,B=b}
	function c:Lerp(o, a) return color(r+(o.R-r)*a, g+(o.G-g)*a, b+(o.B-b)*a) end return c end
local Color3 = { new = function(r,g,b) return color(r or 0,g or 0,b or 0) end,
	fromRGB = function(r,g,b) return color((r or 0)/255,(g or 0)/255,(b or 0)/255) end,
	fromHSV = function(h,s,v) return color(v or 0,v or 0,v or 0) end,
	fromHex = function() return color(0,0,0) end }
local function seqType(name) return { new = function(...) return { _t = name, ... } end } end
local ColorSequence = seqType("CS"); local NumberSequence = seqType("NS"); local NumberRange = seqType("NR")
local ColorSequenceKeypoint = seqType("CSK"); local NumberSequenceKeypoint = seqType("NSK")
local TweenInfo = { new = function(...) return { ... } end }
local Rect = { new = function(...) return { ... } end }
local Random = { new = function(seed)
	SIM_RNG_N = (SIM_RNG_N or 0) + 1
	local st = ((seed or ((SIM_SEED or 1) * 7919 + SIM_RNG_N * 104729))) % 2147483647; if st <= 0 then st = 1 end
	local function nxt() st = (st * 48271) % 2147483647; return st / 2147483647 end
	return { NextNumber = function(_, lo, hi) return (lo or 0) + nxt() * ((hi or 1) - (lo or 0)) end,
		NextInteger = function(_, lo, hi) return lo + math.floor(nxt() * (hi - lo + 1)) end }
end }
local CFrame = { new = function() return {} end, Angles = function() return {} end }

-- Enum: any Enum.X.Y resolves to a stable table
local Enum = setmetatable({}, { __index = function(t, k)
	local e = setmetatable({}, { __index = function(t2, k2)
		local item = { Name = k2, EnumType = k, Value = 0 }
		rawset(t2, k2, item); return item end })
	rawset(t, k, e); return e end })

-- ───── instances & services ─────
local Instance = { new = function(cn, parent) local i = newInstance(cn); if parent then i.Parent = parent end return i end }

local services = {}
local function svc(name, extra)
	local s = newInstance(name); s.Name = name
	for k, v in pairs(extra or {}) do rawset(s, k, v) end
	services[name] = s; return s
end
local Players = svc("Players")
local lp = newInstance("Player"); lp.Name = "Tester"; lp.UserId = 1
local pg = newInstance("PlayerGui"); pg.Name = "PlayerGui"; pg.Parent = lp
Players.LocalPlayer = lp
Players.PlayerAdded = Signal(); Players.PlayerRemoving = Signal()
