	rawset(r, "OnClientEvent", Signal()); rawset(r, "OnServerEvent", Signal())
	rawset(r, "FireServer", function(self, ...) M.fired = M.fired or {}; table.insert(M.fired, { n, ... }) end)
end
Remotes.Parent = RS

