return { resetCache = resetCache, game = game, RS = RS, SS = SS, load = load, sources = sources, services = services, player = lp, M = M,
	Signal = Signal, newInstance = newInstance, globals = globalsBase, vec2 = vec2 }

end)()
MOCK = H.M
local function path(p) for inst, info in pairs(H.sources) do if info.path == p then return inst end end end
local N = 1500
local function run(label, bonus, skipDraw, lowerFirstPts)
	local first = 0
	for g = 1, N do
		SIM_SEED, SIM_RNG_N = g * 31 + 7, 0
		H.resetCache()
		local Decks = H.load(path("ReplicatedStorage/Shared/Decks.lua"))
		local Match = H.load(path("ServerStorage/Modules/Match.lua"))
		local a, b = { IsBot = true, Name = "A" }, { IsBot = true, Name = "B" }
		local m = Match.new(a, b, Decks.Starter, Decks.Starter, "LEADER_LUNG", "LEADER_LUNG")
		local w; m.OnEnded = function(_, winner) w = winner; return {} end
		local orig = m.StartTurn
		m.StartTurn = function(self, p)
			if not self.firstPlayer then
				self.firstPlayer = p
				self.sides[self:Opponent(p)].bonusPoints = self.sides[self:Opponent(p)].bonusPoints + bonus
				if lowerFirstPts then self.sides[p].bonusPoints = self.sides[p].bonusPoints - lowerFirstPts end
				if skipDraw then
					local s, realDraw = self.sides[p], self.Draw
					self.Draw = function(me, side, c) if side == s then me.Draw = realDraw; return false end return realDraw(me, side, c) end
				end
			end
			return orig(self, p)
		end
		m:Start()
		for _ = 1, 12000 do if m.ended then break end MOCK.pump(1) end
		if w == m.firstPlayer then first += 1 end
		MOCK.pump(130)
	end
	print(("%-46s first-player win rate: %.1f%%"):format(label, 100 * first / N))
end
run("baseline", 0, false, 0)
run("P2 +2 pts", 2, false, 0)
run("P2 +3 pts", 3, false, 0)
run("P2 +4 pts", 4, false, 0)
run("P1 skip draw", 0, true, 0)
run("P1 skip draw + P2 +1 pt", 1, true, 0)
run("P1 skip draw + P2 +2 pts", 2, true, 0)
run("P1 -1 pt first turn", 0, false, 1)
run("P1 -1 pt + P2 +2 pts", 2, false, 1)
run("P1 skip draw + P1 -1pt", 0, true, 1)
