			for p in rel:gmatch("[^/]+") do table.insert(parts, p) end
			for i = 1, #parts - 1 do
				local nxt = cur:FindFirstChild(parts[i])
				if not nxt then nxt = newInstance("Folder"); nxt.Name = parts[i]; nxt.Parent = cur end
