local function readFile(p) local f = io.open(p, "r"); if not f then return nil end local s = f:read("*a"); f:close(); return s end
local function ls(dir) local p = io.popen('ls -1 "'..dir..'"'); local t = {}; for l in p:lines() do table.insert(t, l) end p:close(); return t end
local function isDir(p) local h = io.popen('[ -d "'..p..'" ] && echo y'); local r = h:read("*a"); h:close(); return r:find("y") ~= nil end

local sources = {}   -- instance -> {src=, path=}
local function mount(dir, parent)
	for _, name in ipairs(ls(dir)) do
		local full = dir.."/"..name
		if isDir(full) then
			local f = newInstance("Folder"); f.Name = name; f.Parent = parent; mount(full, f)
		elseif name:match("%.lua$") then
			local base = name:gsub("%.server%.lua$", ""):gsub("%.client%.lua$", ""):gsub("%.lua$", "")
			local kind = name:match("%.server%.lua$") and "Script" or name:match("%.client%.lua$") and "LocalScript" or "ModuleScript"
			local m = newInstance(kind); m.Name = base; m.Parent = parent
			sources[m] = { src = readFile(full), path = full }
		end
	end
end
local function sub(root, name) local f = newInstance("Folder"); f.Name = name; f.Parent = root; return f end
if isDir(REPO.."/ReplicatedStorage") then mount(REPO.."/ReplicatedStorage", RS) end
if isDir(REPO.."/ServerStorage") then mount(REPO.."/ServerStorage", SS) end


-- ───── module loader ─────
local globalsBase = { game=game, workspace=workspace, Instance=Instance, Vector2=Vector2, Vector3=Vector3, UDim=UDim, UDim2=UDim2,
	Color3=Color3, ColorSequence=ColorSequence, NumberSequence=NumberSequence, NumberRange=NumberRange,
	ColorSequenceKeypoint=ColorSequenceKeypoint, NumberSequenceKeypoint=NumberSequenceKeypoint, TweenInfo=TweenInfo,
	Rect=Rect, Random=Random, CFrame=CFrame, Enum=Enum, typeof=function(v)
		if type(v) == "table" then
			if v.ClassName then return "Instance" end
			if v.Scale ~= nil and v.Offset ~= nil then return "UDim" end
			if v.R and v.G and v.B then return "Color3" end
			if v.X and v.Y and not v.Z and type(v.X) == "number" then return "Vector2" end
			if v.X and v.Y and type(v.X) == "table" then return "UDim2" end
			if v.Connect then return "RBXScriptSignal" end
		end
		return type(v) end,
	warn = function(...) M.warnings = M.warnings or {}; table.insert(M.warnings, table.concat({...}, " ")) end,
	tick = os.clock, time = os.clock, os = os, string = string, table = table, math = math, pairs = pairs, ipairs = ipairs,
	next = next, select = select, type = type, tostring = tostring, tonumber = tonumber, pcall = pcall, xpcall = xpcall,
	error = error, assert = assert, unpack = table.unpack, setmetatable = setmetatable, getmetatable = getmetatable,
	rawget = rawget, rawset = rawset, rawequal = rawequal, print = print, utf8 = utf8, coroutine = coroutine, bit32 = bit32,
	buffer = buffer, newproxy = newproxy, tostring = tostring,
}

-- cooperative scheduler: task.spawn runs until first yield; task.wait yields (virtual clock); pump() advances time
local queue, now = {}, 0
local function resume(co, ...)
	local ok, e = coroutine.resume(co, ...)
	if not ok then M.taskErrors = M.taskErrors or {}; table.insert(M.taskErrors, tostring(e)) end
end
local function spawnFn(f, ...)
	local co = type(f) == "thread" and f or coroutine.create(f)
	resume(co, ...); return co
end
globalsBase.task = {
	wait = function(t)
		local co, ismain = coroutine.running()
		if ismain then return t or 0 end
		table.insert(queue, { at = now + (t or 0.03), co = co })
		coroutine.yield(); return t or 0.03 end,
	spawn = spawnFn,
	defer = function(f, ...) local a = {...}; local co = coroutine.create(f); table.insert(queue, { at = now, co = co, args = a }); return co end,
	delay = function(t, f, ...) local a = {...}; local co = coroutine.create(f); table.insert(queue, { at = now + (t or 0), co = co, args = a }); return co end,
	cancel = function(co) for i = #queue, 1, -1 do if queue[i].co == co then table.remove(queue, i) end end end,
}
globalsBase.wait = globalsBase.task.wait
globalsBase.spawn = globalsBase.task.spawn
function M.clock() return now end
function M.pump(dt, maxSteps)
	local target = now + (dt or 1); local steps = 0
	while steps < (maxSteps or 5000) do
		table.sort(queue, function(a, b) return a.at < b.at end)
		local nxt = queue[1]
		if not nxt or nxt.at > target then break end
		table.remove(queue, 1); now = math.max(now, nxt.at); steps += 1
		if coroutine.status(nxt.co) == "suspended" then resume(nxt.co, table.unpack(nxt.args or {})) end
	end
	now = target
end


local cache, loading = {}, {}
local function load(inst)
	if cache[inst] ~= nil then return cache[inst] end
	local info = sources[inst]; if not info then error("require: not a module: "..tostring(inst and inst.Name), 3) end
	if loading[inst] then error("cyclic require: "..inst.Name, 3) end
	loading[inst] = true
	local env = setmetatable({ script = inst, require = function(m) return load(m) end }, { __index = globalsBase })
	local fn, err = loadstring(info.src, "="..info.path)
	if not fn then loading[inst] = nil; error("SYNTAX "..info.path..": "..tostring(err), 0) end
	setfenv(fn, env)
	local ok, res = pcall(fn)
	loading[inst] = nil
	if not ok then error("LOAD "..info.path..": "..tostring(res), 0) end
	cache[inst] = res == nil and true or res
	return cache[inst]
end

local function resetCache() for k in pairs(cache) do cache[k] = nil end end
return { resetCache = resetCache, game = game, RS = RS, SS = SS, load = load, sources = sources, services = services, player = lp, M = M,
	Signal = Signal, newInstance = newInstance, globals = globalsBase, vec2 = vec2 }
]]
SOURCES["tools/sim/mock.lua"] = [[
-- Minimal mock-Roblox runtime (Luau). Loads repo modules with their own env.
local ROOT = ...
local M = {}

local function Signal()
	local s = { _h = {} }
	function s:Connect(f) local c = { f = f, Connected = true }; table.insert(self._h, c)
		return { Disconnect = function() c.Connected = false end } end
	function s:Once(f) return self:Connect(f) end
	function s:Wait() return end
	function s:Fire(...)
		for _, c in ipairs(table.clone(self._h)) do
			if c.Connected then
				local co = coroutine.create(c.f)
				local ok, e = coroutine.resume(co, ...)
				if not ok then M.handlerErrors = M.handlerErrors or {}; table.insert(M.handlerErrors, tostring(e)) end
			end
		end
	end
	return s
end
M.Signal = Signal

local SIGNALS = { Activated=1, MouseButton1Click=1, MouseButton1Down=1, MouseButton1Up=1, MouseButton2Click=1,
	MouseEnter=1, MouseLeave=1, InputBegan=1, InputEnded=1, InputChanged=1, Changed=1, ChildAdded=1, ChildRemoved=1,
	Destroying=1, AncestryChanged=1, TouchLongPress=1, FocusLost=1, Heartbeat=1, RenderStepped=1, Completed=1,
	OnClientEvent=1, OnServerEvent=1, PlayerAdded=1, PlayerRemoving=1, MouseMoved=1, TouchTap=1, TouchMoved=1, TouchEnded=1, TouchStarted=1, TouchPinch=1, TouchPan=1, WindowFocused=1, WindowFocusReleased=1,  MouseButton2Down=1, MouseButton2Up=1 }

local ClassIs = {
	TextButton = { GuiButton=1, GuiObject=1, GuiBase2d=1, TextButton=1 },
	ImageButton = { GuiButton=1, GuiObject=1, ImageButton=1 },
	Frame = { GuiObject=1, Frame=1 }, ScrollingFrame = { GuiObject=1, ScrollingFrame=1 },
	TextLabel = { GuiObject=1, TextLabel=1 }, ImageLabel = { GuiObject=1, ImageLabel=1 },
	TextBox = { GuiObject=1, TextBox=1 },
}

local function newInstance(class)
	local inst = { ClassName = class, Name = class, _children = {}, _attrs = {}, _props = {}, _parent = nil }
	local mt = {}
	local function setParent(self, p)
		if self._parent then
			for i, c in ipairs(self._parent._children) do if c == self then table.remove(self._parent._children, i) break end end
		end
		rawset(self, "_parent", p)
		if p then table.insert(p._children, self) end
	end
	function inst:IsA(c) return c == class or c == "Instance" or (ClassIs[class] and ClassIs[class][c]) or false end
	function inst:GetChildren() return table.clone(self._children) end
	function inst:GetDescendants()
		local out = {}
		local function walk(n) for _, c in ipairs(n._children) do table.insert(out, c); walk(c) end end
		walk(self); return out end
	function inst:FindFirstChild(n, rec)
		for _, c in ipairs(self._children) do if c.Name == n then return c end end
		if rec then for _, c in ipairs(self:GetDescendants()) do if c.Name == n then return c end end end
	end
	function inst:FindFirstChildOfClass(cn) for _, c in ipairs(self._children) do if c.ClassName == cn then return c end end end
	function inst:FindFirstChildWhichIsA(cn) for _, c in ipairs(self._children) do if c:IsA(cn) then return c end end end
	function inst:WaitForChild(n) return self:FindFirstChild(n) or error("WaitForChild timeout: "..n.." in "..self.Name, 2) end
	function inst:Destroy() rawset(self, "_destroyed", true); for _, c in ipairs(table.clone(self._children)) do c:Destroy() end; setParent(self, nil) end
	function inst:ClearAllChildren() for _, c in ipairs(table.clone(self._children)) do c:Destroy() end end
	function inst:SetAttribute(k, v) self._attrs[k] = v end
	function inst:GetAttribute(k) return self._attrs[k] end
	function inst:Clone() local n = newInstance(class); for k, v in pairs(self._props) do n[k] = v end; return n end
	function inst:IsDescendantOf(a) local p = self._parent while p do if p == a then return true end p = p._parent end return false end
	function inst:GetFullName() return self.Name end
	function inst:TweenSize() end function inst:TweenPosition() end
	function inst:Play() end function inst:Stop() end function inst:Pause() end
	inst.AbsoluteSize = {X=800,Y=600}; inst.AbsolutePosition = {X=0,Y=0}; inst.AbsoluteContentSize = {X=0,Y=0}
	mt.__index = function(t, k)
		local v = rawget(t, "_props")[k]
		if v ~= nil then return v end
		if k == "Parent" then return rawget(t, "_parent") end
		if SIGNALS[k] then local s = Signal(); t._props[k] = s; return s end
		if type(k) == "string" then
			for _, c in ipairs(rawget(t, "_children")) do if c.Name == k then return c end end
		end
		return nil
	end
	mt.__newindex = function(t, k, v)
		if k == "Parent" then setParent(t, v) return end
		if k == "Name" then rawset(t, "Name", v) return end
		t._props[k] = v
	end
	return setmetatable(inst, mt)
end

M.newInstance = newInstance
return M
]]
SOURCES["tools/sim/remotes_block.lua"] = [[
-- Remotes (mirrors GameServer REMOTES list)
local Remotes = newInstance("Folder"); Remotes.Name = "Remotes"
M.handlers = {}
local RF = { "PlayCard", "Attack", "Queue", "GetStats", "GetProfile", "SaveDeck", "Gacha", "ClaimQuest", "GetFarms", "ClaimFarm", "UpgradeFarm" }
local RE = { "EndTurn", "Surrender", "StateUpdate", "GateRolled", "MatchEnded", "Notify", "ProfileChanged" }
for _, n in ipairs(RF) do
	local r = newInstance("RemoteFunction"); r.Name = n; r.Parent = Remotes
	rawset(r, "InvokeServer", function(self, ...) local h = M.handlers[n]; if h then return h(...) end return false, "NO_HANDLER" end)
end
for _, n in ipairs(RE) do
	local r = newInstance("RemoteEvent"); r.Name = n; r.Parent = Remotes
	rawset(r, "OnClientEvent", Signal()); rawset(r, "OnServerEvent", Signal())
	rawset(r, "FireServer", function(self, ...) M.fired = M.fired or {}; table.insert(M.fired, { n, ... }) end)
end
Remotes.Parent = RS

]]
SOURCES["tools/sim/t_comp.lua"] = [[
MOCK = H.M
local function path(p) for inst, info in pairs(H.sources) do if info.path == p then return inst end end end
local N = 1000
local function run(label, mutate)
	local first = 0
	for g = 1, N do
		SIM_SEED, SIM_RNG_N = g * 31 + 7, 0
		H.resetCache()
		local Decks = H.load(path("ReplicatedStorage/Shared/Decks.lua"))
		local Match = H.load(path("ServerStorage/Modules/Match.lua"))
		local a, b = { IsBot = true, Name = "A" }, { IsBot = true, Name = "B" }
		local m = Match.new(a, b, Decks.Starter, Decks.Starter, "LEADER_LUNG", "LEADER_LUNG")
		local w; m.OnEnded = function(_, winner) w = winner; return {} end
		mutate(m)
		for _ = 1, 12000 do if m.ended then break end MOCK.pump(1) end
		if w == m.firstPlayer then first += 1 end
		MOCK.pump(130)
	end
	print(("%-44s first-player win rate: %.1f%%"):format(label, 100 * first / N))
end
run("baseline", function(m) m:Start() end)
-- B: second player starts with +1 card
run("second player +1 starting card", function(m)
	local orig = m.StartTurn
	m.StartTurn = function(self, p)
		if not self.firstPlayer then
			self.firstPlayer = p
			local other = self:Opponent(p)
			self:Draw(self.sides[other], 1)
			self.firstPlayer = nil
		end
		return orig(self, p)
	end
	m:Start()
end)
-- C: second player gets +2 bonus points on their first turn
run("second player +2 points on first turn", function(m)
	local orig = m.StartTurn
	m.StartTurn = function(self, p)
		if not self.firstPlayer then self.firstPlayer = p; self.sides[self:Opponent(p)].bonusPoints = 2 end
		return orig(self, p)
	end
	m:Start()
end)
-- D: first player skips their first draw
run("first player skips first-turn draw", function(m)
	local orig = m.StartTurn
	local d = m.Draw
	m.StartTurn = function(self, p)
		if not self.firstPlayer then
			self.firstPlayer = p
			local s = self.sides[p]
			local realDraw = self.Draw
			self.Draw = function(me, side, c) if side == s and not me._skipped then me._skipped = true; return false end me.Draw = realDraw; return realDraw(me, side, c) end
		end
		return orig(self, p)
	end
	m:Start()
end)
]]
SOURCES["tools/sim/t_deck.lua"] = [[
local CardData = H.load(H.RS.Shared.CardData)
local Config = H.load(H.RS.Shared.Config)
local UIKit = H.load(H.RS.Shared.UI.UIKit)
local DeckBuilder = H.load(H.player.PlayerGui.Parent and H.sources and (function()
	for inst, info in pairs(H.sources) do if info.path:find("UIClient/DeckBuilder.lua") then return inst end end end)())

local cards, owned = {}, {}
local n = 0
for id, def in pairs(CardData) do
	if type(def) == "table" and def.Type and def.Type ~= "Leader" then cards[id] = def; owned[id] = 2; n += 1 end
end
print("cards:", n, "quota:", DeckBuilder.QUOTA.Character, DeckBuilder.QUOTA.Weapon, DeckBuilder.QUOTA.Spell)

local saved
local parent = H.newInstance("Frame")
local panelOk, panel = pcall(DeckBuilder.Open, parent, { Cards = cards, Owned = owned, Deck = {},
	OnSave = function(ids) saved = ids; return true end })
print("Open ok:", panelOk, panelOk and "" or panel)
if not panelOk then return end

local function findSave()
	for _, d in ipairs(panel:GetDescendants()) do
		if d.ClassName == "TextButton" then
			local face = d:FindFirstChild("Face"); local lbl = face and face:FindFirstChild("Label")
			if lbl and lbl.Text == "เซฟเด็ค!" then return d end
		end
	end
end
local save = findSave()
print("save button found:", save ~= nil)
if save then
	print("Disabled attr on EMPTY deck (expect true):", save:GetAttribute("Disabled"))
	save.Activated:Fire()
	print("saved after click on empty deck (expect nil):", saved)
end

-- ── positive path: build a legal 24-card deck and save ──
local Config2 = Config
local function legalDeck()
	local out, per = {}, { Character = 0, Weapon = 0, Spell = 0 }
	local shields = 0
	local ids = {}
	for id in pairs(cards) do table.insert(ids, id) end
	table.sort(ids)
	for _, id in ipairs(ids) do
		local d = cards[id]
		local isShield = d.Type == "Spell" and type(d.Effect) == "table" and d.Effect.Kind == "Shield"
		local copies = (Config.MAX_COPIES and Config.MAX_COPIES[d.Rarity]) or 1
		for _ = 1, math.min(copies, 2) do
			if per[d.Type] < DeckBuilder.QUOTA[d.Type] and not (isShield and shields >= (Config.MAX_SHIELDS_IN_DECK or 2)) then
				table.insert(out, id); per[d.Type] += 1; if isShield then shields += 1 end
			end
		end
	end
	return out, per
end
local deckIds, per = legalDeck()
print("legal deck size:", #deckIds, "C/W/S:", per.Character, per.Weapon, per.Spell)

local saved2
local parent2 = H.newInstance("Frame")
local panel2 = DeckBuilder.Open(parent2, { Cards = cards, Owned = owned, Deck = deckIds, OnSave = function(ids) saved2 = ids; return true end })
local save2
for _, d in ipairs(panel2:GetDescendants()) do
	if d.ClassName == "TextButton" then
		local f = d:FindFirstChild("Face"); local l = f and f:FindFirstChild("Label")
		if l and l.Text == "เซฟเด็ค!" then save2 = d end
	end
end
print("FULL deck -> Disabled (expect nil/false):", save2:GetAttribute("Disabled"))
save2.Activated:Fire()
print("saved count (expect " .. #deckIds .. "):", saved2 and #saved2)

-- failure path: OnSave returns false + msg, and OnSave throws
local parent3 = H.newInstance("Frame")
local panel3 = DeckBuilder.Open(parent3, { Cards = cards, Owned = owned, Deck = deckIds, OnSave = function() error("boom") end })
local sv3
for _, d in ipairs(panel3:GetDescendants()) do
	if d.ClassName == "TextButton" then local f = d:FindFirstChild("Face"); local l = f and f:FindFirstChild("Label"); if l and l.Text == "เซฟเด็ค!" then sv3 = d end end
end
local okc, err = pcall(function() sv3.Activated:Fire() end)
print("OnSave throws -> UI survives:", okc, err)
print("warnings:", M and M.warnings and #M.warnings or (MOCK.warnings and #MOCK.warnings or 0))
if MOCK.taskErrors then for _, e in ipairs(MOCK.taskErrors) do print("TASK ERR:", e) end end
for i, w in ipairs(MOCK.warnings or {}) do print("WARN " .. i .. ": " .. tostring(w)) end
]]
SOURCES["tools/sim/t_hud.lua"] = [[
local MatchHUD
for inst, info in pairs(H.sources) do if info.path:find("UIClient/MatchHUD.lua") then MatchHUD = H.load(inst) end end
local gui = H.newInstance("Frame")
local ok, hud = pcall(MatchHUD.new, gui, {})
print("MatchHUD.new:", ok, ok and "" or hud)
if not ok then return end
local function px(u, vw, vh) return u.X.Scale * vw + u.X.Offset, u.Y.Scale * vh + u.Y.Offset end
local VW, VH = 980, 310 -- short Studio viewport like the screenshot
local boxes = {}
local function add(name, g)
	local w, h = px(g.Size, VW, VH)
	local c = g:FindFirstChildOfClass("UISizeConstraint")
	if c then w = math.max(c.MinSize.X, math.min(c.MaxSize.X, w)); h = math.max(c.MinSize.Y, math.min(c.MaxSize.Y, h)) end
	local x, y = px(g.Position, VW, VH)
	x = x - g.AnchorPoint.X * w; y = y - g.AnchorPoint.Y * h
	boxes[#boxes + 1] = { name = name, x = x, y = y, w = w, h = h }
end
add("HP me", hud.hp.me.holder); add("HP opp", hud.hp.opp.holder); add("Points", hud.pointsHolder)
add("Skip", hud.skip); add("ShieldHint", hud.shieldHint)
for _, d in ipairs(gui:GetDescendants()) do if d.Name == "Timer" then add("Timer", d) end end
for _, b in ipairs(boxes) do print(string.format("%-10s x=%4d y=%4d w=%3d h=%3d", b.name, b.x, b.y, b.w, b.h)) end
local overlaps = 0
for i = 1, #boxes do for j = i + 1, #boxes do
	local a, b = boxes[i], boxes[j]
	if a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h then
		overlaps += 1; print("OVERLAP:", a.name, "x", b.name) end end end
print("viewport", VW .. "x" .. VH, "overlaps:", overlaps)
]]
